E["item:500-pound-chicken"] = {t="item",n="500 Pound Chicken",z="tanaris",s="Dirge, a goblin in Tanaris, sends you with a promised delicacy for Narain Soothfancy. The gnome is eager to receive it.",h="Dirge, a goblin in Tanaris, sends you with a promised delicacy for Narain Soothfancy.",sec={{t="A Goblin's Promise",b="In Tanaris, Dirge gives you the 500 Pound Chicken to carry to Narain Soothfancy. The goblin says he keeps his word, though he cannot imagine why a gnome would want such a meal. Narain soon supplies the answer: he digs into the enormous chicken and calls it the best he has ever tasted.",sp=0}},faq={{q="Who gives you the 500 Pound Chicken?",a="Dirge, a goblin, gives you the 500 Pound Chicken and says he is a goblin of his word.",al={"who gives chicken","dirge chicken","chicken giver"}},{q="Who is the chicken for?",a="The chicken is for Narain Soothfancy, a gnome in Tanaris.",al={"chicken for who","who wants it","narain chicken"}},{q="Why does Narain want a giant chicken?",a="Narain wants to eat it. He calls it the best chicken he has ever tasted.",al={"why chicken","gnome chicken","500 pound chicken why"},sp=1},{q="What happens when Narain gets the chicken?",a="Narain mashes his fists into the huge chicken, stuffs his face, and praises its taste.",al={"narain eats chicken","chicken ending","what happens to it"},sp=1},{q="Where does the 500 Pound Chicken go?",a="You take the 500 Pound Chicken to Narain Soothfancy in Tanaris.",al={"chicken location","where to take chicken","tanaris chicken"}}},kw={"500 pound chicken","chicken","dirge","gnome","goblin","narain soothfancy","tanaris"},rel={"quest:8587","npc:narain-soothfancy","zone:tanaris","quest:8728"},src={"Wowpedia: 500 Pound Chicken","Return to Narain"}}
E["item:a-carefully-packed-crate"] = {t="item",n="A Carefully-packed Crate",z="tanaris",s="A Carefully-packed Crate carries eggs from Tanaris to Erelas Ambersky in Rut’theran Village. The druid tends the eggs until they hatch and trains the young hippogryphs.",h="A Carefully-packed Crate carries eggs from Tanaris to Erelas Ambersky in Rut’theran Village.",sec={{t="The Shipment",b="Erelas Ambersky cares for the eggs in Rut’theran Village, a small village in southern Teldrassil. Once they hatch, he trains the young hippogryphs. In Tanaris, Curgle provides the shipment and asks you to carry the crate safely to him.",sp=0}},faq={{q="What is in the crate?",a="The Carefully-packed Crate holds eggs for Erelas Ambersky to tend until they hatch.",al={"crate contents","what's inside","crate eggs"}},{q="Who is Erelas Ambersky?",a="Erelas Ambersky is a druid in Rut’theran Village who cares for the eggs and trains the young hippogryphs.",al={"who's Erelas","Erelas","hippogryph druid"}},{q="Where does the crate go?",a="The crate goes to Erelas Ambersky in Rut’theran Village, a small village in southern Teldrassil.",al={"where to take crate","crate destination","Rut'theran delivery"}},{q="Who sends the shipment?",a="Curgle provides the shipment of eggs for Erelas Ambersky.",al={"who packed it","Curgle crate","where from"}},{q="Why are the eggs being sent?",a="Erelas tends the eggs until they hatch, then trains the young hippogryphs.",al={"why eggs","hippogryph eggs","what's the shipment for"}}},ang={["class:Druid"]="As a druid, you know the work of tending living things. Erelas cares for the eggs and trains the young hippogryphs."},kw={"carefully-packed crate","crate","curgle","eggs","erelas ambersky","hippogryph","hippogryph eggs","rut'theran village","tanaris"},rel={"quest:3022","zone:tanaris","zone:feralas","subzone:rut-theran-village","topic:druid"},src={"Wowpedia: A Carefully-packed Crate","Handle With Care (Tanaris)"}}
E["item:acceptable-basilisk-sample"] = {t="item",n="Acceptable Basilisk Sample",z="tanaris",s="An acceptable basilisk sample is one of the specimens sought for Chief Engineer Bilgewhizzle's field testing in Tanaris. It is collected with a Field Testing Kit while the kit's power lasts.",h="An acceptable basilisk sample is one of the specimens sought for Chief Engineer Bilgewhizzle's field testing...",sec={{t="Desert Specimen",b="The Field Testing Kit needs eight basilisk samples, along with samples from hyenas and scorpids. In Tanaris, an untested basilisk sample may prove acceptable when examined with the kit. The kit glows and vibrates once its power source is active, and Bilgewhizzle allows two hours to gather the data before the power runs out.",sp=0}},faq={{q="What is an Acceptable Basilisk Sample?",a="It is a basilisk specimen accepted by the Field Testing Kit during Bilgewhizzle's field testing in Tanaris.",al={"basilisk sample","acceptable sample","good basilisk specimen"}},{q="Who needs the basilisk samples?",a="Chief Engineer Bilgewhizzle in Gadgetzan needs eight acceptable basilisk samples for his field testing.",al={"who wants samples","Bilgewhizzle samples","who needs basilisk"}},{q="How do I get an acceptable sample?",a="Use an untested basilisk sample while carrying the Field Testing Kit; the specimen may be judged acceptable.",al={"get basilisk sample","sample test","how sample works"}},{q="Why does the kit glow and vibrate?",a="The kit glows and vibrates after its power source is activated, showing that it is working.",al={"kit glowing","vibrating kit","what is kit doing"}},{q="How long does the kit have power?",a="Bilgewhizzle says the powered kit gives you two hours to collect the Tanaris data before the samples are lost.",al={"kit timer","power runs out","two hours"}}},ang={["profession:Engineering"]="As an engineer, you may recognize Bilgewhizzle's powered testing kit as a device built to gather field data in the Tanaris desert."},kw={"acceptable basilisk sample","basilisk","chief engineer bilgewhizzle","field testing kit","gadgetzan","power source","tanaris","tanaris field sampling"},rel={"quest:654","item:field-testing-kit","item:acceptable-hyena-sample","item:acceptable-scorpid-sample","subzone:gadgetzan","zone:tanaris"},src={"Wowpedia: Acceptable Basilisk Sample","Tanaris Field Sampling"}}
E["item:acceptable-hyena-sample"] = {t="item",n="Acceptable Hyena Sample",z="tanaris",s="An acceptable hyena sample is data gathered with Chief Engineer Bilgewhizzle’s field testing kit in Tanaris. It is one part of his survey of the desert’s wildlife.",h="An acceptable hyena sample is data gathered with Chief Engineer Bilgewhizzle’s field testing kit in Tanaris.",sec={{t="Desert Samples",b="In Tanaris, the field testing kit can yield an acceptable hyena sample from an untested one. Chief Engineer Bilgewhizzle needs eight hyena samples, alongside samples from basilisks and scorpions, for his survey. The kit’s power source gives you two hours to gather the data before it is lost.",sp=0}},faq={{q="What is an acceptable hyena sample?",a="An acceptable hyena sample is data gathered from an untested hyena sample with Bilgewhizzle’s field testing kit.",al={"hyena sample","acceptable sample hyena"}},{q="Who needs hyena samples?",a="Chief Engineer Bilgewhizzle in Gadgetzan needs eight acceptable hyena samples for his Tanaris field survey.",al={"who wants hyena samples","Bilgewhizzle sample"}},{q="How many hyena samples does Bilgewhizzle need?",a="Bilgewhizzle needs eight acceptable hyena samples, as well as eight each from basilisks and scorpions.",al={"hyena sample count","how many samples"}},{q="Why is there a time limit?",a="The field testing kit’s power source gives you two hours to collect the data. If it runs out, the data inside is lost.",al={"kit power limit","data lost"}}},kw={"acceptable hyena sample","chief engineer bilgewhizzle","field sampling","field testing kit","gadgetzan","hyena","tanaris"},rel={"quest:654","zone:tanaris","subzone:gadgetzan","item:field-testing-kit","item:acceptable-basilisk-sample","item:acceptable-scorpid-sample"},src={"Wowpedia: Acceptable Hyena Sample","Tanaris Field Sampling"}}
E["item:acceptable-scorpid-sample"] = {t="item",n="Acceptable Scorpid Sample",z="tanaris",s="An acceptable scorpid sample is data gathered with a Field Testing Kit in Tanaris. Chief Engineer Bilgewhizzle needs it with the other samples for his field study.",h="An acceptable scorpid sample is data gathered with a Field Testing Kit in Tanaris.",sec={{t="Desert Data",b="The Field Testing Kit gathers scorpid data in Tanaris for Chief Engineer Bilgewhizzle of Gadgetzan. An acceptable sample is one kind of data he needs alongside basilisk and hyena samples. Once the collection is complete, the kit goes back to Bilgewhizzle so he can remove its power source.",sp=0}},faq={{q="What is an acceptable scorpid sample?",a="An acceptable scorpid sample is data gathered from a scorpid with the Field Testing Kit in Tanaris.",al={"scorpid sample","acceptable scorpid","scorpion data"}},{q="Who needs the scorpid samples?",a="Chief Engineer Bilgewhizzle in Gadgetzan needs the scorpid samples, along with basilisk and hyena samples.",al={"who wants samples","bilgewhizzle samples","who needs scorpid data"}},{q="What is the sample used for?",a="The sample provides data for Chief Engineer Bilgewhizzle's field study in Tanaris.",al={"why sample scorpids","scorpid testing","what's the data for"}},{q="What happens to the kit after sampling?",a="Bring the Field Testing Kit back to Chief Engineer Bilgewhizzle in Gadgetzan so he can remove its power source.",al={"return the kit","kit power source","what to do with testing kit"}}},kw={"acceptable scorpid sample","bilgewhizzle","field testing kit","gadgetzan","sample","scorpid","scorpion","tanaris"},rel={"quest:654","item:field-testing-kit","item:acceptable-basilisk-sample","item:acceptable-hyena-sample","zone:tanaris","subzone:gadgetzan"},src={"Wowpedia: Acceptable Scorpid Sample","Tanaris Field Sampling"}}
E["item:caliph-scorpidsting-s-head"] = {t="item",n="Caliph Scorpidsting's Head",z="tanaris",s="The Gadgetzan Water Company seeks proof against Caliph Scorpidsting and offers a bounty through Chief Engineer Bilgewhizzle in Gadgetzan.",h="The Gadgetzan Water Company seeks proof against Caliph Scorpidsting and offers a bounty through Chief...",sec={{t="A Bounty in Gadgetzan",b="The Gadgetzan Water Company names Caliph Scorpidsting as leader of the Wastewander outlaws. It accuses his band of murdering its employees, stealing its resources, and seizing its property. The company offers a high bounty for proof of his demise. Chief Engineer Bilgewhizzle receives the head in Gadgetzan.",sp=0}},faq={{q="Who wants Caliph Scorpidsting's head?",a="The Gadgetzan Water Company offers a bounty for proof of Caliph Scorpidsting's demise. Chief Engineer Bilgewhizzle receives the head in Gadgetzan.",al={"who wants the head","who pays for it"}},{q="Why is Scorpidsting wanted?",a="The Gadgetzan Water Company accuses Caliph Scorpidsting and his Wastewander outlaws of murdering its employees, stealing its resources, and seizing its property.",al={"why wanted","what did he do"}},{q="Who is Caliph Scorpidsting?",a="Caliph Scorpidsting leads the Wastewander outlaws in Tanaris.",al={"scorpidsting","wastewander leader"}},{q="Where do I bring his head?",a="Bring Caliph Scorpidsting's Head to Chief Engineer Bilgewhizzle in Gadgetzan.",al={"where to take head","bilgewhizzle"},sp=1},{q="What is the head proof of?",a="The head is proof of Caliph Scorpidsting's demise, which the Gadgetzan Water Company seeks for its bounty.",al={"proof of demise","why the head"},sp=1}},kw={"bilgewhizzle","bounty","caliph scorpidsting","gadgetzan water company","scorpidsting's head","tanaris","wanted","wastewander"},rel={"quest:2781","subzone:gadgetzan","zone:tanaris"},src={"Wowpedia: Caliph Scorpidsting's Head","WANTED: Caliph Scorpidsting"}}
E["item:centipaar-insect-parts"] = {t="item",n="Centipaar Insect Parts",z="tanaris",s="Centipaar Insect Parts are gathered from silithid in Tanaris's Noxious Lair. Alchemist Pestlezugg in Gadgetzan studies them to learn more about the creatures draining the area's water pools.",h="Centipaar Insect Parts are gathered from silithid in Tanaris's Noxious Lair.",sec={{t="Parts from the Lair",b="The Centipaar silithid in Noxious Lair yield parts for Alchemist Pestlezugg's investigation. He studies them in Gadgetzan, seeking to learn what these creatures are.",sp=0}},faq={{q="What are Centipaar Insect Parts?",a="Centipaar Insect Parts are pieces gathered from silithid in Tanaris's Noxious Lair for Alchemist Pestlezugg to study.",al={"centipaar parts","insect parts","bug parts"}},{q="Where do I get Centipaar Insect Parts?",a="The Centipaar silithid in Noxious Lair yield the parts Alchemist Pestlezugg seeks.",al={"where parts","get centipaar parts","noxious lair parts"}},{q="Who wants these insect parts?",a="Alchemist Pestlezugg in Gadgetzan wants Centipaar Insect Parts so he can study the creatures from Noxious Lair.",al={"who needs parts","pestlezugg parts","alchemist wants"}},{q="Why are the bugs being investigated?",a="The silithid are draining the water pools that once lay where Noxious Lair now stands, and Pestlezugg wants to learn what they are.",al={"why bugs","water pools","silithid investigation"}}},kw={"alchemist pestlezugg","centipaar","gadgetzan","insect parts","noxious lair","silithid","tanaris","water pools"},rel={"quest:82","quest:32","subzone:noxious-lair","subzone:gadgetzan","zone:tanaris"},src={"Wowpedia: Centipaar Insect Parts","Noxious Lair Investigation"}}
E["item:field-testing-kit"] = {t="item",n="Field Testing Kit",z="tanaris",s="The Field Testing Kit is a modified device used to test creature tissue in Tanaris. It needs a goblin power source to hold its data during fieldwork.",h="The Field Testing Kit is a modified device used to test creature tissue in Tanaris.",sec={{t="A Kit for Samples",b="Apothecary Zinge sends you to Tanaris with the Field Testing Kit to examine basilisks, hyenas, and scorpids. Chief Engineer Bilgewhizzle in Gadgetzan supplies the power source it needs. Once activated, the kit glows and vibrates, and its stored data must be brought back before the power runs out.",sp=0}},faq={{q="What is the Field Testing Kit for?",a="The Field Testing Kit examines the tissue of basilisks, hyenas, and scorpids in Tanaris.",al={"what does the kit do","field testing device"}},{q="Who gives me the kit?",a="Apothecary Zinge provides the Field Testing Kit for the work in Tanaris.",al={"where get the kit","zinge kit"}},{q="Who powers the kit?",a="Chief Engineer Bilgewhizzle in Gadgetzan can provide a power source for the modified kit.",al={"power source for kit","bilgewhizzle power"}},{q="Why does the kit glow and vibrate?",a="The kit glows and vibrates when its power source is activated, which means it is working as planned.",al={"kit glowing","kit buzzing"}},{q="How long does the kit hold its data?",a="The power source gives you two hours to collect the needed data. If it runs out, the data inside is ruined.",al={"kit time limit","power run out"}}},ang={["profession:Engineering"]="As an engineer, the modified kit and its separate power source show Gadgetzan's practical approach to field experiments."},kw={"apothecary zinge","basilisk sample","bilgewhizzle","field testing kit","hyena sample","power source","scorpid sample","tanaris"},rel={"quest:243","quest:654","npc:apothecary-zinge","subzone:gadgetzan","item:acceptable-basilisk-sample","item:acceptable-hyena-sample","item:acceptable-scorpid-sample"},src={"Wowpedia: Field Testing Kit","Tanaris Field Sampling","Into the Field"}}
E["item:firebeard-s-head"] = {t="item",n="Firebeard's Head",z="tanaris",s="Firebeard’s Head is the proof demanded for Andre Firebeard’s warrant at Steamwheedle Port. The port’s law allows his head to stand in for him at trial.",h="Firebeard’s Head is the proof demanded for Andre Firebeard’s warrant at Steamwheedle Port.",sec={{t="A Binding Warrant",b="Security Chief Bilgewhizzle accepts Andre Firebeard’s head as a proxy for his hearing. The warrant names the pirate for crimes against Steamwheedle and Gadgetzan. Once you bring the head to the port, Bilgewhizzle treats the contract as fulfilled and offers payment for your service.",sp=0}},faq={{q="Why does the warrant ask for his head?",a="The warrant says Andre Firebeard’s head may serve as his proxy if he is dead or unable to attend his hearing. Security Chief Bilgewhizzle accepts it at Steamwheedle Port.",al={"andre head warrant","why his head","firebeard head"}},{q="Who is Andre Firebeard?",a="Andre Firebeard is a pirate wanted for crimes against Steamwheedle and Gadgetzan.",al={"andre firebeard","firebeard pirate","who is andre"}},{q="Who takes Firebeard’s Head?",a="Security Chief Bilgewhizzle takes Andre Firebeard’s head at Steamwheedle Port.",al={"who wants the head","bilgewhizzle head","where bring andre head"}},{q="Where is Steamwheedle Port?",a="Steamwheedle Port lies on the coast of Tanaris. Andre Firebeard’s warrant is posted there.",al={"steamwheedle location","tanaris port","where is the port"}}},kw={"andre firebeard","firebeard's head","gadgetzan","pirate","security chief bilgewhizzle","steamwheedle port","tanaris","wanted"},rel={"quest:2875","subzone:steamwheedle-port","zone:tanaris","subzone:gadgetzan","topic:pirate"},src={"Wowpedia: Firebeard's Head","WANTED: Andre Firebeard"}}
E["item:frozen-ectoplasm"] = {t="item",n="Frozen Ectoplasm",z="tanaris",s="Mux Manascrambler needs Frozen Ectoplasm from Winterspring’s restless Highborne spirits. It is one of three spectral substances he seeks for his work with the dead.",h="Mux Manascrambler needs Frozen Ectoplasm from Winterspring’s restless Highborne spirits.",sec={{t="Winter Spirits",b="Near Winterspring’s lake, Anguished and Suffering Highborne leave Frozen Ectoplasm behind. Mux Manascrambler asks you to gather it with an Ectoplasmic Distiller, alongside Scorched Ectoplasm from Silithus and Stable Ectoplasm from the Eastern Plaguelands. He hopes the three substances will let him reach souls that have not wholly left this world.",sp=0}},faq={{q="Where do I find Frozen Ectoplasm?",a="Anguished and Suffering Highborne near the lake in Winterspring leave Frozen Ectoplasm behind.",al={"frozen ectoplasm location","where frozen ectoplasm","ectoplasm winterspring"}},{q="What is Frozen Ectoplasm for?",a="Mux Manascrambler needs it for Hunting for Ectoplasm, which calls for three kinds of ectoplasm gathered with an Ectoplasmic Distiller.",al={"frozen ectoplasm use","what's it for","ectoplasm purpose"}},{q="Who wants Frozen Ectoplasm?",a="Mux Manascrambler in Gadgetzan wants Frozen Ectoplasm, along with Scorched and Stable Ectoplasm.",al={"mux ectoplasm","who needs it","mux manascrambler"}},{q="Why does Mux want ectoplasm?",a="Mux hopes to use the otherworldly energies in the ectoplasm to reach souls that have not wholly left this world.",al={"why ectoplasm","mux's plan","reach souls"}},{q="What spirits leave Frozen Ectoplasm?",a="The Anguished and Suffering Highborne spirits of Winterspring leave Frozen Ectoplasm.",al={"ectoplasm from what","highborne ectoplasm","frozen spirit drops"}}},ang={["profession:Engineering"]="As an engineer, you may recognize Mux’s Ectoplasmic Distiller as his device for gathering spectral substances."},kw={"anguished highborne","ectoplasm","ectoplasmic distiller","frozen ectoplasm","hunting for ectoplasm","mux manascrambler","suffering highborne","winterspring"},rel={"quest:8924","npc:mux-manascrambler","quest:8921","item:scorched-ectoplasm","item:stable-ectoplasm","zone:winterspring","zone:tanaris"},src={"Wowpedia: Frozen Ectoplasm","Hunting for Ectoplasm"}}
E["item:gahz-ridian-detector"] = {t="item",n="Gahz'ridian Detector",z="tanaris",s="The Gahz'ridian Detector is a device Marvon Rivetseeker devised to find the ornaments scattered across Tanaris. It helps him gather material for his studies of the troll-made carvings.",h="The Gahz'ridian Detector is a device Marvon Rivetseeker devised to find the ornaments scattered across...",sec={{t="A Desert Search",b="Marvon Rivetseeker made the Gahz'ridian Detector to help locate ornaments carved from Gahz'ridian. Trolls fashioned the ornaments long ago in the image of Gahz'rilla, whom they worshipped as a deity. The carvings lie across Tanaris, with many found near Broken Pillar, Eastmoon Ruins and Southmoon Ruins.",sp=0}},faq={{q="Who made the Gahz'ridian Detector?",a="Marvon Rivetseeker, a scientist and treasure hunter in Tanaris, invented the Gahz'ridian Detector.",al={"who made detector","Marvon's device","detector inventor"}},{q="What does the detector find?",a="The Gahz'ridian Detector helps locate ornaments carved from Gahz'ridian, a material named for Gahz'rilla.",al={"what does detector find","find Gahz'ridian","detector purpose"}},{q="Who made the Gahz'ridian ornaments?",a="Trolls who once occupied Tanaris carved the Gahz'ridian ornaments long ago.",al={"who made ornaments","troll carvings","ornament origin"}},{q="Why are the ornaments shaped like Gahz'rilla?",a="The ornaments were modeled after Gahz'rilla, a hydra the trolls worshipped as a deity.",al={"why Gahz'rilla ornaments","hydra carvings","Gahz'rilla idol"}},{q="Where can I find Gahz'ridian ornaments?",a="Gahz'ridian ornaments lie throughout Tanaris, especially around Broken Pillar, Eastmoon Ruins and Southmoon Ruins.",al={"where ornaments","Gahz'ridian locations","ornaments Tanaris"}}},kw={"broken pillar","eastmoon ruins","gahz'ridian","gahz'ridian detector","gahz'ridian ornament","gahz'rilla","marvon rivetseeker","southmoon ruins","tanaris"},rel={"quest:3161","item:gahz-ridian-ornament","zone:tanaris","subzone:broken-pillar","subzone:eastmoon-ruins","subzone:southmoon-ruins","quest:2770","topic:troll"},src={"Wowpedia: Gahz'ridian Detector","Gahz'ridian (quest)"}}
E["item:gahz-ridian-ornament"] = {t="item",n="Gahz'ridian Ornament",z="tanaris",s="Gahz'ridian Ornaments are carved relics scattered across Tanaris. Marvon Rivetseeker studies them for clues to the trolls who once lived here.",h="Gahz'ridian Ornaments are carved relics scattered across Tanaris.",sec={{t="Carved Relics",b="Marvon Rivetseeker seeks Gahz'ridian Ornaments across Tanaris. He says the trolls who once occupied this desert carved them in the likeness of Gahz'rilla, the hydra they worshipped. The ornaments are made from a substance Marvon calls Gahz'ridian, named for that revered creature. He has gathered some already and wants more for his studies.",sp=0}},faq={{q="What are Gahz'ridian Ornaments?",a="Gahz'ridian Ornaments are carvings made by the trolls who once lived in Tanaris. They depict Gahz'rilla, a hydra the trolls worshipped.",al={"gahz'ridian","what is gahz'ridian","ornament meaning"}},{q="Who wants the ornaments?",a="Marvon Rivetseeker, a scientist and treasure hunter in Tanaris, wants Gahz'ridian Ornaments for his studies.",al={"who wants gahz'ridian","marvon ornaments","where take ornaments"}},{q="Where can I find Gahz'ridian Ornaments?",a="The ornaments are scattered across Tanaris, with many around Broken Pillar, Eastmoon Ruins, and Southmoon Ruins.",al={"gahz'ridian locations","where ornaments","gahz'ridian ruins"}},{q="What is Gahz'rilla?",a="Gahz'rilla is a hydra the trolls of Tanaris worshipped as a deity. The ornaments are carved in its likeness.",al={"gahz'rilla meaning","hydra god","troll deity"}},{q="What is the detector for?",a="Marvon Rivetseeker invented the Gahz'ridian Detector to help find the ornaments scattered through Tanaris.",al={"gahz'ridian detector","ornament finder","how find gahz'ridian"}}},kw={"broken pillar","detector","eastmoon ruins","gahz'ridian","gahz'rilla","marvon rivetseeker","ornament","southmoon ruins","tanaris","trolls"},rel={"zone:tanaris","quest:3161","item:gahz-ridian-detector","quest:2770","subzone:broken-pillar","subzone:eastmoon-ruins","subzone:southmoon-ruins"},src={"Wowpedia: Gahz'ridian Ornament","Gahz'ridian (quest)"}}
E["item:gorishi-queen-brain"] = {t="item",n="Gorishi Queen Brain",z="tanaris",s="The Gorishi Queen Brain is a specimen taken from the queen in the Slithering Scar. Researchers in Gadgetzan want it to study the silithid and the force that may control them.",h="The Gorishi Queen Brain is a specimen taken from the queen in the Slithering Scar.",sec={{t="A Mind to Study",b="Researchers in Gadgetzan seek the Gorishi Queen Brain after the Gorishi Hive Queen is summoned from her chamber in southern Un'Goro Crater. They suspect the silithid may answer to a malign intelligence, and hope the queen's brain will help them understand it. Their findings may reveal more about the hive than its queen alone.",sp=0}},faq={{q="What is the Gorishi Queen Brain?",a="The Gorishi Queen Brain is a specimen taken from the Gorishi Hive Queen for study by researchers in Gadgetzan.",al={"queen brain","gorishi brain","what is this brain"}},{q="Where does the Gorishi Queen Brain come from?",a="It comes from the Gorishi Hive Queen in the Slithering Scar, in southern Un'Goro Crater.",al={"where brain from","queen brain location","gorishi queen"}},{q="Why do researchers want the queen's brain?",a="Researchers in Gadgetzan hope the brain will help them understand the silithid and the malign intelligence they suspect may control them.",al={"why need brain","what for brain","study the queen"}},{q="How is the Gorishi Hive Queen summoned?",a="A Gorishi Queen Lure used on a crystal in the hive's hatcheries is meant to draw out the queen.",al={"summon queen","gorishi lure","how get queen out"}},{q="Is the queen the only silithid presence?",a="The researchers doubt that the Gorishi Hive Queen marks the full extent of the silithid presence.",al={"more silithid","silithid still here","is this all"}}},kw={"gadgetzan","gorishi","gorishi hive queen","gorishi queen brain","hive crystal","malign intelligence","silithid","slithering scar","un'goro crater"},rel={"quest:4507","item:gorishi-queen-lure","subzone:slithering-scar","zone:ungoro","zone:tanaris","quest:32"},src={"Wowpedia: Gorishi Queen Brain","Pawn Captures Queen"}}
E["item:gorishi-queen-lure"] = {t="item",n="Gorishi Queen Lure",z="tanaris",s="The Gorishi Queen Lure is a tool used to draw the Gorishi Hive Queen from her chamber in Un'Goro Crater. Researchers in Gadgetzan need the queen's brain to study the silithid.",h="The Gorishi Queen Lure is a tool used to draw the Gorishi Hive Queen from her chamber in Un'Goro Crater.",sec={{t="A Hive Stirred",b="In the Gorishi Hive of Un'Goro Crater, a crystal is thought to attune the silithid across their hive network. The lure is used on that crystal to draw out the queen. Researchers in Gadgetzan seek her brain for study, fearing a malign intelligence may control the silithid.",sp=0}},faq={{q="What does the Gorishi Queen Lure do?",a="The Gorishi Queen Lure is used on a crystal in the Gorishi Hive to draw out the Gorishi Hive Queen.",al={"queen lure use","gorishi lure purpose","how lure works"}},{q="Where is the lure used?",a="The lure is used on a crystal in the hatcheries of the Gorishi Hive in Un'Goro Crater.",al={"where use queen lure","lure location","gorishi hive where"}},{q="Who provided the lure?",a="Researchers in Gadgetzan provide the Gorishi Queen Lure so the queen can be drawn out for study.",al={"who gave lure","where did lure come from","gadgetzan lure"}},{q="Why do researchers want the queen's brain?",a="The researchers need the Gorishi Hive Queen's brain to study the silithid and investigate whether a malign intelligence controls them.",al={"why queen brain","gorishi brain reason","what is brain for"}},{q="What is the crystal in the hive?",a="The crystal is believed to attune the silithid across their hive network.",al={"hive crystal","silithid crystal","what crystal does"}}},kw={"gadgetzan","gorishi","gorishi hive","gorishi queen lure","hive crystal","queen","queen brain","silithid","un'goro crater"},rel={"quest:4507","item:gorishi-queen-brain","zone:ungoro","subzone:gadgetzan","quest:32"},src={"Wowpedia: Gorishi Queen Lure","Pawn Captures Queen"}}
E["item:insect-analysis-report"] = {t="item",n="Insect Analysis Report",z="tanaris",s="The Insect Analysis Report carries urgent findings about a spreading threat in Tanaris. Senior Surveyor Fizzledowser has it copied so the warning can reach others.",h="The Insect Analysis Report carries urgent findings about a spreading threat in Tanaris.",sec={{t="A Warning from Tanaris",b="In Gadgetzan, Senior Surveyor Fizzledowser asks that the report be shared widely. Alchemist Pestlezugg believes everyone who can read should know of the danger. Fizzledowser agrees to make a copy for you to carry to your allegiance.",sp=0},{t="The Scholar in the Drag",b="In Orgrimmar, Zilzibin Drumlore studies Azeroth's life forms and history. He recognizes the creatures described in the report as silithid, and warns that they could consume the Tanaris desert rapidly. He calls them tools of a threat facing both Horde and Alliance.",sp=1}},faq={{q="What is the Insect Analysis Report?",a="The Insect Analysis Report describes the silithid, a grave threat spreading from Tanaris.",al={"insect report","analysis report","what's in the report"}},{q="Who wrote the report?",a="Alchemist Pestlezugg in Gadgetzan prepared the report, and Senior Surveyor Fizzledowser copies it for wider distribution.",al={"who made report","Fizzledowser report","where'd report come from"}},{q="Why does Fizzledowser make a copy?",a="Alchemist Pestlezugg asks for a copy so the warning can be distributed among your allegiance.",al={"why copy report","get a duplicate","share the report"}},{q="Who is Zilzibin Drumlore?",a="Zilzibin Drumlore is a troll scholar in Orgrimmar who studies Azeroth's life forms and history.",al={"who's Zil","Zilzibin backstory","troll scholar"}},{q="What creatures does the report describe?",a="Zilzibin identifies the creatures in the report as silithid, which threaten Tanaris and both the Horde and Alliance.",al={"what insects","silithid report","what are the bugs"}}},ang={["faction:Horde"]="The report is meant to warn your allegiance about the silithid, a threat Zilzibin Drumlore says faces both Horde and Alliance.",["faction:Alliance"]="The report's warning concerns the silithid, which Zilzibin Drumlore identifies as a threat to both Alliance and Horde."},kw={"fizzledowser","gadgetzan","insect analysis report","insect part analysis","pestlezugg","silithid","tanaris","zilzibin drumlore"},rel={"quest:110","zone:tanaris","subzone:gadgetzan","npc:senior-surveyor-fizzledowser","zone:orgrimmar","subzone:drag","quest:32"},src={"Wowpedia: Insect Analysis Report","Rise of the Silithid (Horde)","Insect Part Analysis (2)"}}
E["item:laden-dew-gland"] = {t="item",n="Laden Dew Gland",z="tanaris",s="A Laden Dew Gland holds water gathered by a dew collector in Tanaris. Marin Noggenfogger in Gadgetzan wants one to ease his thirst.",h="A Laden Dew Gland holds water gathered by a dew collector in Tanaris.",sec={{t="Water for Marin",b="Southwest of Gadgetzan, Thistleshrub Valley is home to dew collectors that store water in special glands. Marin Noggenfogger asks you to bring him a Laden Dew Gland, hoping it will quench his terrible thirst.",sp=0}},faq={{q="What is a Laden Dew Gland?",a="A Laden Dew Gland is a water-filled organ carried by dew collectors in Thistleshrub Valley.",al={"dew gland","laden gland"}},{q="Who wants the gland?",a="Marin Noggenfogger in Gadgetzan wants a Laden Dew Gland to try to quench his thirst.",al={"who needs dew gland","marin gland"}},{q="Where do I find a Laden Dew Gland?",a="Thistleshrub Dew Collectors in Thistleshrub Valley, southwest of Gadgetzan, carry Laden Dew Glands.",al={"dew gland location","where gland tanaris"}},{q="Why does Marin want it?",a="Marin hopes the water stored in the gland will make a drink that quenches his terrible thirst.",al={"marin thirsty","why dew gland"}}},kw={"dew collector","dew gland","laden dew gland","marin noggenfogger","tanaris","thistleshrub valley"},rel={"quest:2605","item:thistleshrub-dew","subzone:thistleshrub-valley","subzone:gadgetzan","zone:tanaris"},src={"Wowpedia: Laden Dew Gland","The Thirsty Goblin"}}
E["item:magma-core-classic"] = {t="item",n="Magma Core",z="tanaris",s="The Magma Core is the heart of Magma Lord Bokk, an elemental in the Burning Steppes. Mux Manascrambler needs its steady heat to power an extra-dimensional ghost revealer.",h="The Magma Core is the heart of Magma Lord Bokk, an elemental in the Burning Steppes.",sec={{t="A Heart of Heat",b="Magma Lord Bokk dwells in the Burning Steppes, south of Blackrock Mountain. His Magma Core holds an endless supply of heat. Mux Manascrambler in Gadgetzan seeks it to keep ectoplasm active and power an extra-dimensional ghost revealer.",sp=0}},faq={{q="What is the Magma Core?",a="The Magma Core is the heart of Magma Lord Bokk, a mighty elemental in the Burning Steppes. It holds a powerful supply of heat.",al={"magma core","bokk's heart"}},{q="Who wants the Magma Core?",a="Mux Manascrambler in Gadgetzan wants the Magma Core to power an extra-dimensional ghost revealer.",al={"who needs magma core","mux power source"}},{q="Where is Magma Lord Bokk?",a="Magma Lord Bokk can be found in the Burning Steppes, south of Blackrock Mountain.",al={"where's bokk","bokk location"}},{q="Why does Mux need it?",a="Mux needs a stable, portable source of energy to keep ectoplasm active and power his extra-dimensional ghost revealer.",al={"why magma core","ghost revealer power"}}},ang={["profession:Engineering"]="As an engineer, you may recognize why Mux wants a portable source of power: he means to use the Magma Core to run an extra-dimensional ghost revealer."},kw={"bokk","burning steppes","ectoplasm","gadgetzan","ghost revealer","magma core","magma lord bokk","mux manascrambler","portable power source"},rel={"quest:8925","subzone:blackrock-mountain","zone:burningsteppes","subzone:gadgetzan","zone:tanaris"},src={"Wowpedia: Magma Core (Classic)","A Portable Power Source"}}
E["item:meridith-s-love-letter"] = {t="item",n="Meridith's Love Letter",z="tanaris",s="Meridith's Love Letter carries a message from Meridith to Narain Soothfancy in Tanaris. It is a small plea born from a meeting after a flying machine crashed.",h="Meridith's Love Letter carries a message from Meridith to Narain Soothfancy in Tanaris.",sec={{t="A Message for Narain",b="After rescuing Narain Soothfancy from a crashed flying machine, Meridith asks you to carry her letter to him. She has fallen in love with the gnome and hopes he will hear her feelings.",sp=0},{t="Narain's Reply",b="Narain recoils when he learns who sent the letter. Meridith is a fish, he protests, and he is a gnome; he sees no way their love could work.",sp=1}},faq={{q="Who wrote Meridith's Love Letter?",a="Meridith wrote the letter for Narain Soothfancy, the gnome she rescued from a crashed flying machine.",al={"who wrote the letter","meridith letter","love letter author"}},{q="Who is the letter for?",a="The letter is for Narain Soothfancy, a gnome in Tanaris.",al={"who gets the letter","letter for narain","deliver to who"}},{q="Why does Meridith send a letter?",a="Meridith believes she has fallen in love with Narain and wants him to know how she feels.",al={"why letter","meridith loves who","meridith's message"}},{q="How did Meridith meet Narain?",a="Meridith rescued Narain from the wreckage of a crashed flying machine.",al={"where did they meet","narain wreck","crashed flying machine"}},{q="What does Narain say about the letter?",a="Narain says Meridith is a fish and he is a gnome, so he believes they could never be together.",al={"narain's reaction","does narain love meridith","fish and gnome"},sp=1}},ang={["race:Gnome"]="As a gnome, you carry Meridith's feelings to Narain Soothfancy, a fellow gnome who is startled by her message."},kw={"fish","flying machine","gnome","love letter","meridith","narain soothfancy","tanaris"},rel={"quest:8599","npc:narain-soothfancy","quest:8597","zone:tanaris"},src={"Wowpedia: Meridith's Love Letter","Love Song for Narain"}}
E["item:pestlezugg-s-un-goro-report"] = {t="item",n="Pestlezugg's Un'Goro Report",z="tanaris",s="Pestlezugg's Un'Goro Report carries his latest findings from Gadgetzan to leaders in Darnassus or Orgrimmar. He hopes they will heed the silithid threat and help confront it.",h="Pestlezugg's Un'Goro Report carries his latest findings from Gadgetzan to leaders in Darnassus or Orgrimmar.",sec={{t="A Report from Gadgetzan",b="In Gadgetzan, Pestlezugg sends his latest findings about the silithid to someone who can reach the leaders. The report travels to Gracina Spiritmight at the Temple of the Moon in Darnassus, or to Zilzibin Drumlore in Orgrimmar. Pestlezugg believes the danger is too great for Gadgetzan to face alone.",sp=0},{t="Heeding the Warning",b="Gracina and Zilzibin both fear that hatred between the Alliance and Horde blinds their leaders to the silithid threat. Gracina says the Alliance dismisses dangers that do not come from the Horde, while the Horde's leaders are divided by conflicting advice. Both recipients urge continued effort against the silithid.",sp=1}},faq={{q="Who wrote the report?",a="Pestlezugg, who works in Gadgetzan, wrote the report about his latest findings on the silithid.",al={"who is pestlezugg","pestlezugg report","report author"}},{q="What is in Pestlezugg's report?",a="The report carries Pestlezugg's latest findings on the silithid threat.",al={"what does report say","silithid report","report contents"}},{q="Where is the report sent?",a="The report is carried to Gracina Spiritmight at the Temple of the Moon in Darnassus, or to Zilzibin Drumlore in Orgrimmar.",al={"where take report","report destination","where does it go"}},{q="Why does Pestlezugg send it?",a="Pestlezugg believes Gadgetzan cannot face the silithid threat alone and hopes leaders can act on his findings.",al={"why send report","why does pestlezugg need help","gadgetzan needs help"}},{q="What does Gracina think of the warning?",a="Gracina says the Alliance overlooks threats that do not come from the Horde, and she urges continued effort against the silithid.",al={"gracina on silithids","alliance response","why alliance ignores threat"}},{q="How does the Horde respond?",a="Zilzibin says the Horde is distracted by conflicting advice, though he believes Thrall might act if the facts reached him.",al={"horde response","thrall and silithids","zilzibin report"}}},ang={["faction:Alliance"]="As an Alliance traveler, you carry Pestlezugg's warning to Gracina Spiritmight in Darnassus, where she hopes her leaders will take the silithid threat seriously.",["faction:Horde"]="As a Horde traveler, you bring Pestlezugg's warning to Zilzibin Drumlore in Orgrimmar, in the hope that Thrall may hear the facts."},kw={"calm before the storm","darnassus","gadgetzan","gracina spiritmight","orgrimmar","pestlezugg","silithid","un'goro report","zilzibin drumlore"},rel={"quest:4508","zone:tanaris","zone:darnassus","zone:orgrimmar","quest:32"},src={"Wowpedia: Pestlezugg's Un'Goro Report","Calm Before the Storm (Alliance)","Calm Before the Storm (Horde)"}}
E["item:ransom-letter"] = {t="item",n="Ransom Letter",z="tanaris",s="The Ransom Letter is a threat from the thieves holding Narain’s book in Tanaris. Its cut-and-pasted words demand money and a meeting alone.",h="The Ransom Letter is a threat from the thieves holding Narain’s book in Tanaris.",sec={{t="A Cut-Out Threat",b="Narain’s missing book brings a ransom demand to Tanaris. The letter’s words are cut from different typefaces and glued onto parchment. It promises the book will be returned if the demands are met, then sets out detailed instructions across three pages. The message ends with a blunt order: bring the money and come alone.",sp=0},{t="Narain’s Anger",b="When Narain reads the ransom letter, his face turns bright red. The gnome vows to teach the kidnappers what it means to meddle with a psychic. His stolen book has become a matter of anger as well as payment.",sp=1}},faq={{q="Who wrote the ransom letter?",a="The letter does not name its writer. It says that the kidnappers have Narain’s book and demands money in exchange.",al={"letter writer","who sent it","ransom note author"}},{q="Whose book was stolen?",a="The book belongs to Narain, a gnome in Tanaris.",al={"who owns the book","narain book","stolen book"}},{q="What does the letter demand?",a="The kidnappers demand money and order the recipient to come alone.",al={"what do they want","ransom demand","bring money"}},{q="Why is the letter made from cut-out words?",a="Its text is made from different typefaces glued onto parchment. The letter gives no reason for this method.",al={"typeface ransom note","cut and paste note","weird letter"}},{q="How does Narain react?",a="Narain’s face turns bright red, and he vows to teach the kidnappers a lesson.",al={"narain angry","gnome reaction","what does narain say"},sp=1}},ang={["race:Gnome"]="As a gnome, you may recognize Narain’s pride in his psychic abilities. The stolen book and ransom threat leave him furious."},kw={"gnome","narain","psychic","ransom","ransom letter","ransom note","stolen book","tanaris"},rel={"quest:8598","zone:tanaris","topic:gnome"},src={"Wowpedia: Ransom Letter","RAnS0m"}}
E["item:scorched-ectoplasm"] = {t="item",n="Scorched Ectoplasm",z="tanaris",s="Scorched Ectoplasm is spectral matter gathered from tortured night elf spirits in Silithus. Mux Manascrambler needs it for his work with the dead.",h="Scorched Ectoplasm is spectral matter gathered from tortured night elf spirits in Silithus.",sec={{t="A Scorched Trace",b="In Silithus, the tortured spirits of druids and Sentinels yield Scorched Ectoplasm. Mux Manascrambler, a goblin engineer in Gadgetzan, seeks it alongside other forms of ectoplasm. He believes their strange energies can reach souls that remain near the living world.",sp=0}},faq={{q="What is Scorched Ectoplasm?",a="It is spectral matter taken from the tortured night elf spirits of Silithus.",al={"scorched ectoplasm","what's scorched ectoplasm","ectoplasm item"}},{q="Where does Scorched Ectoplasm come from?",a="Tortured Druids and Tortured Sentinels in Silithus yield Scorched Ectoplasm.",al={"where scorched ectoplasm","scorched ectoplasm location","where get it"}},{q="Why does Mux Manascrambler want it?",a="Mux Manascrambler hopes to use the otherworldly energies in ectoplasm to reach souls that remain near the living world.",al={"why mux wants ectoplasm","mux ectoplasm","what's mux doing"}},{q="What are the other kinds of ectoplasm?",a="Frozen Ectoplasm comes from highborne spirits in Winterspring, while Stable Ectoplasm comes from ghosts and banshees in the Eastern Plaguelands.",al={"other ectoplasms","frozen and stable ectoplasm","ectoplasm types"}},{q="Where can I find Mux Manascrambler?",a="Mux Manascrambler can be found in Gadgetzan, in Tanaris.",al={"where is mux","mux location","gadgetzan goblin"}}},ang={["profession:Engineering"]="As an engineer, you may recognize the Ectoplasmic Distiller as Mux Manascrambler's device for gathering spectral matter."},kw={"ectoplasm","ectoplasmic distiller","gadgetzan","mux manascrambler","scorched ectoplasm","silithus","tortured druid","tortured sentinel"},rel={"quest:8924","quest:8921","item:frozen-ectoplasm","item:stable-ectoplasm","zone:silithus","subzone:gadgetzan"},src={"Wowpedia: Scorched Ectoplasm","Hunting for Ectoplasm"}}
E["item:scrimshank-s-surveying-gear"] = {t="item",n="Scrimshank's Surveying Gear",z="tanaris",s="Scrimshank's Surveying Gear lies beneath the sands of Tanaris, in the Gaping Chasm. Senior Surveyor Fizzledowser needs its findings to investigate the strange bugs in the desert.",h="Scrimshank's Surveying Gear lies beneath the sands of Tanaris, in the Gaping Chasm.",sec={{t="Beneath the Sands",b="In the Gaping Chasm of Tanaris, Scrimshank's Surveying Gear is all that may be found of the missing Junior Surveyor. His senior, Fizzledowser, sent him into the desert after reports of strange bugs. The machine carries Scrimshank's last records, which may help explain the danger facing Gadgetzan.",sp=0}},faq={{q="What is Scrimshank's Surveying Gear?",a="It is the surveying equipment of Junior Surveyor Scrimshank, found beneath Tanaris in the Gaping Chasm.",al={"scrimshank's gear","surveying machine","what is the gear"}},{q="Where is the surveying gear?",a="Scrimshank's Surveying Gear lies in the Gaping Chasm beneath Tanaris.",al={"gear location","where's scrimshank's stuff","gaping chasm gear"}},{q="Who was Scrimshank?",a="Junior Surveyor Scrimshank was Senior Surveyor Fizzledowser's assistant, sent to investigate strange bugs in the Gaping Chasm.",al={"junior surveyor","scrimshank backstory","who is scrimshank"}},{q="Why does Fizzledowser want the gear?",a="Fizzledowser hopes Scrimshank's records will help reveal what is happening with the strange bugs in the desert.",al={"why gear matters","fizzledowser wants it","what did it record"}}},kw={"fizzledowser","gaping chasm","goblin","junior surveyor","scrimshank","silithid","surveying gear","tanaris"},rel={"quest:10","quest:32","npc:senior-surveyor-fizzledowser","subzone:gaping-chasm","zone:tanaris","topic:goblin"},src={"Wowpedia: Scrimshank's Surveying Gear","The Scrimshank Redemption"}}
E["item:sealed-venom-container"] = {t="item",n="Sealed Venom Container",z="tanaris",s="The Sealed Venom Container holds venom gathered from poisonous creatures in Silithus. In Gadgetzan, an engineer seeks it for work on a device that can speak with the dead.",h="The Sealed Venom Container holds venom gathered from poisonous creatures in Silithus.",sec={{t="Venom for Gadgetzan",b="Venom from Silithus is carried in the Sealed Venom Container. The sample is meant for an engineer in Gadgetzan who studies the supernatural. He is building a device to communicate with the dead, and the venom is payment for his work.",sp=0}},faq={{q="What is in the Sealed Venom Container?",a="The Sealed Venom Container holds venom collected from poisonous creatures in Silithus.",al={"what's in the venom container","venom container contents"}},{q="Where does the container go?",a="The container is meant for an engineer in Gadgetzan who is working on a device to speak with the dead.",al={"where to take venom","venom container destination"}},{q="Who wants the venom?",a="Mux Manascrambler, an engineer in Gadgetzan with an interest in the supernatural, wants the venom.",al={"who needs the container","mux venom"}},{q="Why does the engineer need venom?",a="The venom is payment for Mux Manascrambler's work on a device that can communicate with the dead.",al={"what's venom for","why give mux venom"}}},kw={"communicate with the dead","gadgetzan","mux manascrambler","sealed venom container","silithus","supernatural device","venom"},rel={"quest:8922","npc:mux-manascrambler","zone:silithus","subzone:gadgetzan"},src={"Wowpedia: Sealed Venom Container","A Supernatural Device (Alliance)","A Supernatural Device (Horde)"}}
E["item:skeleton-key-mold"] = {t="item",n="Skeleton Key Mold",z="tanaris",s="The Skeleton Key Mold shapes a thorium-and-bone key stem in Fire Plume Ridge’s lava. Apothecary Dithers needs the unfinished key for the fight against the Scourge in Andorhal.",h="The Skeleton Key Mold shapes a thorium-and-bone key stem in Fire Plume Ridge’s lava.",sec={{t="A Mold for the Key",b="Krinkle Goodsteel in Gadgetzan sells you the Skeleton Key Mold for work at Fire Plume Ridge in Un'Goro Crater. With two Thorium Bars, its bearer can use the mold beside the lava lake to fuse thorium and bone into an unfinished key stem. Krinkle says the lava's heat will do the forging, but the thorium must be supplied separately.",sp=0}},faq={{q="What is the Skeleton Key Mold for?",a="The Skeleton Key Mold shapes a thorium-and-bone key stem in the lava at Fire Plume Ridge.",al={"skeleton mold purpose","what mold do"}},{q="Who gives me the mold?",a="Krinkle Goodsteel in Gadgetzan sells you the Skeleton Key Mold for the work at Fire Plume Ridge. Apothecary Dithers is sorry you had to bear its fee.",al={"where get skeleton mold","dithers mold"}},{q="What do I need with the mold?",a="Two Thorium Bars are needed with the Skeleton Key Mold to forge the unfinished key stem.",al={"mold ingredients","thorium bars key"}},{q="Where is the mold used?",a="Use the Skeleton Key Mold beside the lava lake at the top of Fire Plume Ridge in Un'Goro Crater.",al={"where use skeleton mold","fire plume lava"}},{q="Why is Dithers making a skeleton key?",a="Dithers is preparing the key as part of the effort to strike at the Scourge in Andorhal.",al={"key for andorhal","why skeleton key"}}},ang={["faction:Horde"]="Dithers calls on you to help counter the Scourge, whose power holds Andorhal.",["profession:Mining"]="Thorium is needed to forge the key stem, though Krinkle Goodsteel leaves its acquisition to you."},kw={"andorhal","apothecary dithers","fire plume ridge","scourge","skeleton key","skeleton key mold","thorium","un'goro crater","unfinished skeleton key"},rel={"quest:5801","item:unfinished-skeleton-key","zone:ungoro","subzone:andorhal","topic:scourge","zone:tanaris"},src={"Wowpedia: Skeleton Key Mold","Fire Plume Forged (Horde)"}}
E["item:stable-ectoplasm"] = {t="item",n="Stable Ectoplasm",z="tanaris",s="Near the ghosts of the Eastern Plaguelands, an Ectoplasmic Distiller can gather Stable Ectoplasm. Mux Manascrambler needs it to reach spirits whose souls have not left this world.",h="Near the ghosts of the Eastern Plaguelands, an Ectoplasmic Distiller can gather Stable Ectoplasm.",sec={{t="Among the Ghosts",b="Mux Manascrambler asks for Stable Ectoplasm from the ghosts and banshees of the Eastern Plaguelands. He needs it alongside two other kinds of ectoplasm, gathered from Silithus and Winterspring. The distiller draws out the substance from nearby incorporeal undead. Northdale is a good place to find them.",sp=0}},faq={{q="What is Stable Ectoplasm?",a="Stable Ectoplasm is a substance gathered from ghosts and banshees in the Eastern Plaguelands with an Ectoplasmic Distiller.",al={"stable ectoplasm","what's ectoplasm","ghost stuff"}},{q="Who needs Stable Ectoplasm?",a="Mux Manascrambler in Gadgetzan needs Stable Ectoplasm, along with Scorched and Frozen Ectoplasm, for his work with the Ectoplasmic Distiller.",al={"who wants stable ectoplasm","mux ectoplasm","mux needs what"}},{q="Where can I find Stable Ectoplasm?",a="Ghosts and banshees in the Eastern Plaguelands yield Stable Ectoplasm. Northdale is a good place to find them.",al={"stable ectoplasm location","where ectoplasm","northdale ghosts"}},{q="Why does Mux want ectoplasm?",a="Mux hopes to use the otherworldly energy in the ectoplasm to reach spirits whose souls have not quite left this world.",al={"why ectoplasm","mux's plan","reach spirits"}}},ang={["profession:Engineering"]="Mux calls the Ectoplasmic Distiller a fine piece of engineering. His work shows how goblin contraptions can be put to use in studying the spirit world."},kw={"banshees","eastern plaguelands","ectoplasm","ectoplasmic distiller","gadgetzan","ghosts","mux manascrambler","northdale","stable ectoplasm"},rel={"quest:8924","quest:8921","item:frozen-ectoplasm","item:scorched-ectoplasm","npc:mux-manascrambler","zone:easternplaguelands","subzone:northdale"},src={"Wowpedia: Stable Ectoplasm","Hunting for Ectoplasm"}}
E["item:stoley-s-bottle"] = {t="item",n="Stoley's Bottle",z="tanaris",s="Stoley’s Bottle holds Steamwheedle bilge rum, sent to Booty Bay for Sea Wolf MacKinley. MacKinley is meant to taste the rum and judge its harshness.",h="Stoley’s Bottle holds Steamwheedle bilge rum, sent to Booty Bay for Sea Wolf MacKinley.",sec={{t="A Bitter Bottle",b="In Booty Bay, Sea Wolf MacKinley receives a bottle of Steamwheedle bilge rum from Stoley. MacKinley expects the drink to put his doubts about Booty Bay booze to rest. One taste proves the rum is terrible. It is thick as gravel and burns like lava, just as Stoley promised.",sp=0}},faq={{q="What is in Stoley’s Bottle?",a="Stoley’s Bottle contains Steamwheedle bilge rum.",al={"what's in the bottle","stoleys bottle contents"}},{q="Who is the bottle for?",a="Sea Wolf MacKinley in Booty Bay is meant to receive Stoley’s Bottle.",al={"who gets the bottle","deliver bottle to who"}},{q="Why does MacKinley want the bottle?",a="MacKinley wants to put his doubts about Booty Bay booze to rest by tasting Stoley’s Steamwheedle bilge rum.",al={"why booze for mackinley","mac kinley bottle"}},{q="What does the rum taste like?",a="MacKinley finds the rum terrible, thick as gravel and burning like lava.",al={"is the rum good","bilge rum taste"},sp=1},{q="Does the bottle settle Stoley’s debt?",a="After tasting the rum, MacKinley says Stoley can keep the money he owes. The drink is as harsh as Stoley promised.",al={"stoley debt bottle","does mac kinley forgive stoley"},sp=1}},kw={"booty bay","sea wolf mackinley","steamwheedle bilge rum","stoley","stoley's bottle","stoley's debt"},rel={"quest:2874","quest:2872","quest:2873","subzone:booty-bay"},src={"Wowpedia: Stoley's Bottle","Deliver to MacKinley"}}
E["item:stoley-s-shipment"] = {t="item",n="Stoley's Shipment",z="tanaris",s="Stoley’s Shipment is a stolen cargo of rum held by pirates in Lost Rigger Cove. Stoley wants it back to settle a wager with “Sea Wolf” MacKinley.",h="Stoley’s Shipment is a stolen cargo of rum held by pirates in Lost Rigger Cove.",sec={{t="Rum for a Wager",b="In Lost Rigger Cove, Stoley’s Shipment lies among the pirates’ stolen cargo. Captain Cuergo took Stoley’s last rum and keeps it in the walled pirate town. Stoley needs the shipment returned to Steamwheedle Port so he can settle his wager with “Sea Wolf” MacKinley in Booty Bay.",sp=0}},faq={{q="What is Stoley’s Shipment?",a="Stoley’s Shipment is a stolen cargo of rum that Captain Cuergo took from Stoley.",al={"stoleys shipment","stoley rum","stoley's cargo"}},{q="Who stole the rum?",a="Captain Cuergo stole Stoley’s last shipment of rum.",al={"who took stoleys rum","cuergo shipment","pirate stole rum"}},{q="Where is Stoley’s Shipment?",a="Stoley’s Shipment is kept in the walled pirate town at Lost Rigger Cove in Tanaris.",al={"where is the rum","lost rigger cargo","shipment location"}},{q="Why does Stoley want the shipment back?",a="Stoley wants the rum back so he can settle a wager with “Sea Wolf” MacKinley in Booty Bay.",al={"why return the rum","stoley wager","booze bet"}},{q="Who is MacKinley?",a="“Sea Wolf” MacKinley is the Booty Bay sailor with whom Stoley made a wager about Kalimdor’s rum.",al={"sea wolf","mackinley wager","booty bay guy"}}},kw={"booty bay","captain cuergo","lost rigger cove","rum","sea wolf mackinley","steamwheedle port","stoley","stoley's shipment","tanaris","wager"},rel={"quest:2872","quest:2874","subzone:lost-rigger-cove","subzone:steamwheedle-port","subzone:booty-bay","zone:tanaris","topic:pirate"},src={"Wowpedia: Stoley's Shipment","Stoley's Shipment (quest)"}}
E["item:stone-circle"] = {t="item",n="Stone Circle",z="tanaris",s="The Stone Circle is a serpent-marked stone kept in Marvon Rivetseeker’s workshop in Ratchet. It recalls a circular chamber in the Sunken Temple.",h="The Stone Circle is a serpent-marked stone kept in Marvon Rivetseeker’s workshop in Ratchet.",sec={{t="A Serpent Mark",b="Marvon Rivetseeker keeps the Stone Circle in his Ratchet workshop, where he asks you to retrieve it. He remembers finding a matching serpent symbol after escaping the Sunken Temple. The stone may help him recall more of what he saw there.",sp=0}},faq={{q="What is the Stone Circle?",a="The Stone Circle is a round stone marked with a serpent symbol, kept in Marvon Rivetseeker’s workshop in Ratchet.",al={"stone circle","what stone is this"}},{q="Where is the Stone Circle?",a="Marvon Rivetseeker has the Stone Circle in his workshop in Ratchet.",al={"where stone circle","find the stone"}},{q="Who wants the Stone Circle?",a="Marvon Rivetseeker asks you to retrieve the Stone Circle from his workshop in Ratchet.",al={"who wants this stone","marvon stone"}},{q="What does the serpent mark mean?",a="The serpent symbol matches the statues Marvon remembers in a circular chamber of the Sunken Temple.",al={"serpent symbol","snake mark meaning"}},{q="Why does Marvon want it?",a="Marvon hopes the stone will help him remember his escape from the Sunken Temple and tell him more about the place.",al={"why stone circle","marvon wants stone"}}},kw={"circular chamber","marvon rivetseeker","ratchet","serpent symbol","stone circle","sunken temple"},rel={"quest:3444","quest:3445","subzone:ratchet","zone:barrens","zone:tanaris"},src={"Wowpedia: Stone Circle","The Stone Circle"}}
E["item:super-sticky-tar"] = {t="item",n="Super Sticky Tar",z="tanaris",s="In northern Un'Goro Crater, tar from the beasts near the pits clings with unusual force. Tran'rek in Gadgetzan wants samples for a profitable glue idea.",h="In northern Un'Goro Crater, tar from the beasts near the pits clings with unusual force.",sec={{t="Tar from the Pits",b="Tran'rek asks you to gather tar from the beasts near the northern pits of Un'Goro Crater. Their skin holds chlorophyll, which he says makes the tar far stickier than ordinary tar. He hopes to turn the mixture into a useful glue.",sp=0}},faq={{q="Where does Super Sticky Tar come from?",a="You collect Super Sticky Tar from the tar beasts near the pits in northern Un'Goro Crater.",al={"where tar from","super sticky source"}},{q="Who wants the tar?",a="Tran'rek in Gadgetzan wants samples of Super Sticky Tar for his glue idea.",al={"who needs tar","tranrek tar"}},{q="Why is this tar so sticky?",a="Tran'rek says the beasts' chlorophyll-rich skin mixes with the tar and makes it unusually sticky.",al={"why sticky","sticky tar reason"}},{q="What does Tran'rek plan to do with it?",a="Tran'rek hopes to make a profitable glue from the tar and the chlorophyll in the beasts' skin.",al={"tranrek plan","what glue for"}}},kw={"chlorophyll","gadgetzan","glue","super sticky","super sticky tar","tar","tar beasts","tran'rek","un'goro crater"},rel={"quest:4504","zone:ungoro","subzone:gadgetzan","zone:tanaris"},src={"Wowpedia: Super Sticky Tar","Super Sticky (Classic)"}}
E["item:tapped-dowsing-widget"] = {t="item",n="Tapped Dowsing Widget",z="tanaris",s="A Tapped Dowsing Widget holds a water sample from a pool near Sandsorrow Watch in Tanaris. The Gadgetzan Water Company needs such surveys as the desert's wells grow scarce.",h="A Tapped Dowsing Widget holds a water sample from a pool near Sandsorrow Watch in Tanaris.",sec={{t="A Desert Sample",b="Senior Surveyor Fizzledowser sends you from Gadgetzan to test the pool near Sandsorrow Watch. The widget taps a sample for the Gadgetzan Water Company, which seeks free sources of water as nomads seize its wells. Yet the pool lies within sight of the trolls, and the survey brings a further danger from the desert.",sp=0}},faq={{q="What is the Tapped Dowsing Widget?",a="It is an Untapped Dowsing Widget that has collected a water sample from the pool near Sandsorrow Watch in Tanaris.",al={"tapped widget","water sample gadget","dowsing thing"}},{q="Where do I use the dowsing widget?",a="Use the Untapped Dowsing Widget at the pool near Sandsorrow Watch, west of Gadgetzan and south of Zul'Farrak.",al={"where use widget","pool location","sandsorrow water"}},{q="Who wants the water sample?",a="Senior Surveyor Fizzledowser in Gadgetzan asks you to bring the Tapped Dowsing Widget back to him for the Gadgetzan Water Company.",al={"who needs sample","fizzledowser","gadgetzan water company"}},{q="Why is the company surveying water?",a="The Gadgetzan Water Company seeks free water sources because nomads are seizing its wells.",al={"why survey water","no wells","water shortage"}},{q="What danger is near the pool?",a="Reports speak of strange bug-creatures sucking water from the desert. Surveyors may also be in sight of the trolls around the pool.",al={"pool danger","bugs at sandsorrow","creepy crawly"},sp=1}},kw={"fizzledowser","gadgetzan","sandsorrow watch","tanaris","tapped dowsing widget","untapped dowsing widget","water sample","water survey"},rel={"item:untapped-dowsing-widget","quest:992","npc:senior-surveyor-fizzledowser","subzone:sandsorrow-watch","zone:tanaris"},src={"Wowpedia: Tapped Dowsing Widget","Gadgetzan Water Survey"}}
E["item:thistleshrub-dew"] = {t="item",n="Thistleshrub Dew",z="tanaris",s="In Gadgetzan, Thistleshrub Dew leaves Marin Noggenfogger with a bitter taste and a new idea. He sends it to Sprinkle, hoping she can make the concoction easier to drink.",h="In Gadgetzan, Thistleshrub Dew leaves Marin Noggenfogger with a bitter taste and a new idea.",sec={{t="A Bitter Taste",b="Marin Noggenfogger has tried the Thistleshrub Dew, and it tastes terrible. Rather than abandon the idea, he asks you to take it to Sprinkle, his friend in Gadgetzan. She is an excellent chef, and Marin hopes she can give the drink some kick.",sp=0}},faq={{q="What is Thistleshrub Dew for?",a="Marin Noggenfogger wants Sprinkle to use the dew to make his unpleasant concoction easier to drink.",al={"thistleshrub dew use","what's the dew for"}},{q="Why does Marin want Sprinkle's help?",a="Marin finds the concoction tastes terrible and thinks Sprinkle, an excellent chef, can improve it.",al={"why sprinkle","marin needs help"}},{q="Who is Sprinkle?",a="Sprinkle is a chef in Gadgetzan and a friend of Marin Noggenfogger.",al={"sprinkle gadgetzan","who's sprinkle"}},{q="Where does Thistleshrub Dew go?",a="Marin asks you to take the Thistleshrub Dew to Sprinkle in Gadgetzan.",al={"dew delivery","where to take dew"}}},ang={["profession:Cooking"]="As a cook, you can see why Marin turns to Sprinkle: he hopes her skill will make the bitter concoction easier to drink."},kw={"bitter concoction","cooking","gadgetzan","marin noggenfogger","sprinkle","thistleshrub dew"},rel={"quest:2606","quest:2605","quest:2641","subzone:gadgetzan","zone:tanaris"},src={"Wowpedia: Thistleshrub Dew","In Good Taste"}}
E["item:unfinished-skeleton-key"] = {t="item",n="Unfinished Skeleton Key",z="tanaris",s="The Unfinished Skeleton Key is a thorium-and-bone key stem forged from a Skeleton Key Mold. It is part of preparations against the Scourge in Andorhal.",h="The Unfinished Skeleton Key is a thorium-and-bone key stem forged from a Skeleton Key Mold.",sec={{t="Forged in Fire",b="At Fire Plume Ridge in Un’Goro Crater, the Skeleton Key Mold and two bars of thorium are brought to the lava lake. Its heat fuses thorium and bone into the Unfinished Skeleton Key. The stem is then carried to Alchemist Arbington at Chillwind Point or Apothecary Dithers at the Bulwark, where work on the key continues.",sp=0}},faq={{q="What is the Unfinished Skeleton Key?",a="The Unfinished Skeleton Key is a stem of thorium and bone forged from the Skeleton Key Mold in Fire Plume Ridge’s lava. It is one part of a key being prepared for an assault on Andorhal.",al={"unfinished key","skeleton key stem","what is this key"}},{q="How is the key made?",a="The Skeleton Key Mold and two bars of thorium are taken to the lava lake atop Fire Plume Ridge in Un’Goro Crater. The heat fuses thorium and bone into the key stem.",al={"how make skeleton key","forge the key","where is it made"}},{q="Who takes the unfinished key?",a="Alchemist Arbington at Chillwind Point receives it for the Alliance, while Apothecary Dithers at the Bulwark receives it for the Horde.",al={"where bring key","arbington or dithers","who wants the key"}},{q="Why is the key being made?",a="The key is part of preparations for an assault on Andorhal, where the Scourge holds the ruined city.",al={"why make this key","key for andorhal","scourge key"}}},ang={["faction:Alliance"]="As an Alliance traveler, you can bring the forged stem to Alchemist Arbington at Chillwind Point as part of preparations against the Scourge in Andorhal.",["faction:Horde"]="As a Horde traveler, you can bring the forged stem to Apothecary Dithers at the Bulwark as part of preparations against the Scourge in Andorhal."},kw={"andorhal","araj the summoner","bone","fire plume ridge","lava lake","scourge","skeleton key mold","thorium","un'goro crater","unfinished skeleton key"},rel={"quest:5801","item:skeleton-key-mold","zone:ungoro","zone:tanaris","zone:westernplaguelands","subzone:bulwark","subzone:chillwind-point","subzone:andorhal"},src={"Wowpedia: Unfinished Skeleton Key","Fire Plume Forged (Alliance)","Fire Plume Forged (Horde)"}}
E["item:untapped-dowsing-widget"] = {t="item",n="Untapped Dowsing Widget",z="tanaris",s="The Untapped Dowsing Widget is a survey tool issued by the Gadgetzan Water Company. It is meant to test a desert pool near Sandsorrow Watch.",h="The Untapped Dowsing Widget is a survey tool issued by the Gadgetzan Water Company.",sec={{t="A Water Sample",b="Senior Surveyor Fizzledowser gives you the Untapped Dowsing Widget in Gadgetzan. Take it to the pool near Sandsorrow Watch and use it to test the water. Bring the tapped widget back to Fizzledowser.",sp=0},{t="The Desert Stirs",b="When you use the Untapped Dowsing Widget, Centipaar Tunnelers emerge nearby. Fizzledowser says these creatures have been seen sucking water from the desert, a troubling sign for the Gadgetzan Water Company.",sp=0}},faq={{q="What does the Untapped Dowsing Widget do?",a="The Untapped Dowsing Widget tests the pool near Sandsorrow Watch for water. Using it also draws out Centipaar Tunnelers.",al={"what's the widget for","dowsing tool purpose"}},{q="Where should I use the widget?",a="Use the Untapped Dowsing Widget at the pool near Sandsorrow Watch, west of Gadgetzan and south of Zul'Farrak.",al={"where is the water pool","widget location"}},{q="Who gave me the widget?",a="Senior Surveyor Fizzledowser gives you the Untapped Dowsing Widget for the Gadgetzan Water Company survey.",al={"who wants the water sample","Fizzledowser widget"}},{q="Why do Centipaar Tunnelers appear?",a="The Centipaar Tunnelers emerge when you use the widget. Fizzledowser says creatures like them have been sucking water from the desert.",al={"why bugs attack","centipaar from widget"}}},kw={"centipaar tunneler","dowsing widget","fizzledowser","gadgetzan water company","sandsorrow watch","untapped dowsing widget","water survey"},rel={"quest:992","item:tapped-dowsing-widget","npc:senior-surveyor-fizzledowser","subzone:sandsorrow-watch","zone:tanaris"},src={"Wowpedia: Untapped Dowsing Widget","Gadgetzan Water Survey"}}
E["item:violet-powder"] = {t="item",n="Violet Powder",z="tanaris",s="Sprinkle sends Violet Powder to Marin Noggenfogger in Gadgetzan, asking him to repay a favor. Marin is willing to try it.",h="Sprinkle sends Violet Powder to Marin Noggenfogger in Gadgetzan, asking him to repay a favor.",sec={{t="A Favor for Sprinkle",b="In Gadgetzan, Marin Noggenfogger receives Violet Powder from Sprinkle. Sprinkle asks you to deliver it and tell Marin that he owes a favor. Marin accepts the powder and says it could hardly make things worse.",sp=0}},faq={{q="What is Violet Powder for?",a="Sprinkle sends Violet Powder to Marin Noggenfogger in Gadgetzan, who agrees to try it.",al={"violet powder use","what's the powder for"}},{q="Who gives you the Violet Powder?",a="Sprinkle gives you Violet Powder and asks you to take it to Marin Noggenfogger.",al={"who gave me powder","sprinkle powder"}},{q="Who is supposed to get the powder?",a="Marin Noggenfogger in Gadgetzan is the one meant to receive Violet Powder.",al={"powder delivery","where take violet powder"}},{q="Why does Sprinkle say Marin owes her?",a="Sprinkle asks you to tell Marin that he owes her a favor; no further details are given.",al={"marin favor","sprinkle's favor"}}},kw={"delivery","favor","gadgetzan","marin noggenfogger","sprinkle","violet powder"},rel={"quest:2661","subzone:gadgetzan","quest:2662","quest:2641"},src={"Wowpedia: Violet Powder","Delivery for Marin"}}
E["item:violet-tragan"] = {t="item",n="Violet Tragan",z="tanaris",s="A violet mushroom from Valorwind Lake is Sprinkle’s secret ingredient in Gadgetzan. Cooked into a dish, it makes the food taste wonderful; raw, it is poisonous.",h="A violet mushroom from Valorwind Lake is Sprinkle’s secret ingredient in Gadgetzan.",sec={{t="A Taste from the Lake",b="Sprinkle in Gadgetzan sends you to the Hinterlands for a violet mushroom found only beneath Valorwind Lake. She says it transformed her sister’s terrible cooking into something she could stomach. Add it to a dish and, if properly cooked, it makes the food taste great. Raw, it poisons whoever eats it.",sp=0}},faq={{q="What is Violet Tragan?",a="Violet Tragan is a mushroom from beneath Valorwind Lake in the Hinterlands. Properly cooked, it makes food taste great.",al={"violet mushroom","what's violet tragan","violet tragan item"}},{q="Where can I find Violet Tragan?",a="Violet Tragan grows underwater in Valorwind Lake in the Hinterlands.",al={"where is violet tragan","violet tragan location","mushroom lake"}},{q="Why does Sprinkle want it?",a="Sprinkle in Gadgetzan uses Violet Tragan as her secret ingredient because, when properly cooked, it makes food taste great.",al={"why sprinkle wants mushroom","sprinkle ingredient","secret ingredient"}},{q="Is Violet Tragan safe to eat raw?",a="No. Raw Violet Tragan is poisonous.",al={"can i eat it raw","raw violet tragan","does it poison you"}}},ang={["profession:Cooking"]="As a cook, you can see why Sprinkle prizes Violet Tragan: properly cooked, it makes food taste great."},kw={"gadgetzan","hinterlands","poisonous","secret ingredient","sprinkle","valorwind lake","violet mushroom","violet tragan"},rel={"quest:2641","zone:tanaris","zone:hinterlands","subzone:gadgetzan"},src={"Wowpedia: Violet Tragan","Sprinkle's Secret Ingredient"}}
E["item:volcanic-ash"] = {t="item",n="Volcanic Ash",z="tanaris",s="Volcanic Ash gathers near lava in the Burning Steppes. Mux Manascrambler needs it to build a filter for his ectoplasmic distiller.",h="Volcanic Ash gathers near lava in the Burning Steppes.",sec={{t="Ash by the Lava",b="Lava pools and dried channels in the Burning Steppes leave Volcanic Ash on the ground. Mux Manascrambler in Gadgetzan needs twenty-five handfuls for a filter in his ectoplasmic distiller. He is gathering several costly materials for the device, which he hopes will harvest the fabric of death.",sp=0}},faq={{q="Where can I find Volcanic Ash?",a="Volcanic Ash lies near lava pools and dried lava channels in the Burning Steppes, mostly between Blackrock Mountain and Flame Crest.",al={"volcanic ash location","where ash","ash burning steppes"}},{q="What is Volcanic Ash used for?",a="Mux Manascrambler needs Volcanic Ash to build a filter for his ectoplasmic distiller.",al={"ash use","why volcanic ash","what's ash for"}},{q="Who needs Volcanic Ash?",a="Mux Manascrambler in Gadgetzan needs twenty-five Volcanic Ash for his ectoplasmic distiller.",al={"who wants ash","mux ash","ash for mux"}}},ang={["profession:Engineering"]="Mux Manascrambler is building an ectoplasmic distiller and needs Volcanic Ash for its filter, alongside a Delicate Arcanite Converter."},kw={"blackrock mountain","burning steppes","ectoplasmic distiller","filter","flame crest","lava","mux manascrambler","volcanic ash"},rel={"quest:8921","zone:burningsteppes","subzone:blackrock-mountain","subzone:flame-crest","npc:mux-manascrambler","zone:tanaris"},src={"Wowpedia: Volcanic Ash","The Ectoplasmic Distiller"}}
E["item:yeh-kinya-s-bramble"] = {t="item",n="Yeh'kinya's Bramble",z="tanaris",s="Yeh'kinya's Bramble draws out the spirits of vale screechers in Feralas. The troll scholar Yeh'kinya uses it to seek knowledge of an ancient power.",h="Yeh'kinya's Bramble draws out the spirits of vale screechers in Feralas.",sec={{t="A Spirit's Essence",b="At Steamwheedle Port, Yeh'kinya gives you the bramble for his search in Feralas. He says the vale screechers are kin to an ancient god, and their spirits are bound to him. When you wave the wand over a fallen screecher, its spirit appears. Gather the essence and bring it back to Yeh'kinya, who promises to tell you more.",sp=0}},faq={{q="What does Yeh'kinya's Bramble do?",a="Yeh'kinya's Bramble draws out the spirits of vale screechers in Feralas when waved over their fallen bodies.",al={"bramble wand","what's the bramble for"}},{q="Who gives you the bramble?",a="Yeh'kinya, a troll scholar at Steamwheedle Port, gives you the bramble for his search into the screecher spirits.",al={"who is yehkinya","where get bramble"}},{q="Why does Yeh'kinya want screecher spirits?",a="Yeh'kinya says vale screechers are kin to an ancient god and their spirits are linked to him. He seeks their essence to learn more.",al={"why screecher essence","screecher spirit purpose"}},{q="Where are the vale screechers?",a="Vale screechers dwell in southern and central Feralas.",al={"screechers location","where find screechers"}},{q="What does Yeh'kinya say about the old god?",a="Yeh'kinya speaks of an ancient troll prophecy concerning Hakkar, the Soulflayer, and says the essence of Hakkar holds great power.",al={"old god prophecy","hakkar and bramble"}}},ang={["race:Troll"]="Yeh'kinya cites an ancient prophecy among the trolls about Hakkar, the Soulflayer, and the danger his power may bring."},kw={"feralas","hakkar","screecher spirits","soulflayer","steamwheedle port","troll prophecy","vale screecher","yeh'kinya","yeh'kinya's bramble"},rel={"quest:3520","npc:yeh-kinya","zone:feralas","subzone:steamwheedle-port","topic:troll","zone:tanaris"},src={"Wowpedia: Yeh'kinya's Bramble","Screecher Spirits"}}
E["npc:dirge-quikcleave"] = {t="npc",n="Dirge Quikcleave",z="tanaris",s="Inside Gadgetzan's inn, Dirge Quikcleave welcomes travelers with food and drink. This goblin calls himself Azeroth's greatest living culinary artist, and chefs come to him when they are ready for artisan cooking.",h="Inside Gadgetzan's inn, Dirge Quikcleave welcomes travelers with food and drink.",sec={{t="Master of the Cleaver",b="In dusty Gadgetzan, Dirge Quikcleave serves food and drink to travelers crossing the Tanaris sands. He claims to be Azeroth's greatest living culinary artist, though his kitchen stands in a frontier tavern. When city cooking lessons are spent, trainers send their most promising students to him. His demanding recipes call for rare ingredients, from giant clam meat and eggs for his Clamlette creations to beasts from distant shores.",sp=0},{t="Exotic Flavors and Shady Favors",b="Dirge Quikcleave brings a gourmand's bravado and a goblin's eye for business to his work. Across Kalimdor, he keeps company with eccentric figures and pursues dangerous culinary ventures. Those who bring him fierce beast cuts can receive hearty recipes for champions facing perilous journeys. The monstrous chimaeroks of Feralas's Isle of Dread provide one such ingredient. Dirge's private dealings are best left unquestioned.",sp=0}},faq={{q="Who is Dirge Quikcleave?",a="Dirge Quikcleave is a goblin chef and provisioner inside the inn at Gadgetzan, Tanaris. Renowned as one of Azeroth's finest cooks, he teaches aspiring chefs to hone their craft toward artisan mastery.",al={"dirge quikcleave lore","who is dirge","gadgetzan chef"},it="identity"},{q="Where can Dirge Quikcleave be found?",a="Dirge Quikcleave can be found inside the tavern in Gadgetzan, a Steamwheedle cartel boomtown in the northern dunes of Tanaris.",al={"dirge location","where is dirge quikcleave","dirge inn"},it="place"},{q="Why do cooking trainers send adventurers to him?",a="Cooking trainers in the capital cities can take an apprentice only so far. When a cook reaches the expert threshold, they send that cook to Dirge in Gadgetzan through 'To Gadgetzan You Go!' to prove their worth and unlock artisan cooking.",al={"why visit dirge","artisan cooking quest","to gadgetzan you go"},it="purpose"},{q="What dishes is Dirge famous for?",a="Dirge Quikcleave is known for Clamlette Surprise, a savory omelet made from giant clam meat and eggs, hearty wolf steaks, and his potent Dirge's Kickin' Chimaerok Chops.",al={"dirge recipes","clamlette surprise","what does dirge cook"},it="fame"},{q="Whose side is Dirge Quikcleave on?",a="Dirge Quikcleave remains completely neutral, working out of the Steamwheedle Cartel's desert outpost of Gadgetzan. Like most goblins of the trade cartels, he serves anyone whose coin is good, willingly sharing his culinary mastery and peddling food to Alliance and Horde patrons alike.",al={"dirge quikcleave faction","is dirge horde or alliance","who does dirge quikcleave serve"},it="side",add="882c7cf6"},{q="What does Dirge Quikcleave want?",a="Dirge is driven by a passion for extreme and exotic cooking. He seeks rare, unusual meats and fresh ingredients from dangerous corners of the world to craft masterpieces like his famed clamlettes and chimaerok chops, always ready to turn daring harvests into culinary brilliance.",al={"dirge quikcleave goals","what does dirge quikcleave need","why does dirge want ingredients"},it="wants",add="6a938a01"},{q="Why is Dirge Quikcleave in Gadgetzan?",a="Operating out of the bustling inn at Gadgetzan places Dirge right at a major crossroads of daring explorers, monster hunters, and desert travelers. It offers the goblin chef a steady stream of patrons eager for hearty provisions and daring cooks seeking his artisan instruction.",al={"why is dirge in gadgetzan","dirge quikcleave tanaris why","why is dirge here"},it="why_here",add="97163837"},{q="Who is Dirge Quikcleave tied to?",a="Dirge makes his home among the Steamwheedle Cartel goblins of Gadgetzan, serving travelers and desert wayfarers from all walks of life. He also maintains connections with eccentric figures like Narain Soothfancy, who knows where to turn when exotic, high-end dishes are required.",al={"dirge quikcleave associates","who does dirge know","dirge connections"},it="ties",add="60da7b2e"}},ang={["profession:Cooking"]="As an ambitious chef, you can seek Dirge Quikcleave's artisan instruction. He tests your skill with his signature clamlette recipes before granting master status.",["race:Orc"]="As an aspiring Horde gourmand, you are sent straight from Orgrimmar by its trainers to seek Dirge's culinary tutelage in the Tanaris desert."},kw={"artisan cooking","clamlette surprise","cooking trainer","dirge quikcleave","gadgetzan","goblin chef","tanaris"},rel={"quest:6611","subzone:gadgetzan","zone:tanaris","subzone:isle-of-dread","topic:goblin"},src={"Dirge Quikcleave"}}
E["npc:mux-manascrambler"] = {t="npc",n="Mux Manascrambler",z="tanaris",s="In Gadgetzan, Mux Manascrambler turns his craft to spirits and occult forces. The goblin engineer studies what others cannot see.",h="In Gadgetzan, Mux Manascrambler turns his craft to spirits and occult forces.",sec={{t="A Tinkerer of the Unseen",b="Near the center of Gadgetzan, Mux Manascrambler works inside a building behind Driz Plunkbow and his clanking Butcherbots. The Steamwheedle Cartel trades in oil, guns, and salvage, but Mux pursues spirits and supernatural anomalies.\n\nHe builds strange devices to detect and distill spectral remnants, and to interact with them. His work brings goblin engineering into the unseen world of the dead.",sp=0}},faq={{q="Where can I find Mux Manascrambler?",a="Mux Manascrambler works in Gadgetzan, in northern Tanaris. Look inside a building near the center of town, behind Driz Plunkbow and the meat-carving Butcherbots.",al={"mux location","where is mux","mux manascrambler map"}},{q="What kind of work does Mux do?",a="Mux Manascrambler is an engineer drawn to spirits and unseen forces. He builds devices to reveal spirits, distill ectoplasm, and harness supernatural arcane power.",al={"mux job","what does mux sell","mux research"}},{q="Does Mux belong to a faction?",a="Mux Manascrambler belongs to the Steamwheedle Cartel in Gadgetzan. He works independently, keeps commercial neutrality, and aids adventurers from either the Horde or the Alliance.",al={"is mux horde","is mux neutral","mux alliance"}}},ang={["profession:Engineering"]="As a goblin engineer, you can use gears and power cells to capture and distill invisible supernatural forces, as Mux does, instead of simply blowing things apart."},kw={"ectoplasm","gadgetzan","ghost","goblin engineer","manascrambler","mux","tanaris"},rel={"subzone:gadgetzan","zone:tanaris","topic:goblin"},src={"Mux Manascrambler"}}
E["npc:narain-soothfancy"] = {t="npc",n="Narain Soothfancy",z="tanaris",s="Along Tanaris’s eastern shore, Narain Soothfancy offers visitors his visions. The gnome lives in a secluded hut just north of Steamwheedle Port, though those who know him value his engineering more than his prophecies.",h="Along Tanaris’s eastern shore, Narain Soothfancy offers visitors his visions.",sec={{t="Psychic Visions and Practical Gearing",b="Narain Soothfancy, a retired engineer, lives on Tanaris’s eastern coast just north of the goblin docks. He greets visitors with unopened envelopes pressed to his forehead or guesses at their business. Sometimes he asks if they seek the legendary Ashbringer. His fortune-telling is a show, but his technical knowledge is real. Even the blue dragon Azuregos calls Narain a poor psychic and a brilliant engineer. Nearby rests a handbook titled Soothsaying for Dummies.",sp=0},{t="A Shoreline Crash",b="Narain Soothfancy survived a flying machine crash far south along Land’s End Beach before settling near Steamwheedle Port. An unexpected rescue saved him from the wreck. His eccentric nature and strange obsessions have kept him isolated on the desert shore. There he tinkers with arcane-adjacent technology and offers dubious prophecies to passersby.",sp=0}},faq={{q="Who is Narain Soothfancy?",a="Narain Soothfancy is a retired gnome engineer living in Tanaris, north of Steamwheedle Port. He advertises himself as a master soothsayer, though his predictions are famously inaccurate.",al={"narain soothfancy lore","who is narain","tanaris psychic gnome"}},{q="Is Narain actually a psychic?",a="No. The blue dragon Azuregos calls Narain a poor psychic. Narain’s true gift is engineering, despite his theatrical attempts at mind-reading.",al={"can narain see the future","is narain psychic","soothfancy fortune teller"}},{q="What is the book 'Soothsaying for Dummies' beside him?",a="Soothsaying for Dummies is a handbook kept in Narain’s hut and associated with specialized trades. Narain directs travelers seeking such knowledge to the book.",al={"soothsaying for dummies","narain tradeskill book"}},{q="How does Narain know Azuregos?",a="Narain Soothfancy is an old associate of the blue dragon Azuregos, who wanders Azshara. Azuregos respects Narain’s engineering and crafting skill despite his bizarre pretensions.",al={"narain and azuregos","blue dragon narain"}}},ang={["profession:Engineering"]="As an engineer, you may find Narain’s wild inventions fascinating, though he claims his mechanical achievements come from mystical visions.",["race:Gnome"]="As a gnome, you may recognize Narain’s eccentric blend of brilliant engineering and bizarre, obsessive hobbies."},kw={"azuregos","engineer","narain","soothfancy","soothsayer","steamwheedle port","tanaris"},rel={"zone:tanaris","subzone:steamwheedle-port","subzone:land-s-end-beach","npc:azuregos","topic:gnome"},src={"Narain Soothfancy"}}
E["npc:senior-surveyor-fizzledowser"] = {t="npc",n="Senior Surveyor Fizzledowser",z="tanaris",s="In Gadgetzan, Senior Surveyor Fizzledowser searches the desert for water. He investigates trouble around the town’s supply and asks adventurers to find the missing Junior Surveyor Scrimshank.",h="In Gadgetzan, Senior Surveyor Fizzledowser searches the desert for water.",sec={{t="A Search for Water Gone Wrong",b="Senior Surveyor Fizzledowser works from Gadgetzan, where water is always scarce. Wastewander bandits seize nearby wells and water holes, so the Gadgetzan Water Company sends scouts farther into the dunes to seek new sources. Fizzledowser gives them dowsing widgets and directs some toward Sandsorrow Watch. Yet his probes keep finding underground insect hives instead of clean springs. The shortage now comes with a new danger.",sp=1},{t="Uncovering the Silithid",b="Armored insects that burrow through the sand ambushed the survey crews. Fizzledowser and Alchemist Pestlezugg examined the specimens, while Junior Surveyor Scrimshank disappeared inside the Gaping Chasm. The insects proved to be silithid, a coordinated vanguard force rather than ordinary desert pests. Fizzledowser's findings point to a danger that could overwhelm southern Kalimdor. He sets goblin neutrality aside and sends word to scholars of both the Horde and the Alliance.",sp=1}},faq={{q="Who is Senior Surveyor Fizzledowser?",a="Senior Surveyor Fizzledowser oversees fieldwork for the Gadgetzan Water Company. He searches Tanaris for wells to keep Gadgetzan supplied.",al={"who is fizzledowser","fizzledowser tanaris","gadgetzan surveyor"}},{q="What is the Gadgetzan Water Company?",a="The Gadgetzan Water Company works from Gadgetzan to secure, process, and distribute water across arid Tanaris. There, water is the most valuable commodity.",al={"gadgetzan water company","who does fizzledowser work for"}},{q="What happened to Junior Surveyor Scrimshank?",a="Junior Surveyor Scrimshank is missing. Fizzledowser asks adventurers to investigate his disappearance.",al={"where is scrimshank","scrimshank redemption","what happened to scrimshank"},sp=1},{q="Why is Fizzledowser concerned about the desert insects?",a="Fizzledowser investigates troubling insect activity and disruptions to Gadgetzan's water supply. He gathers evidence for further study.",al={"why investigate bugs","noxious lair investigation","silithid threat tanaris"}}},ang={["profession:Engineering"]="As an engineer, you can appreciate Fizzledowser's custom goblin dowsing widgets. They are built to find water beneath the shifting sands."},kw={"dowsing widget","fizzledowser","gadgetzan","gaping chasm","pestlezugg","scrimshank","silithid","tanaris","water company"},rel={"subzone:gadgetzan","zone:tanaris","subzone:sandsorrow-watch","subzone:gaping-chasm","subzone:noxious-lair","topic:goblin","topic:alliance","topic:horde"},src={"Senior Surveyor Fizzledowser"}}
E["npc:yeh-kinya"] = {t="npc",n="Yeh'kinya",z="tanaris",s="At Steamwheedle Port, Yeh'kinya sends travelers in search of lost troll relics. The jungle troll scholar says he seeks ancient lore and artifacts to understand dark powers.",h="At Steamwheedle Port, Yeh'kinya sends travelers in search of lost troll relics.",sec={{t="The Scholar at Steamwheedle Port",b="Among Steamwheedle Port's goblins and dockworkers, Yeh'kinya studies history and spirits. He sends travelers across Kalimdor and the Eastern Kingdoms in search of rare magical items. Some are ancient eggs in the Hinterlands. Others are stone prophecy tablets buried in Zul'Farrak. Yeh'kinya says this work serves the peaceful study of ancient troll history, though his focus on the blood god Hakkar draws suspicion.",sp=0},{t="The Serpent's Deceit",b="Yeh'kinya worships Hakkar the Soulflayer beneath his scholar's guise. He gathers artifacts and soul essence to prepare the Blood God's physical rebirth in Azeroth. Prospector Ironboot pieces together the plot and exposes it. Then Yeh'kinya abandons any pretense of friendship. He transforms into a green wind serpent and flees south across the open sea. The duped heroes must seek aid from the Zandalari on Yojamba Isle.",sp=2}},faq={{q="Who is Yeh'kinya?",a="At Steamwheedle Port in Tanaris, Yeh'kinya is a jungle troll who stands near the water. He presents himself as a scholar of historical relics and spirits, with particular interest in the troll god Hakkar.",al={"yeh'kinya lore","who is yehkinya","yehkinya npc"},sp=2},{q="Why does Yeh'kinya want the Prophecy of Mosh'aru and the Ancient Egg?",a="Yeh'kinya says the Prophecy of Mosh'aru and the Ancient Egg aid his study of ancient troll history and spirits. The tablets lie in Zul'Farrak's ruins, and the egg is in the Hinterlands. Both connect to his interest in Hakkar.",al={"why ancient egg","prophecy of mosharu troll","yehkinya purpose"},sp=2}},ang={["race:Troll"]="As a Darkspear troll, you recognize the mortal peril of Hakkar's return.",["class:Priest"]="As a priest, you may find Yeh'kinya's casual gathering of trapped screecher spirits troubling if you are sensitive to spiritual essence."},kw={"hakkar","ironboot","mosh'aru","soulflayer","steamwheedle port","tanaris","wind serpent","yeh'kinya","yehkinya"},rel={"subzone:steamwheedle-port","zone:tanaris","subzone:yojamba-isle","subzone:zul-gurub","topic:troll"},src={"Yeh'kinya"}}
E["quest:10"] = {t="quest",n="The Scrimshank Redemption",z="tanaris",s="In Gadgetzan, Fizzledowser seeks news of his missing assistant, Junior Surveyor Scrimshank. Scrimshank went into the Gaping Chasm, southeast of town. Now Fizzledowser asks you to find Scrimshank or the surveying equipment.",h="In Gadgetzan, Fizzledowser seeks news of his missing assistant, Junior Surveyor Scrimshank.",sec={{t="A Surveyor Gone Missing",b="Senior Surveyor Fizzledowser has heard nothing from Junior Surveyor Scrimshank since he went into the Gaping Chasm. The last report from there spoke of more weird bugs. Fizzledowser wonders whether the bugs now hold two great regions of the desert.\n\nHe asks you to search for Scrimshank or, if Scrimshank is gone, the surveying equipment. Fizzledowser fears it may be all that remains.",sp=0},{t="Fizzledowser's Verdict",b="By Fizzledowser's account, Junior Surveyor Scrimshank did not survive. Fizzledowser hopes his loss counts for something, given what the surveying equipment recorded.\n\nThe bugs show worrying cunning, and the research so far points to a third party controlling them. Gadgetzan and the whole desert may be in danger.",sp=1}},faq={{q="Who is Senior Surveyor Fizzledowser?",a="Senior Surveyor Fizzledowser studies the desert's weird bugs in Gadgetzan. He is Scrimshank's superior.",al={"fizzledowser","who gives this quest","surveyor fizzledowser"}},{q="Who is Junior Surveyor Scrimshank?",a="Junior Surveyor Scrimshank was Fizzledowser's top assistant. He was sent into the desert southeast of Gadgetzan before he went missing.",al={"scrimshank","who is scrimshank","junior surveyor"}},{q="Where is the Gaping Chasm located?",a="The Gaping Chasm is a desert region southeast of Gadgetzan.",al={"gaping chasm location","where is gaping chasm","chasm location"}},{q="What came before this step?",a="The Noxious Lair Investigation came before this step.",al={"previous quest","prerequisite","what quest comes first"}}},kw={"fizzledowser","gadgetzan","gaping chasm","scrimshank","surveying","tanaris"},rel={"npc:senior-surveyor-fizzledowser","subzone:gaping-chasm","subzone:gadgetzan","quest:82","quest:110","zone:tanaris","topic:goblin"},m={start="Senior Surveyor Fizzledowser",["end"]="Senior Surveyor Fizzledowser",level="48",id=10,ri={"Scrimshank's Surveying Gear"}},src={"The Scrimshank Redemption"}}
E["quest:110"] = {t="quest",n="Insect Part Analysis",z="tanaris",s="In Gadgetzan, Fizzledowser needs word on the insect parts sent to Alchemist Pestlezugg. With Scrimshank lost, the Senior Surveyor is sorting his surveying gear and personal effects.",h="In Gadgetzan, Fizzledowser needs word on the insect parts sent to Alchemist Pestlezugg.",sec={{t="A Check-In at Gadgetzan",b="Senior Surveyor Fizzledowser is putting Scrimshank's surveying gear and personal effects in order. He fears the bugs will claim more lives, so he sends you to Alchemist Pestlezugg in Gadgetzan. Learn whether Pestlezugg has finished processing the insect parts the surveyors sent. If they are ready, bring them back to Fizzledowser.",sp=0},{t="What Pestlezugg Found",b="Alchemist Pestlezugg has finished his work, and the results trouble him. He believes the first suspicion was right: an outside force controls the bugs. That points to a powerful force, unknown and malignant. Pestlezugg has never seen bugs changed into pure ravagers before.",sp=1}},faq={{q="Who sends you to consult Alchemist Pestlezugg?",a="Senior Surveyor Fizzledowser sends you while sorting through Scrimshank's surveying gear and personal effects.",al={"quest giver","who starts insect part analysis","fizzledowser location"}},{q="Where is Alchemist Pestlezugg located?",a="Alchemist Pestlezugg is in Gadgetzan, where you are sent to check on the insect parts.",al={"where is pestlezugg","pestlezugg location","pestlezugg town"}},{q="What came directly before this step?",a="The Scrimshank Redemption comes directly before this step.",al={"prerequisite quest","what quest comes first","previous step"}},{q="What are you sent to find out?",a="You are sent to learn whether Pestlezugg has finished processing the insect parts the surveyors sent. If they are ready, bring them back to Fizzledowser.",al={"what does pestlezugg have"}}},kw={"fizzledowser","gadgetzan","insect part analysis","pestlezugg","scrimshank","tanaris"},rel={"quest:10","quest:113","subzone:gadgetzan","zone:tanaris"},m={start="Senior Surveyor Fizzledowser",["end"]="Alchemist Pestlezugg",level="48",id=110},src={"Insect Part Analysis"}}
E["quest:113"] = {t="quest",n="Insect Part Analysis",z="tanaris",s="From Tanaris, Alchemist Pestlezugg sends an urgent warning to Gadgetzan. The danger threatens both places and may spread across southern Kalimdor.",h="From Tanaris, Alchemist Pestlezugg sends an urgent warning to Gadgetzan.",sec={{t="A Grave Warning",b="Alchemist Pestlezugg asks you to carry the report to Senior Surveyor Fizzledowser in Gadgetzan. The danger threatens Tanaris and Gadgetzan, and may spread across southern Kalimdor. It could reach all of Azeroth, and nothing suggests it will subside. Pestlezugg wants everyone who can read to know.\n\nFizzledowser is to make a duplicate for you, so you can share it freely with your allegiance.",sp=0},{t="A Matter of Coin",b="Senior Surveyor Fizzledowser thanks you for bringing the report and for your hard work for the Gadgetzan Water Company. The company holds valuable information, and Fizzledowser would usually expect people to pay well for it.\n\nBut Fizzledowser has known Alchemist Pestlezugg for a long time. Pestlezugg recommends sharing the report with everyone, so Fizzledowser agrees and makes a copy for you.",sp=1}},faq={{q="Who sends the report and who receives it?",a="Alchemist Pestlezugg gives you the report to take to Senior Surveyor Fizzledowser in Gadgetzan.",al={"who gives insect part analysis","who do i turn insect part analysis in to","where to deliver the report"}},{q="Why is Alchemist Pestlezugg so alarmed?",a="Pestlezugg warns that the threat faces Tanaris and Gadgetzan, then may reach all of southern Kalimdor and perhaps all of Azeroth. Nothing suggests it will subside.",al={"pestlezugg warning","what is in the insect report","why is the insect threat serious"}},{q="Why do you need a copy of the report?",a="Pestlezugg wants everyone to know about the threat. Fizzledowser is to make a duplicate for you to share freely with your allegiance.",al={"why copy the report","fizzledowser report copy","why share the report"}},{q="What comes directly before this delivery?",a="This delivery follows an earlier step with the same name.",al={"previous quest","what quest comes before this"}}},kw={"fizzledowser","gadgetzan","gadgetzan water company","insect analysis","pestlezugg","report","tanaris"},rel={"npc:senior-surveyor-fizzledowser","subzone:gadgetzan","zone:tanaris","quest:110","quest:32","quest:162"},m={start="Alchemist Pestlezugg",["end"]="Senior Surveyor Fizzledowser",level="48",id=113},src={"Insect Part Analysis (2)"}}
E["quest:1189"] = {t="quest",n="Safety First",z="tanaris",s="On the Shimmering Flats, you carry Shreev’s modified seaforium booster back to Razzeric. Shreev warns that one slip while setting it off could leave Razzeric a scorch mark on the track.",h="On the Shimmering Flats, you carry Shreev’s modified seaforium booster back to Razzeric.",sec={{t="A Warning from Shreev",b="Shreev hands you the modified booster, prepared as Razzeric asked. He warns that Razzeric must take care when setting it off. One slip, and Razzeric will be a scorch mark on the track instead of racing ahead. Shreev says that would be a shame. Then he wonders whether the nineteenth driver would have been any good.",sp=0},{t="Sand Under the Seat",b="Back on the Shimmering Flats, Razzeric grumbles that Pozzik loaded a bucket of sand onto his racer. How can he reach top speed with sand beneath the seat?",sp=0},{t="The Booster Returned",b="Razzeric is pleased with the modified booster. He wishes he could see the gnomes’ faces when he sets it off. Yet he expects to be too busy setting a new course record.",sp=1}},faq={{q="Who sends the modified booster back to the flats?",a="In Gadgetzan, Shreev finishes modifying the seaforium booster as Razzeric wanted. Then he gives it to you to carry back to Razzeric on the Shimmering Flats.",al={"who gives safety first 2","shreev quest giver","who modifies the booster"}},{q="What does Shreev warn about?",a="Shreev warns Razzeric to take care when setting off the booster. One slip, and Razzeric will be a scorch mark on the track instead of racing ahead.",al={"is the booster dangerous","shreev warning","booster risk"}},{q="Why is Razzeric upset about his vehicle?",a="Pozzik loaded a bucket of sand onto Razzeric’s racer. Razzeric wonders how he can reach top speed with sand beneath the seat.",al={"why is razzeric mad","pozzik bucket of sand","razzeric complaint"}}},kw={"gadgetzan","pozzik","razzeric","safety first","seaforium booster","shimmering flats","shreev","thousand needles"},rel={"quest:1188","subzone:shimmering-flats","subzone:gadgetzan","zone:thousandneedles","npc:pozzik","topic:gnome"},m={start="Shreev",["end"]="Razzeric",level="41",id=1189},src={"Safety First (2)"}}
E["quest:1560"] = {t="quest",n="Tooga's Quest",z="tanaris",s="In Tanaris, you and Tooga are trying to reach Torta. She waits just south of Steamwheedle Port.",h="In Tanaris, you and Tooga are trying to reach Torta.",sec={{t="A Lost Wanderer",b="Tooga wanders near a crashed goblin zeppelin by Thistleshrub Valley, unsure of the way home. His wife, Torta, sent him to fetch dinner. A wrong turn left him lost, so he asks you to lead him back to her.",sp=0},{t="Across the Zone",b="Torta waits just south of Steamwheedle Port, across Tanaris from Tooga. Reaching her means walking nearly the whole width of the zone.",sp=0},{t="A Wife's Welcome",b="Torta is not surprised that Tooga could not find his way home alone. She tells him to go into the ocean and bring back food.",sp=1}},faq={{q="Who is Tooga?",a="Tooga is a lost turtle in Tanaris who needs help finding his way back to his wife.",al={"who is tooga","tooga turtle","who is the turtle in tanaris"}},{q="Who is Torta?",a="Torta is Tooga's wife, waiting just south of Steamwheedle Port.",al={"who is torta","where is torta","torta location"}},{q="Why is Tooga lost in the desert?",a="Torta sent Tooga to fetch dinner, but a wrong turn left him lost.",al={"why is tooga lost","what happened to tooga","tooga backstory"}},{q="Where is Tooga originally found?",a="Tooga is found near a crashed goblin zeppelin by Thistleshrub Valley in Tanaris.",al={"tooga start location","where does toogas quest start","find tooga"}}},kw={"steamwheedle port","tanaris","thistleshrub valley","tooga","torta","turtle"},rel={"zone:tanaris","subzone:thistleshrub-valley","subzone:steamwheedle-port","topic:goblin"},m={start="Tooga",["end"]="Torta",level="50",id=1560},src={"Tooga's Quest"}}
E["quest:162"] = {t="quest",n="Rise of the Silithid",z="tanaris",s="Senior Surveyor Fizzledowser sends you to Darnassus with a report for Gracina Spiritmight, a night elf scholar and historian.",h="Senior Surveyor Fizzledowser sends you to Darnassus with a report for Gracina Spiritmight, a night elf...",sec={{t="A Scholar in Darnassus",b="Senior Surveyor Fizzledowser wants the report in the hands of someone who knows such matters. Gracina Spiritmight is a night elf scholar and historian. She has spent much time studying life forms unique to Azeroth's ecology. Fizzledowser hopes she can judge the danger and find a way to halt it. At Fizzledowser's last word, Gracina lives in the Temple of the Moon in Darnassus.",sp=0},{t="Gracina's Answer",b="Gracina Spiritmight says the night elves know of the terror described in the report. She believes Fizzledowser chose well in sending the report, and you. The silithid will devour the Tanaris desert rapidly and rank among the greatest menaces anyone will face. They are tools of one of the gravest threats to both Horde and Alliance. Gracina laments that no one saw the danger sooner.",sp=1}},faq={{q="Who is Gracina Spiritmight?",a="Gracina Spiritmight is a night elf scholar and historian who has spent much time studying life forms unique to Azeroth's ecology.",al={"gracina spiritmight lore","who is gracina","temple of the moon scholar"}},{q="Who sends you to Gracina?",a="Senior Surveyor Fizzledowser gives you the Insect Analysis Report and asks you to take it to Gracina Spiritmight.",al={"where did the report come from","insect analysis report origin"}},{q="Where can Gracina Spiritmight be found?",a="At Fizzledowser's last word, Gracina Spiritmight lives in the Temple of the Moon in Darnassus.",al={"where is gracina","gracina spiritmight location","find gracina spiritmight"}},{q="What came before this journey to Darnassus?",a="Insect Part Analysis comes before your journey to Darnassus.",al={"previous quest","what led to rise of the silithid","prior quest to gracina"}}},kw={"darnassus","fizzledowser","gracina","insect analysis","silithid","spiritmight","tanaris","temple of the moon"},rel={"npc:senior-surveyor-fizzledowser","zone:tanaris","zone:darnassus","subzone:temple-of-the-moon","topic:night-elf","topic:alliance","topic:horde","quest:113"},m={start="Senior Surveyor Fizzledowser",["end"]="Gracina Spiritmight",level="49",faction="Alliance",id=162},src={"Rise of the Silithid (Alliance)"}}
E["quest:1690"] = {t="quest",n="Wastewander Justice",z="tanaris",s="In Tanaris, the Wastewander hold nearly every well, and Gadgetzan's water supply is at risk. Chief Engineer Bilgewhizzle sends you east of town to bring justice to the Wastewander Bandits and Thieves.",h="In Tanaris, the Wastewander hold nearly every well, and Gadgetzan's water supply is at risk.",sec={{t="Justice for the Wells",b="Without access to the wells held by Wastewander nomads, Gadgetzan's water supply will soon run dry. Chief Engineer Bilgewhizzle wants you to bring down ten Wastewander Bandits and Thieves east of town. Then you are to report back at once. He has a taste for goblin-style justice.",sp=0},{t="Far From Done",b="Bilgewhizzle is pleased with how quickly you acted. The Wastewander are thinned enough for the company to consider winning back its wells. Yet Bilgewhizzle is far from done with the foul nomads, and he has more in mind.",sp=1}},faq={{q="Who is Chief Engineer Bilgewhizzle?",a="Chief Engineer Bilgewhizzle works for the Gadgetzan Water Company in Gadgetzan.",al={"bilgewhizzle","who gives wastewander justice","gadgetzan water company engineer"}},{q="Why is the Gadgetzan Water Company going after the Wastewanders?",a="The Wastewander nomads hold nearly every water well in the desert. Without access to them, Gadgetzan's water supply will run dry.",al={"why kill wastewander bandits","wastewander justice reason","why attack nomads tanaris"}},{q="Where are the Wastewander Bandits and Thieves located?",a="The Wastewander Bandits and Thieves are in the desert east of Gadgetzan.",al={"where to find wastewander bandits","wastewander bandit location","thieves tanaris location"}}},kw={"bandit","bilgewhizzle","gadgetzan","tanaris","thief","wastewander","water company","wells"},rel={"quest:1691","subzone:gadgetzan","zone:tanaris","topic:goblin"},m={start="Chief Engineer Bilgewhizzle",["end"]="Chief Engineer Bilgewhizzle",level="43",id=1690},src={"Wastewander Justice"}}
E["quest:1691"] = {t="quest",n="More Wastewander Justice",z="tanaris",s="East and southeast of Gadgetzan, Bilgewhizzle now targets Wastewander rogues, assassins, and shadow mages. With fewer nomads left, the company can more easily reclaim the water wells.",h="East and southeast of Gadgetzan, Bilgewhizzle now targets Wastewander rogues, assassins, and shadow mages.",sec={{t="The Stronger Ranks",b="Chief Engineer Bilgewhizzle says you have done well, but the company needs fewer nomads before it can reclaim the wells. Now you face their rogues, assassins, and shadow mages east and southeast of Gadgetzan. Bilgewhizzle calls them a nasty lot. He insists the wells rightfully belong to the company.",sp=0},{t="Taking the Fight to Them",b="With the nomad population thinned, the company can take the fight to them. Bilgewhizzle points you to Spigot Operator Luglunket in Gadgetzan. Luglunket offers a bounty for any Wastewander water pouches you collected while dealing with the nomads.",sp=1}},faq={{q="Who asks for this?",a="Chief Engineer Bilgewhizzle of the Gadgetzan Water Company asks you in Gadgetzan.",al={"who gives more wastewander justice","quest giver"}},{q="Why does the Gadgetzan Water Company want these nomads removed?",a="The company wants to reclaim the water wells, and fewer nomads will make that easier.",al={"why kill wastewanders","bilgewhizzle motive"}},{q="Where can the targeted nomads be found?",a="The targeted nomads are east and southeast of Gadgetzan.",al={"where are wastewander rogues","where to find shadow mages"}},{q="What comes before this step?",a="This follows Wastewander Justice.",al={"prerequisite","prior quest"}}},kw={"assassins","bilgewhizzle","gadgetzan","shadow mages","tanaris","wastewander","water company"},rel={"quest:1690","subzone:gadgetzan","zone:tanaris"},m={start="Chief Engineer Bilgewhizzle",["end"]="Chief Engineer Bilgewhizzle",level="44",id=1691},src={"More Wastewander Justice"}}
E["quest:1707"] = {t="quest",n="Water Pouch Bounty",z="tanaris",s="In Gadgetzan, Spigot Operator Luglunket asks you to recover the Wastewander water pouches stolen by the nomads. Bring them back from anywhere in the desert, and the Gadgetzan Water Company offers an official care package for every five.",h="In Gadgetzan, Spigot Operator Luglunket asks you to recover the Wastewander water pouches stolen by the...",sec={{t="Water That Belongs to Gadgetzan",b="Spigot Operator Luglunket wants you to bring back the Wastewander water pouches you find in the desert. The nomads stole Gadgetzan's water, so every pouch helps the town reclaim what is its own. For every five pouches returned, the Gadgetzan Water Company offers an official care package.",sp=0},{t="Keep Them Coming",b="Luglunket welcomes every reclaimed pouch because each one puts disaster further off. Bring back five, and Luglunket promises to make it worth your while.",sp=1}},faq={{q="Who is Spigot Operator Luglunket?",a="Spigot Operator Luglunket is a seasoned spigot operator in Gadgetzan who wants the Wastewander water pouches returned.",al={"who is luglunket","luglunket role","spigot operator"}},{q="Why does Luglunket want Wastewander water pouches?",a="The Wastewander nomads stole water that belongs to Gadgetzan.",al={"why water pouches","why kill wastewander","wastewander water lore"}},{q="Where can Wastewander water pouches be found?",a="The stolen pouches are somewhere in the desert, in the hands of the Wastewander nomads.",al={"where to find water pouches","wastewander pouch location","who drops water pouches"}},{q="What does the Gadgetzan Water Company offer for the pouches?",a="The Gadgetzan Water Company offers an official care package for every five pouches.",al={"care package","what do i get for pouches"}}},kw={"gadgetzan","luglunket","tanaris","wastewander","water company","water pouch"},rel={"subzone:gadgetzan","zone:tanaris"},m={start="Spigot Operator Luglunket",["end"]="Spigot Operator Luglunket",level="44",id=1707},src={"Water Pouch Bounty"}}
E["quest:1878"] = {t="quest",n="Water Pouch Bounty",z="tanaris",s="In Gadgetzan, Spigot Operator Luglunket welcomes you back for five more Wastewander water pouches. A care package waits with your name on it.",h="In Gadgetzan, Spigot Operator Luglunket welcomes you back for five more Wastewander water pouches.",sec={{t="Back Again",b="Luglunket welcomes you back and asks for five more Wastewander water pouches. A care package is already set aside with your name on it.",sp=0},{t="Keep Them Coming",b="Luglunket is pleased with the reclaimed pouches. Each one keeps everyone further from disaster. Luglunket promises to make it worth your while for every five you bring.",sp=1}},faq={{q="Who is offering this bounty?",a="Luglunket, the spigot operator in Gadgetzan, offers the bounty.",al={"who gives water pouch bounty","luglunket quest","who takes water pouches"}},{q="How many water pouches are needed?",a="You need five Wastewander water pouches, the same number as before.",al={"how many pouches","water pouch count","pouches per turn in"}},{q="What does Luglunket have ready?",a="Luglunket has a care package set aside under your name.",al={"what is the care package","what do i get"}},{q="What comes before this step?",a="This follows the earlier Water Pouch Bounty, when you first brought pouches to Luglunket.",al={"previous quest","what do i do first"}}},kw={"care package","spigot operator luglunket","tanaris","wastewander water pouch","water pouch bounty"},rel={"quest:1707","zone:tanaris"},m={start="Spigot Operator Luglunket",["end"]="Spigot Operator Luglunket",level="44",faction="Neutral",id=1878},src={"Water Pouch Bounty (2)"}}
E["quest:2605"] = {t="quest",n="The Thirsty Goblin",z="tanaris",s="In Gadgetzan, Marin Noggenfogger longs for a drink that can end his unending thirst. He has heard the dew collectors in the cactus garden southwest of town keep water in special glands, and hopes one will make such a drink possible.",h="In Gadgetzan, Marin Noggenfogger longs for a drink that can end his unending thirst.",sec={{t="A Gland Worth Drinking",b="Marin Noggenfogger has heard of dew collectors in the cactus garden southwest of Gadgetzan. They keep water in special glands, and he believes a full gland could start a drink that ends his thirst for good. He asks you to find their garden and bring one back.",sp=0}},faq={{q="Who sends you to hunt for the dew gland?",a="Marin Noggenfogger in Gadgetzan asks you to find a full dew gland, hoping it will cure his terrible thirst.",al={"thirsty goblin questgiver","who starts thirsty goblin","marin noggenfogger"}},{q="Where are the dew collectors located?",a="The dew collectors live in the cactus garden of Thistleshrub Valley, southwest of Gadgetzan in Tanaris.",al={"dew collector location","where to find dew gland","cactus garden location"}},{q="What creature carries the laden dew gland?",a="Thistleshrub Dew Collectors carry the glands, which are said to store water.",al={"what drops laden dew gland","dew collector mob"}},{q="What comes next in the chain?",a="The chain continues with In Good Taste.",al={"thirsty goblin follow up","next quest after thirsty goblin"}}},kw={"cactus garden","dew collector","dew gland","gadgetzan","marin noggenfogger","tanaris","thistleshrub valley"},rel={"quest:2606","subzone:gadgetzan","zone:tanaris","subzone:thistleshrub-valley","quest:2641","quest:2661","quest:2662","topic:goblin"},m={start="Marin Noggenfogger",["end"]="Marin Noggenfogger",level="49",id=2605,ri={"Laden Dew Gland"}},src={"The Thirsty Goblin"}}
E["quest:2606"] = {t="quest",n="In Good Taste",z="tanaris",s="Marin Noggenfogger finds thistleshrub dew awful to drink, yet he keeps working on the brew. He sends you to Sprinkle in Gadgetzan with the dew.",h="Marin Noggenfogger finds thistleshrub dew awful to drink, yet he keeps working on the brew.",sec={{t="A Cook for a Bad Brew",b="Marin Noggenfogger tastes the dew and finds it awful. Still, he keeps working on the drink. He sends you to Sprinkle, his friend in Gadgetzan and an excellent chef. You carry the dew and explain that the drink needs to go down more easily. Marin also wants it to have some kick.",sp=0}},faq={{q="Where does this step fit in the chain?",a="It follows The Thirsty Goblin, and Sprinkle's Secret Ingredient comes next.",al={"what quest is before this","what is next in the chain","quest progression"}},{q="Why does Marin Noggenfogger want the dew taken to Sprinkle?",a="Marin Noggenfogger finds the dew awful to drink. He hopes Sprinkle, whom he calls an excellent chef, can make it go down more easily and give it some kick.",al={"why sprinkle","what does marin want with sprinkle","who is sprinkle"}},{q="Where can Sprinkle be found?",a="Sprinkle is in Gadgetzan, the same town as Marin Noggenfogger.",al={"sprinkle location","where is sprinkle","find sprinkle"}}},kw={"gadgetzan","in good taste","marin noggenfogger","sprinkle","tanaris","thistleshrub dew"},rel={"quest:2605","quest:2641","quest:2661","quest:2662","subzone:gadgetzan","zone:tanaris","topic:goblin"},m={start="Marin Noggenfogger",["end"]="Sprinkle",level="49",id=2606},src={"In Good Taste"}}
E["quest:2641"] = {t="quest",n="Sprinkle's Secret Ingredient",z="tanaris",s="In Gadgetzan, Sprinkle offers a way to make Marin Noggenfogger's foul brew drinkable with a Violet Tragan. The mushroom grows underwater in a small lake in the Hinterlands.",h="In Gadgetzan, Sprinkle offers a way to make Marin Noggenfogger's foul brew drinkable with a Violet Tragan.",sec={{t="A Cook's Secret",b="As a child, Sprinkle's sister did all the cooking, and the food was hard to stomach. Sprinkle found a mushroom called the Violet Tragan and made it her secret ingredient. She says it made every dish taste wonderful. Now she will use it to make Marin's horrid brew drinkable.",sp=0},{t="Under the Water",b="The Violet Tragan grows underwater in a small lake in the Hinterlands. Valorwind Lake lies just south of the road that crosses the zone. Dive beneath the surface to gather the mushroom, then return to Sprinkle in Gadgetzan.",sp=0}},faq={{q="Who is Sprinkle?",a="Sprinkle is a cook in Gadgetzan and a friend of Marin Noggenfogger. Marin sent you to her with a bad-tasting brew.",al={"who is sprinkle","sprinkle gadgetzan","sprinkles secret ingredient quest giver"}},{q="What is the Violet Tragan?",a="The Violet Tragan is a mushroom Sprinkle found as a child and calls her secret ingredient. She says it makes anything taste great.",al={"violet tragan","what is violet tragan","secret ingredient mushroom"}},{q="Where can the Violet Tragan be found?",a="The Violet Tragan grows underwater in a small lake in the Hinterlands. Valorwind Lake lies just south of the road across the zone.",al={"where is violet tragan","where to find secret ingredient","violet tragan location"}},{q="How does this connect to Marin Noggenfogger?",a="Marin's brew tasted terrible, so Sprinkle wants the Violet Tragan to make it drinkable.",al={"why does sprinkle need this","marin noggenfogger connection","noggenfogger questline"}}},kw={"gadgetzan","hinterlands","mushroom","noggenfogger","sprinkle","tanaris","violet tragan"},rel={"quest:2606","quest:2661","quest:2605","quest:2662","subzone:gadgetzan","zone:tanaris","zone:hinterlands","topic:goblin"},m={start="Sprinkle",["end"]="Sprinkle",level="49",id=2641,ri={"Violet Tragan"}},src={"Sprinkle's Secret Ingredient"}}
E["quest:2661"] = {t="quest",n="Delivery for Marin",z="tanaris",s="In Gadgetzan, Sprinkle sends Violet Powder to Marin Noggenfogger and reminds her of the favor Marin owes.",h="In Gadgetzan, Sprinkle sends Violet Powder to Marin Noggenfogger and reminds her of the favor Marin owes.",sec={{t="A Town Delivery",b="In Gadgetzan, Sprinkle gives you Violet Powder after you bring her the Violet Tragan. Marin Noggenfogger is in the same town, and Sprinkle asks you to remind Marin that she owes a favor.",sp=0}},faq={{q="Who sends you to Marin Noggenfogger?",a="Sprinkle sends you to Marin Noggenfogger with Violet Powder after you bring her the Violet Tragan.",al={"who gives delivery for marin","delivery for marin quest giver","sprinkle delivery"}},{q="What item are you delivering?",a="Sprinkle gives you Violet Powder to deliver to Marin Noggenfogger.",al={"what do you bring marin","marin delivery item","what powder is it"}},{q="Where is Marin Noggenfogger located?",a="Marin Noggenfogger is in Gadgetzan, the same town as Sprinkle.",al={"marin noggenfogger location","where is marin","find marin noggenfogger"}},{q="What message does Sprinkle want passed to Marin?",a="Sprinkle asks you to tell Marin Noggenfogger that Marin owes her a favor.",al={"sprinkle message","what does sprinkle say to marin","sprinkle favor"}}},kw={"gadgetzan","marin noggenfogger","noggenfogger elixir","sprinkle","tanaris","violet powder"},rel={"quest:2641","quest:2662","quest:2606","quest:2605","subzone:gadgetzan","zone:tanaris","topic:goblin"},m={start="Sprinkle",["end"]="Marin Noggenfogger",level="49",id=2661},src={"Delivery for Marin"}}
E["quest:2662"] = {t="quest",n="Noggenfogger Elixir",z="tanaris",s="In Gadgetzan, Marin Noggenfogger works Violet Powder into the dew. He asks you to return in a moment, when his fabulous elixir should be ready.",h="In Gadgetzan, Marin Noggenfogger works Violet Powder into the dew.",sec={{t="Mixing the Elixir",b="Marin has the dew and the powder. He begins mixing them, and the Noggenfogger Elixir should be ready after a short wait. Then speak to him again.",sp=0},{t="Marin's Verdict",b="When Marin finishes, he presses a drink on you and calls it wonderful. He boasts of the millions it will bring, then asks you to step aside so you are not blocking business. Sprinkle claims Marin owes a favor, but Marin laughs it off as a joke.",sp=1}},faq={{q="Who offers this quest?",a="Marin Noggenfogger offers it in Gadgetzan.",al={"noggenfogger quest giver","who gives noggenfogger elixir","marin noggenfogger quest"}},{q="What came before this step?",a="This follows Delivery for Marin. Before that came The Thirsty Goblin, In Good Taste and Sprinkle's Secret Ingredient.",al={"prereq noggenfogger elixir","previous quest for marin","what comes before noggenfogger elixir"}},{q="What ingredients does Marin combine here?",a="Marin mixes Sprinkle's Violet Powder into the dew.",al={"noggenfogger ingredients","what is marin mixing","what is in the elixir"}}},kw={"dew","gadgetzan","goblin","marin noggenfogger","noggenfogger elixir","powder","sprinkle","tanaris"},rel={"quest:2661","quest:2641","quest:2606","quest:2605","subzone:gadgetzan","zone:tanaris","topic:goblin"},m={start="Marin Noggenfogger",["end"]="Marin Noggenfogger",level="49",id=2662},src={"Noggenfogger Elixir (quest)"}}
E["quest:2741"] = {t="quest",n="The Super Egg-O-Matic",z="tanaris",s="At the control panel, Curgle Cranklehop's newest invention sputters wildly as hippogryph eggs go into the machine.",h="At the control panel, Curgle Cranklehop's newest invention sputters wildly as hippogryph eggs go into the...",sec={{t="A Machine of Curgle Cranklehop",b="At its control panel, Curgle Cranklehop's newest invention sputters wildly. It takes a hippogryph egg found in the mountains of southern Feralas, around the Ruins of Isildien.",sp=0},{t="What the Machine Does",b="Place a hippogryph egg inside, and beeps and odd mechanical noises answer. The Eggometer weighs and measures the egg, then packages it in moments. What comes out is an Egg Crate, holding an egg of some variety.",sp=1}},faq={{q="Who built the Super Egg-O-Matic?",a="Curgle Cranklehop built the Super Egg-O-Matic as her newest invention.",al={"who made egg-o-matic","egg-o-matic creator","curgle cranklehop invention"}},{q="What does the machine need to operate?",a="The machine needs a hippogryph egg placed inside.",al={"what do i give the egg-o-matic","egg-o-matic item needed","hippogryph egg machine"}},{q="Where do you find hippogryph eggs?",a="You find hippogryph eggs in the mountains of southern Feralas, around the Ruins of Isildien.",al={"hippogryph egg location","where to find hippogryph eggs","where are the eggs feralas"}}},kw={"curgle cranklehop","egg-o-matic","eggometer","feralas","hippogryph egg","tanaris"},rel={"zone:tanaris","zone:feralas","subzone:ruins-of-isildien"},m={start="Egg-O-Matic",["end"]="Egg-O-Matic",level="47",faction="Neutral",id=2741},src={"The Super Egg-O-Matic"}}
E["quest:2747"] = {t="quest",n="An Extraordinary Egg",z="tanaris",s="In Tanaris, Curgle Cranklehop seeks an extraordinary egg from Feralas.",h="In Tanaris, Curgle Cranklehop seeks an extraordinary egg from Feralas.",sec={{t="A Rarity from Feralas",b="Curgle Cranklehop says few eggs from Feralas arrive in extraordinary shape. Such eggs are the rarest of all. One is what Curgle seeks.",sp=0}},faq={{q="Who is looking for an extraordinary egg?",a="Curgle Cranklehop, inventor of the Super Egg-O-Matic, seeks an extraordinary egg.",al={"who starts an extraordinary egg","who gives an extraordinary egg quest","curgle cranklehop egg"}},{q="Where do these extraordinary eggs come from?",a="These extraordinary eggs come from Feralas, though few arrive in extraordinary shape.",al={"extraordinary egg location","where to find extraordinary egg","egg from feralas"}},{q="What comes before this request?",a="This request follows The Super Egg-O-Matic.",al={"prerequisite for extraordinary egg","an extraordinary egg chain","previous quest for extraordinary egg"}}},kw={"curgle cranklehop","extraordinary egg","feralas","super egg-o-matic","tanaris"},rel={"quest:2741","zone:feralas","zone:tanaris"},m={start="Curgle Cranklehop",["end"]="Curgle Cranklehop",level="60",id=2747},src={"An Extraordinary Egg"}}
E["quest:2748"] = {t="quest",n="A Fine Egg",z="tanaris",s="Curgle Cranklehop speaks of an egg that may hatch free of the Gordunni ogres’ evil incantations.",h="Curgle Cranklehop speaks of an egg that may hatch free of the Gordunni ogres’ evil incantations.",sec={{t="What Makes It Fine",b="Curgle Cranklehop says an egg has a good chance of hatching untouched by the Gordunni ogres’ wicked chanting, if conditions are ideal.",sp=0},{t="What Curgle Does Next",b="Curgle takes the egg and plans to send it to Darnassus. There, it is hoped to hatch soon.",sp=1}},faq={{q="What makes an egg considered a fine egg?",a="Under ideal conditions, an egg may hatch free of the evil brought by Gordunni ogre incantations.",al={"what is a fine egg","fine egg lore","why fine egg"}},{q="What came before this step?",a="The Super Egg-O-Matic came before this step.",al={"fine egg prerequisite","previous quest fine egg"}}},kw={"curgle cranklehop","darnassus","fine egg","gordunni","ogre incantations","super egg-o-matic","tanaris"},rel={"quest:2741","zone:darnassus","zone:tanaris"},m={start="Curgle Cranklehop",["end"]="Curgle Cranklehop",level="60",id=2748},src={"A Fine Egg"}}
E["quest:2749"] = {t="quest",n="An Ordinary Egg",z="tanaris",s="Curgle Cranklehop tends ordinary hippogryph eggs, though only about half hatch.",h="Curgle Cranklehop tends ordinary hippogryph eggs, though only about half hatch.",sec={{t="Half a Chance",b="Only about half of ordinary hippogryph eggs hatch. Curgle Cranklehop does their best to nurture each one, hoping luck will see it hatch.",sp=0}},faq={{q="Who is Curgle Cranklehop?",a="Curgle Cranklehop invented the Super Egg-O-Matic and works with hippogryph eggs from Feralas.",al={"who is curgle","curgle cranklehop"}},{q="What happens to the ordinary hippogryph egg?",a="Curgle tends the ordinary hippogryph egg and hopes for luck. Only about half of such eggs hatch.",al={"what does curgle do with the egg","egg hatching chance"}},{q="Where do these eggs come from?",a="The eggs come from Feralas.",al={"where do i find the egg","ordinary egg location"}},{q="What came before this step?",a="The step before this one is The Super Egg-O-Matic.",al={"prerequisite quest","what is the previous quest"}}},kw={"curgle cranklehop","feralas","hippogryph","ordinary egg","tanaris","the super egg-o-matic"},rel={"quest:2741","zone:feralas","zone:tanaris"},m={start="Curgle Cranklehop",["end"]="Curgle Cranklehop",level="60",id=2749},src={"An Ordinary Egg"}}
E["quest:2750"] = {t="quest",n="A Bad Egg",z="tanaris",s="Curgle Cranklehop takes charge when a hippogryph egg cannot be saved.",h="Curgle Cranklehop takes charge when a hippogryph egg cannot be saved.",sec={{t="An Egg Beyond Saving",b="Some hippogryph eggs cannot be saved. Curgle Cranklehop handles those that will never hatch.",sp=0},{t="What Becomes of It",b="Curgle takes the egg away for proper disposal. Not every egg can be saved, Curgle says. You can try again with another egg from Feralas.",sp=1}},faq={{q="Who accepts the bad egg?",a="Curgle Cranklehop accepts the bad egg.",al={"who do i give bad egg to","curgle cranklehop egg","who takes bad egg"}},{q="Can the egg be saved?",a="No. A bad egg cannot be saved and will never hatch.",al={"can bad egg hatch","will bad egg hatch","save bad egg"}},{q="What came before this?",a="It follows The Super Egg-O-Matic.",al={"previous quest","pre-req","bad egg prerequisite"}}},kw={"bad egg","curgle cranklehop","feralas","super egg-o-matic","tanaris"},rel={"quest:2741","zone:tanaris","zone:feralas"},m={start="Curgle Cranklehop",["end"]="Curgle Cranklehop",level="60",id=2750},src={"A Bad Egg"}}
E["quest:2781"] = {t="quest",n="WANTED: Caliph Scorpidsting",z="tanaris",s="Across Gadgetzan and Steamwheedle Port, notices call for Caliph Scorpidsting, leader of the Wastewander outlaws. The Gadgetzan Water Company seeks proof of his death in Gadgetzan.",h="Across Gadgetzan and Steamwheedle Port, notices call for Caliph Scorpidsting, leader of the Wastewander...",sec={{t="The Company's Charges",b="In Gadgetzan and Steamwheedle Port, the Gadgetzan Water Company posts a high bounty for Caliph Scorpidsting. The notices accuse him of murdering company employees, stealing its resources and seizing its property. Bring proof of his death to Chief Engineer Bilgewhizzle in Gadgetzan.",sp=0},{t="What the Water Company Hopes For",b="Chief Engineer Bilgewhizzle calls Scorpidsting's death justice and a mighty blow against the Wastewanders. He calls them vile nomads and squatters. The engineer hopes the bounty, paid for the company, will drive them from Gadgetzan's water wells at last.",sp=1}},faq={{q="Who is Caliph Scorpidsting?",a="Caliph Scorpidsting leads the Wastewander outlaws and is wanted by the Gadgetzan Water Company.",al={"caliph scorpidsting lore","who leads wastewanders","scorpidsting"}},{q="Why does the Gadgetzan Water Company want him dead?",a="The company accuses him of murdering its employees, stealing its resources and seizing its property.",al={"why bounty on scorpidsting","caliph scorpidsting crimes","gadgetzan water company enemy"}},{q="Who pays the bounty for Caliph Scorpidsting?",a="The Gadgetzan Water Company pays the bounty. Chief Engineer Bilgewhizzle in Gadgetzan takes proof of Scorpidsting's death.",al={"who turns in scorpidsting","where to turn in caliph head","bilgewhizzle bounty"}},{q="Where are the wanted posters located?",a="The wanted notices are in Gadgetzan and at Steamwheedle Port.",al={"caliph poster location","where to pick up caliph bounty","scorpidsting notice"}}},kw={"bounty","caliph scorpidsting","chief engineer bilgewhizzle","gadgetzan","gadgetzan water company","steamwheedle port","tanaris","wastewander"},rel={"subzone:gadgetzan","zone:tanaris"},m={start="Wanted Poster (Gadgetzan) / Wanted Poster (Steamwheedle Port)",["end"]="Chief Engineer Bilgewhizzle",level="46",faction="Neutral",id=2781,ri={"Caliph Scorpidsting's Head"}},src={"WANTED: Caliph Scorpidsting"}}
E["quest:2865"] = {t="quest",n="Scarab Shells",z="tanaris",s="Tran'rek is looking for uncracked scarab shells in Gadgetzan. Finding intact carapaces in the sands will spare him a great deal of trouble.",h="Tran'rek is looking for uncracked scarab shells in Gadgetzan.",sec={{t="Carapaces for Gadgetzan",b="Whole carapaces are hard to come by in Tanaris. Tran'rek is counting on you to bring five undamaged specimens safely back to the desert post.",sp=0}},faq={{q="Who is asking for scarab shells?",a="Tran'rek is waiting in Gadgetzan for whole scarab carapaces.",al={"who gives scarab shells","who needs scarab shells","gadgetzan tranrek"}},{q="Where can Tran'rek be found?",a="Tran'rek stays in the desert town of Gadgetzan.",al={"where is tranrek","tranrek location","where to turn in scarab shells"}},{q="What kind of shells does Tran'rek need?",a="Tran'rek needs five uncracked scarab shells brought to him in Gadgetzan.",al={"what shells does tranrek want","uncracked scarab shells"}}},kw={"gadgetzan","scarab shells","tanaris","tran'rek","uncracked scarab shells"},rel={"subzone:gadgetzan"},m={id=2865},src={"In-game quest text: Scarab Shells"},fv=true}
E["quest:2873"] = {t="quest",n="Stoley's Shipment",z="tanaris",s="Stoley is out of rum and asks you to recover his stolen shipment. Captain Cuergo keeps it in Lost Rigger Cove, the walled pirate town to the south.",h="Stoley is out of rum and asks you to recover his stolen shipment.",sec={{t="A Stolen Shipment",b="Stoley owes “Sea Wolf” MacKinley of Booty Bay rum for their wager, but his supply is gone. Captain Cuergo took the last shipment and keeps it in Lost Rigger Cove, the walled pirate town to the south. Stoley wants you to bring the rum back so he can prove Kalimdor’s drink is better than anything Booty Bay pours.",sp=0},{t="Where It Is Kept",b="The pirates keep the rum in crates on the upper floor of the house in the northwest.",sp=0}},faq={{q="Who is Stoley?",a="Stoley is at Steamwheedle Port in Tanaris. He owes “Sea Wolf” MacKinley in Booty Bay rum to settle their bet.",al={"stoley","who gives stoleys shipment","stoley tanaris"}},{q="Why does Stoley want his shipment back?",a="Captain Cuergo stole Stoley’s last rum shipment. Stoley needs it to settle his bet with MacKinley and prove Kalimdor’s booze beats Booty Bay’s.",al={"why rum","stoley motivation","what is stoleys shipment"}},{q="Where did the pirates hide the rum?",a="The pirates keep the rum in crates on the upper floor of the northwestern house in Lost Rigger Cove, the walled pirate town to the south.",al={"stoley rum location","where is shipment","lost rigger cove rum"}},{q="Who is Captain Cuergo?",a="Captain Cuergo stole Stoley’s last rum shipment and keeps it in the walled pirate town to the south.",al={"cuergo","captain cuergo"}},{q="Where does this step fit in the chain?",a="It follows Stoley’s Debt.",al={"stoleys shipment chain","what comes after stoleys debt"}},{q="Who is \"Sea Wolf\" MacKinley?",a="“Sea Wolf” MacKinley is in Booty Bay. He wagered with Stoley over whose rum is better.",al={"sea wolf mackinley","mackinley booty bay"}}},kw={"cuergo","lost rigger cove","mackinley","rum","shipment","steamwheedle port","stoley","tanaris"},rel={"quest:2872","quest:2874","subzone:steamwheedle-port","subzone:lost-rigger-cove","subzone:booty-bay","topic:pirate","zone:tanaris"},m={start="Stoley",["end"]="Stoley",level="45",faction="Neutral",id=2873,ri={"Stoley's Shipment"}},src={"Stoley's Shipment (quest)"}}
E["quest:2874"] = {t="quest",n="Deliver to MacKinley",z="tanaris",s="At Steamwheedle Port, Stoley gives you bilge rum for MacKinley in Booty Bay. The Sea Wolf can judge whether the drink settles his beliefs about Booty Bay booze.",h="At Steamwheedle Port, Stoley gives you bilge rum for MacKinley in Booty Bay.",sec={{t="A Bottle to Carry",b="After you help with the shipment, Stoley gives you a bottle of Steamwheedle bilge rum. You carry it to MacKinley in Booty Bay, where he can finally set aside his beliefs about the booze there.",sp=0},{t="MacKinley's Verdict",b="MacKinley tastes the rum and delights in its awfulness. Stoley kept his word about the bilge rum, so MacKinley need not pay the money he owes. He calls it thick as gravel and burning like lava.",sp=1}},faq={{q="Who gives you the bottle?",a="Stoley gives you the bottle at Steamwheedle Port.",al={"who starts deliver to mackinley","deliver to mackinley quest giver"}},{q="Who receives the bottle of rum?",a="The bottle goes to “Sea Wolf” MacKinley in Booty Bay.",al={"where do i take the bottle","who gets the rum","mackinley location"}},{q="What kind of alcohol is being delivered?",a="A bottle of Steamwheedle bilge rum.",al={"what rum is it","what booze does stoley give"}},{q="Where does this step fit in the chain?",a="This follows Stoley's Debt and Stoley's Shipment.",al={"what comes before deliver to mackinley","deliver to mackinley quest chain"}}},kw={"booty bay","mackinley","sea wolf mackinley","steamwheedle bilge rum","stoley","stoley's debt","stoley's shipment","tanaris"},rel={"quest:2873","quest:2872","subzone:booty-bay","zone:tanaris"},m={start="Stoley",["end"]="\"Sea Wolf\" MacKinley",level="45",faction="Neutral",id=2874},src={"Deliver to MacKinley"}}
E["quest:2875"] = {t="quest",n="WANTED: Andre Firebeard",z="tanaris",s="In Gadgetzan and Steamwheedle Port, a wanted notice names Andre Firebeard and accuses him of crimes against both places. Deliver his head to Security Chief Bilgewhizzle at Steamwheedle Port, and it counts as a binding contract.",h="In Gadgetzan and Steamwheedle Port, a wanted notice names Andre Firebeard and accuses him of crimes against...",sec={{t="The Decree",b="A notice condemns Andre Firebeard as a vile pirate accused of crimes against Steamwheedle and Gadgetzan. The governing counsel allows anyone who reads it to use lethal force to capture Andre and those who aid him. He can be found at the pirate enclave south along the coast from Steamwheedle Port, standing by a campfire inside its walls.",sp=0},{t="The Head as Proxy",b="A further decree says Andre's head may speak for him if he is dead or otherwise unable to attend his hearing. Delivered to Security Chief Bilgewhizzle at Steamwheedle Port, it counts as a binding contract.",sp=0},{t="Terms of Payment",b="Bilgewhizzle is pleased that Andre will make his trial after all. Payment comes once you sign. He waves off the small print as harmless, saying it is too small for any magnifying glass to read.",sp=1}},faq={{q="Who is Andre Firebeard?",a="Andre Firebeard is a pirate accused of crimes against Steamwheedle and Gadgetzan.",al={"andre firebeard","who is andre","firebeard tanaris"}},{q="Where can the wanted notice be found?",a="The wanted notice is posted in Gadgetzan and at Steamwheedle Port.",al={"where to get quest","wanted poster location","wanted andre firebeard poster"}},{q="Where is Andre Firebeard located?",a="Andre Firebeard is at a campfire inside the walls of the pirate enclave south along the coast from Steamwheedle Port.",al={"firebeard location","where is firebeard","find andre firebeard"}},{q="Who receives the head once Andre is dealt with?",a="Security Chief Bilgewhizzle receives the head at Steamwheedle Port.",al={"who do i turn in firebeard to","bilgewhizzle location","where to turn in firebeard head"}},{q="Why is his head required?",a="A decree lets his head act in Andre's place if he is dead or otherwise unable to attend his hearing.",al={"why his head","head as proxy","trial proxy"}}},kw={"andre firebeard","bilgewhizzle","gadgetzan","pirate enclave","steamwheedle port","tanaris","wanted poster"},rel={"subzone:steamwheedle-port","subzone:gadgetzan","zone:tanaris","topic:pirate"},m={start="Wanted Poster (Gadgetzan) / Wanted Poster (Steamwheedle Port)",["end"]="Security Chief Bilgewhizzle",level="45",faction="Neutral",id=2875,ri={"Firebeard's Head"}},src={"WANTED: Andre Firebeard"}}
E["quest:2876"] = {t="quest",n="Ship Schedules",z="tanaris",s="At Steamwheedle Port, some voyages bear marks on the ship schedule. It belongs with someone in authority there.",h="At Steamwheedle Port, some voyages bear marks on the ship schedule.",sec={{t="The Scroll",b="Ships sail between Steamwheedle Port and Booty Bay, and the scroll names them all. It records voyages already made and those still to come. Large X marks cross some journeys. Notes beside others warn of plunder or a hard fight. Someone in authority at Steamwheedle Port needs the schedule.",sp=0},{t="The Port's Reaction",b="Security Chief Bilgewhizzle checks the schedule and finds its dates and times accurate. He fears what a pirate captain could do with that knowledge. When you tell him you took it from a pirate, Bilgewhizzle calls the news disturbing and thanks you. He is glad the pirate is dead.",sp=1}},faq={{q="What is written on the schedule?",a="The schedule names ships and records past and future voyages between Steamwheedle Port and Booty Bay. Large X marks cross some journeys, and other notes mention plunder or a hard fight.",al={"what does the ship schedule say","ship schedule text","shipment notes"}},{q="Who needs to see this document?",a="Someone in authority at Steamwheedle Port needs the schedule. Security Chief Bilgewhizzle takes it.",al={"who do i give the schedule to","ship schedules turn in","where does the schedule go"}}},kw={"bilgewhizzle","booty bay","pirates","ship schedules","steamwheedle port","tanaris"},rel={"subzone:steamwheedle-port","subzone:booty-bay","topic:pirate","zone:tanaris"},m={start="Ship Schedule",["end"]="Security Chief Bilgewhizzle",level="45",id=2876},src={"Ship Schedules"}}
E["quest:2944"] = {t="quest",n="The Super Snapper FX",z="tanaris",s="Curgle Cranklehop has a new device for you to try: the Super Snapper FX. Aim it at Gammerita, a creature from the Hinterlands, then bring the picture and device to Daryn Lightwind in Rut'theran Village. This follows The Borrower.",h="Curgle Cranklehop has a new device for you to try: the Super Snapper FX.",sec={{t="A Device to Test",b="After The Borrower, Curgle Cranklehop puts a new invention in your hands: the Super Snapper FX. Aim it at what you want pictured, then press the button. Curgle gives it to you to try.",sp=0},{t="The Subject",b="Gammerita, a creature from the Hinterlands, is the subject you mentioned to Curgle. He wishes you luck in finding her and expects Daryn Lightwind to be pleased with the snapshot. Once you have the picture, bring it and the device to Daryn in Rut'theran Village.",sp=0}},faq={{q="Who gives the Super Snapper FX?",a="Curgle Cranklehop gives you the Super Snapper FX to try.",al={"who gives super snapper","curgle quest giver","where to get super snapper fx"}},{q="What do I photograph with the Super Snapper FX?",a="Photograph Gammerita, a creature from the Hinterlands. Curgle wishes you luck finding her.",al={"gammerita location","where is gammerita","gammerita snapshot"}},{q="Who receives the snapshot?",a="Daryn Lightwind in Rut'theran Village receives both the snapshot and the device.",al={"turn in super snapper fx","where does the picture go","who is daryn lightwind"}},{q="What comes next in the chain?",a="The chain continues with Return to Troyas.",al={"next quest after super snapper","what follows super snapper fx"}}},kw={"curgle cranklehop","daryn lightwind","gammerita","rut'theran village","snapshot","super snapper fx","the hinterlands"},rel={"quest:2941","quest:2943","zone:hinterlands","subzone:rut-theran-village","zone:feralas"},m={start="Curgle Cranklehop",["end"]="Daryn Lightwind",level="48",faction="Alliance",id=2944,ri={"Snapshot of Gammerita"}},src={"The Super Snapper FX"}}
E["quest:2954"] = {t="quest",n="The Stone Watcher",z="tanaris",s="At the Uldum Pedestal, The Stone Watcher guards the way into the compound. You have carried the platinum discs across Tanaris, and now it asks you to learn its story before you go on.",h="At the Uldum Pedestal, The Stone Watcher guards the way into the compound.",sec={{t="A Guardian at the Pedestal",b="At the Uldum Pedestal, the Stone Watcher blocks the way into the Uldum compound. You brought the platinum discs across Tanaris. The guardian says entry is allowed only when the Plates of Uldum are part of your set. Learn the Watcher's story, then use the pedestal.",sp=0},{t="What the Watcher Explains",b="The Stone Watcher controls entry to the Uldum complex for the Creators. It admits only those with the proper sequencing discs. The Plates of Uldum are made by the Creators and record their work at Uldum. They are nearly the size of your own discs, but their markings concern Uldum rather than Uldaman.\n\nUldum is a research facility where the Creators work to enhance Azeroth's biosphere. Only those who hold the Plates can learn the details of that work. The Watcher promises to return your discs once you access the pedestal. It will let you enter the complex when the Plates are in your set.",sp=1},{t="More From the Watcher",b="The Stone Watcher says the Creators control the distribution of discs for every complex on this world. Azeroth has been rescheduled for a visitation. The Creators use visitation to restore control over seeded worlds when forces from outside or within upset the balance of their matrix dynamics. The Watcher warns that visitation is not to be taken lightly.",sp=2}},faq={{q="Who is the Stone Watcher of Norgannon?",a="At the Uldum Pedestal in Tanaris, the Stone Watcher guards entry to the Uldum compound and decides who may enter.",al={"what is the stone watcher","who is the watcher at uldum","stone watcher identity"}},{q="Why does the Stone Watcher deny entry?",a="The Stone Watcher admits only those whose disc set includes the Plates of Uldum. Your set does not yet include them.",al={"why can't i enter uldum","plates of uldum missing","uldum entry denied"}}},kw={"creators","plates of uldum","platinum discs","stone watcher of norgannon","tanaris","uldaman","uldum","uldum pedestal"},rel={"subzone:uldum","zone:tanaris","subzone:uldaman"},m={start="Uldum Pedestal",["end"]="Uldum Pedestal",level="50",id=2954},src={"The Stone Watcher"}}
E["quest:3022"] = {t="quest",n="Handle With Care",z="tanaris",s="Curgle Cranklehop sends a crate of eggs to a druid in Rut'theran. The village lies in Teldrassil.",h="Curgle Cranklehop sends a crate of eggs to a druid in Rut'theran.",sec={{t="A Crate of Eggs",b="Curgle Cranklehop entrusts you with a carefully packed crate for Erelas Ambersky. Hippogryph eggs lie inside, bound for the druid.",sp=0},{t="The Druid of Rut'theran",b="Erelas Ambersky cares for hippogryph eggs in Rut'theran Village. He helps them hatch and trains the young hippogryphs. Rut'theran is a small village in southern Teldrassil.",sp=0}},faq={{q="What is inside the crate from Curgle Cranklehop?",a="Curgle Cranklehop's carefully packed crate holds hippogryph eggs.",al={"what is in the crate","carefully packed crate contents","what am i carrying"}},{q="Where does the crate need to go?",a="Carry the crate to Erelas Ambersky, a druid in Rut'theran, a small village in Teldrassil.",al={"where do i take the crate","erelas ambersky location","where is rut'theran village"}},{q="Who is Erelas Ambersky?",a="Erelas Ambersky is a druid in Rut'theran Village. He cares for hippogryph eggs and trains the young hippogryphs after they hatch.",al={"who is erelas","ambersky lore","who receives the eggs"}}},kw={"curgle cranklehop","erelas ambersky","hippogryph eggs","rut'theran village","tanaris","teldrassil"},rel={"subzone:rut-theran-village","zone:tanaris"},m={start="Curgle Cranklehop",["end"]="Erelas Ambersky",level="47",faction="Alliance",id=3022},src={"Handle With Care (Tanaris)"}}
E["quest:3042"] = {t="quest",n="Troll Temper",z="tanaris",s="In Gadgetzan, the smith Trenton Lighthammer requires twenty vials of troll temper for his metalwork. Providing these supplies ensures he has enough material to keep his anvil working for days.",h="In Gadgetzan, the smith Trenton Lighthammer requires twenty vials of troll temper for his metalwork.",sec={{t="The Smith in Gadgetzan",b="Trenton Lighthammer needs materials to treat his metalwork in Gadgetzan. Gathering twenty vials of troll temper ensures his anvil stays busy for days to come.",sp=0},{t="Supplying the Anvil",b="Delivering the twenty vials brings great relief to the smith. Trenton marvels at the quality and sheer quantity of the temper, paying you for your trouble before returning to days of work at his anvil.",sp=1}},faq={{q="Who needs the Troll Temper?",a="Trenton Lighthammer seeks the temper in Gadgetzan. The smith intends to use it at his anvil for his metalworking.",al={"who wants troll temper","troll temper quest giver","who is trenton lighthammer"}},{q="Where is Trenton Lighthammer?",a="Trenton Lighthammer is located in the desert goblin settlement of Gadgetzan. You can find him working his craft there.",al={"where is trenton lighthammer","trenton lighthammer location"}},{q="What will Trenton Lighthammer do with the temper?",a="Trenton Lighthammer uses the temper for his metalwork, noting that twenty vials will keep him busy at the forge for days.",al={"what is trenton doing with temper","why does trenton want temper"}},{q="How many vials of temper does Trenton need?",a="Trenton Lighthammer requires twenty vials of troll temper to keep his forge supplied.",al={"how many vials of troll temper","troll temper amount"}}},ang={["profession:Blacksmithing"]="Trenton Lighthammer needs a steady supply of temper to treat his metalwork at the forge. Delivering these vials keeps his hammer ringing for days."},kw={"blacksmithing","gadgetzan","tanaris","trenton lighthammer","troll temper","vials of troll temper"},rel={"subzone:gadgetzan","topic:troll"},m={id=3042},src={"In-game quest text: Troll Temper"},fv=true}
E["quest:3161"] = {t="quest",n="Gahz'ridian",z="tanaris",s="In Tanaris, Marvon Rivetseeker searches for thirty ornaments left by its old trolls. He gives you a detector of his own making to help find them.",h="In Tanaris, Marvon Rivetseeker searches for thirty ornaments left by its old trolls.",sec={{t="Relics of the Hydra God",b="Long ago, trolls lived in Tanaris and carved ornaments in the likeness of Gahz'rilla, the hydra they revered as a god. Marvon Rivetseeker named the element in the carvings Gahz'ridian, after the hydra. He has found a few ornaments and wants more to study.",sp=0},{t="The Detector",b="Marvon Rivetseeker gives you a detector he invented to make finding Gahz'ridian easier. Wear it, and the search begins. The ornaments may lie almost anywhere in Tanaris. They are thickest near Broken Pillar, the Eastmoon Ruins and the Southmoon Ruins.",sp=0}},faq={{q="Who is Marvon Rivetseeker?",a="Marvon Rivetseeker is a scientist in Tanaris who studies ornaments made by the old trolls and has a heart for treasure hunting.",al={"marvon rivetseeker","who gives gahzridian","quest giver"}},{q="What is Gahz'ridian?",a="Gahz'ridian is the name Marvon Rivetseeker gave the element carved into the trolls' ornaments of the hydra god.",al={"what is gahzridian","gahzridian mineral","gahzridian material"}},{q="Who is Gahz'rilla?",a="Gahz'rilla is a hydra the old trolls revered as a god. They carved ornaments in its likeness.",al={"gahzrilla deity","hydra worship","who is gahzrilla"}},{q="Where are Gahz'ridian ornaments found?",a="Gahz'ridian ornaments may be found almost anywhere in Tanaris, but they are thickest near Broken Pillar, the Eastmoon Ruins and the Southmoon Ruins.",al={"where to find gahzridian","best place for gahzridian","gahzridian locations"}},{q="How do you find the ornaments?",a="Marvon Rivetseeker invented a detector to help find the ornaments. Wear it to begin the search.",al={"how to spot ornaments","gahzridian detector","finding gahzridian"}}},kw={"broken pillar","detector","eastmoon ruins","gahz'ridian","gahz'rilla","marvon rivetseeker","southmoon ruins","tanaris","troll"},rel={"zone:tanaris","subzone:broken-pillar","subzone:eastmoon-ruins","subzone:southmoon-ruins"},m={start="Marvon Rivetseeker",["end"]="Marvon Rivetseeker",level="48",faction="Neutral",id=3161,ri={"Gahz'ridian Ornament"}},src={"Gahz'ridian (quest)"}}
E["quest:32"] = {t="quest",n="Rise of the Silithid",z="tanaris",s="In Orgrimmar, you carry Senior Surveyor Fizzledowser's report on the insect threat to Zilzibin Drumlore.",h="In Orgrimmar, you carry Senior Surveyor Fizzledowser's report on the insect threat to Zilzibin Drumlore.",sec={{t="Someone Who Knows",b="Senior Surveyor Fizzledowser wants the report in the hands of someone who understands such matters. Zilzibin Drumlore is a troll scholar and historian who has spent much time studying Azeroth's unique life forms. Fizzledowser hopes Zilzibin can learn what the danger is and how it might be stopped. All the help they can get will be needed. Zilzibin lives in a house on the Drag's second tier, in Orgrimmar.",sp=0},{t="Zilzibin's Answer",b="Zilzibin Drumlore has faced these creatures before. He believes Fizzledowser chose well in sending the report, and you with it. They will devour the Tanaris desert swiftly and rank among the greatest menaces anyone will face. They are the silithid, tools of one of the gravest threats to both Horde and Alliance. Zilzibin grieves that no one saw the danger sooner.",sp=1}},faq={{q="Who is Zilzibin Drumlore?",a="Zilzibin Drumlore is a troll scholar and historian who has spent much time studying the life forms unique to Azeroth's ecology.",al={"who is drumlore","zilzibin drumlore lore","troll scholar in orgrimmar"}},{q="Who sends you to Zilzibin?",a="Senior Surveyor Fizzledowser gives you the report and asks you to carry it to Orgrimmar.",al={"rise of the silithid start","who gives rise of the silithid"}},{q="Where is Zilzibin Drumlore located in Orgrimmar?",a="Zilzibin Drumlore lives in a house on the Drag's second tier, in Orgrimmar.",al={"where is zilzibin","where is drumlore house"}},{q="What comes directly before this step?",a="This follows Insect Part Analysis.",al={"previous quest rise of the silithid","what led to rise of the silithid"}}},kw={"drag","drumlore","fizzledowser","insects","orgrimmar","silithid","tanaris","zilzibin"},rel={"npc:senior-surveyor-fizzledowser","quest:113","zone:tanaris","zone:orgrimmar","subzone:drag","topic:troll","topic:horde","topic:alliance"},m={start="Senior Surveyor Fizzledowser",["end"]="Zilzibin Drumlore",level="48",faction="Horde",id=32},src={"Rise of the Silithid (Horde)"}}
E["quest:3362"] = {t="quest",n="Thistleshrub Valley",z="tanaris",s="In Tanaris, strange beasts keep Tran'rek from entering Thistleshrub Valley. They hope to return once the creatures are cleared away.",h="In Tanaris, strange beasts keep Tran'rek from entering Thistleshrub Valley.",sec={{t="A Dangerous Valley",b="South-west of Gadgetzan, Tran'rek warns that Thistleshrub Valley is a dangerous place. Strange beasts roam there, including gnarled thistleshrubs and thistleshrub rootshapers. With so many about, Tran'rek will not return.",sp=0},{t="Thinning the Thistleshrubs",b="Tran'rek asks you to clear out eight gnarled thistleshrubs and eight thistleshrub rootshapers. They also want a closer look at the cactus in the valley, so leave some of it in one piece.",sp=0}},faq={{q="Who asks for help with Thistleshrub Valley?",a="Tran'rek, in Gadgetzan, asks for help.",al={"quest giver","tran'rek location","who offers thistleshrub valley"}},{q="Where is Thistleshrub Valley?",a="Thistleshrub Valley lies south-west of Gadgetzan.",al={"thistleshrub valley location","where is valley","find valley tanaris"}},{q="Which creatures need clearing out?",a="Clear out eight gnarled thistleshrubs and eight thistleshrub rootshapers.",al={"targets","what to kill","which thistleshrubs"}},{q="Why does Tran'rek want some of the cactus left in one piece?",a="Tran'rek wants a closer look at the cactus in the valley, so leave some of it in one piece.",al={"tranrek motive","why go to valley","cacti interest"}}},kw={"cactus","gadgetzan","gnarled thistleshrub","rootshaper","tanaris","thistleshrub","tran'rek","thistleshrub valley"},rel={"subzone:thistleshrub-valley","subzone:gadgetzan","zone:tanaris"},m={start="Tran'rek",["end"]="Tran'rek",level="50",faction="Neutral",id=3362},src={"Thistleshrub Valley (quest)"}}
E["quest:3444"] = {t="quest",n="The Stone Circle",z="tanaris",s="Marvon Rivetseeker waits in Ratchet for a serpent-marked stone. He barely escaped the Sunken Temple, and hopes it will bring back his memories.",h="Marvon Rivetseeker waits in Ratchet for a serpent-marked stone.",sec={{t="Marvon's Memory",b="Marvon Rivetseeker remembers the evil that touched everyone who entered the Sunken Temple. Escaping meant struggling through ooze spread across the floors. One place stayed with him: a large round room crowded with serpent statues.",sp=0},{t="The Stone in Ratchet",b="Marvon Rivetseeker found a round stone marked with what seems to be the same serpent symbol. He had it crated and sent to his workshop in Ratchet. Bring it to him, and he may remember more.",sp=0},{t="When the Stone Returns",b="Marvon Rivetseeker recognizes the stone as the right one. His memories begin to return.",sp=1}},faq={{q="Who is Marvon Rivetseeker?",a="Marvon Rivetseeker asks you to bring him a stone. He once entered the Sunken Temple and barely escaped.",al={"marvon rivetseeker","who gives the stone circle quest","questgiver tanaris"}},{q="Where is the stone circle?",a="The stone was crated and sent to Marvon Rivetseeker's workshop in Ratchet.",al={"where is the stone circle","stone circle workshop","stone circle location"}},{q="Why does Marvon want the stone circle?",a="The stone bears a serpent symbol like the statues Marvon Rivetseeker remembers from a round room in the Sunken Temple. With the stone in hand, he may be able to say more.",al={"why find the stone circle","stone circle purpose"}},{q="What happened to Marvon in the Sunken Temple?",a="Marvon Rivetseeker barely escaped the Sunken Temple, wading through ooze spread across the floors. He remembers stumbling through a large round room filled with serpent statues.",al={"marvon sunken temple","marvon backstory"}}},kw={"marvon rivetseeker","ratchet","serpent statue","sunken temple","tanaris","stone circle"},rel={"zone:tanaris","subzone:ratchet"},m={start="Marvon Rivetseeker",["end"]="Marvon Rivetseeker",level="51",id=3444,ri={"Stone Circle"}},src={"The Stone Circle"}}
E["quest:351"] = {t="quest",n="Find OOX-17/TN!",z="tanaris",s="In Tanaris, you turn the knob and Find OOX-17/TN! springs to life. Oglethorpe's voice says his homing robot is missing and asks you to carry the beacon to it.",h="In Tanaris, you turn the knob and Find OOX-17/TN!",sec={{t="A Voice From the Egg",b="A knob opens the strange egg, revealing a gnomish contraption. A voice crackles from within and names its speaker as Oglethorpe. His homing robot has gone missing. Oglethorpe has computed where it went down, near the Gaping Chasm in Tanaris, and asks you to take the beacon there.",sp=0},{t="At the Crash Site",b="The missing homing robot at the crash site is a robotic chicken. Oglethorpe says it needs a jump start before it can fly home to Booty Bay for repairs, so you put the beacon inside. Hums and whirs follow as the chicken struggles to stand. Then Oglethorpe's voice comes from the robot itself. It works, but needs major repairs and is too heavy for you to lift.",sp=1}},faq={{q="Who is contacting you through the device?",a="A voice from inside the egg names its speaker as Oglethorpe. He says his homing robot has gone missing.",al={"who is oglethorpe","who speaks through the egg"}},{q="Where did the homing robot crash?",a="Oglethorpe's computed coordinates place the crash near the Gaping Chasm in Tanaris.",al={"where is the robot","where is oox-17/tn","where do i bring the beacon","gaping chasm robot location"}},{q="What is the beacon for?",a="Oglethorpe asks you to bring the beacon to his missing homing robot.",al={"what does the beacon do","what is the egg","why carry the beacon"}}},kw={"distress beacon","gaping chasm","homing robot","mechanical chicken","oglethorpe","oox-17/tn","tanaris"},rel={"quest:648","zone:tanaris","subzone:gaping-chasm","subzone:booty-bay"},m={start="OOX-17/TN Distress Beacon",["end"]="Homing Robot OOX-17/TN",level="48",faction="Neutral",id=351},src={"Find OOX-17/TN!"}}
E["quest:3520"] = {t="quest",n="Screecher Spirits",z="tanaris",s="In Steamwheedle Port, Yeh'kinya asks you to gather the spirits of Feralas vale screechers. They are kin to an ancient god, and he promises to tell you more when you bring back three essences.",h="In Steamwheedle Port, Yeh'kinya asks you to gather the spirits of Feralas vale screechers.",sec={{t="Spirits of Feralas",b="Yeh'kinya says the vale screechers of Feralas are kin to an ancient god. Their spirits are linked to him. He gives you a bramble wand and sends you to southern and central Feralas. Wave it over a fallen vale screecher to draw out its spirit, then touch the spirit to gather its essence. He wants three essences returned with the bramble.",sp=0},{t="What Yeh'kinya Shares",b="Yeh'kinya names the old god as Hakkar the Soulflayer. An ancient troll prophecy foretells the dead god's return to the world. Some expect his return to bring the trolls glory and joy; others fear it will end everything. Yeh'kinya puts no faith in the myth, but knows Hakkar's essence is powerful and should stay out of the wrong hands.",sp=1}},faq={{q="Who gives this quest and where are they?",a="Yeh'kinya asks you in Steamwheedle Port.",al={"who gives screecher spirits","yehkinya location","where is yehkinya"}},{q="Where are the vale screechers?",a="Vale screechers live in southern and central Feralas.",al={"where to find screechers","screecher location","where are screechers in feralas"}},{q="How do you capture the screecher spirits?",a="Wave Yeh'kinya's bramble wand over a fallen vale screecher to draw out its spirit. Then touch the spirit to gather its essence.",al={"how to get screecher spirit","using yehkinyas bramble","bramble wand"}},{q="Why does Yeh'kinya want screecher spirits?",a="Yeh'kinya says the vale screechers are kin to an ancient god, and their spirits are linked to him. He promises to tell you more about the god when you return.",al={"why gather screecher spirits","yehkinya motive"}}},kw={"bramble wand","feralas","screecher spirits","steamwheedle port","tanaris","vale screecher","yeh'kinya"},rel={"npc:yeh-kinya","subzone:steamwheedle-port","zone:tanaris","zone:feralas"},m={start="Yeh'kinya",["end"]="Yeh'kinya",level="44",faction="Neutral",id=3520},src={"Screecher Spirits"}}
E["quest:3527"] = {t="quest",n="The Prophecy of Mosh'aru",z="tanaris",s="In Tanaris, the troll scholar Yeh'kinya seeks the First and Second Mosh'aru Tablets. He needs their ancient writings to learn how to contain the essence of Hakkar before the Blood God can rise.",h="In Tanaris, the troll scholar Yeh'kinya seeks the First and Second Mosh'aru Tablets.",sec={{t="Secrets in the Stone",b="Yeh'kinya waits among the dunes of Tanaris for two pieces of the ancient prophecy. He believes the writings on the First and Second Mosh'aru Tablets hold hidden truths that can be unlocked once brought together. With them in hand, the troll scholar hopes to uncover a way to contain the essence of the Blood God Hakkar.",sp=0},{t="Mending the Prophecy",b="Bringing the ancient stone slabs together allows Yeh'kinya to mend them into a single tablet. Once joined, he can delve into their forgotten knowledge and prepare for the dangers surrounding Hakkar's return.",sp=1}},faq={{q="Who is asking for the tablets?",a="Yeh'kinya, a troll scholar in the sands of Tanaris, asks for them.",al={"who wants the mosharu tablets","yehkinya tablets","who gave this quest"}},{q="Why does Yeh'kinya want the tablets?",a="Yeh'kinya intends to study the ancient writings to learn how to contain the essence of Hakkar.",al={"why does yehkinya want the tablets","mosharu tablets purpose","contain hakkar"}},{q="Which tablets are needed?",a="He requires the First and Second Mosh'aru Tablets, which hold the ancient prophecy.",al={"which tablets are needed","what tablets does yehkinya want"}},{q="Where can Yeh'kinya be found?",a="Yeh'kinya is stationed in the desert land of Tanaris.",al={"where is yehkinya","yehkinya location"}}},kw={"hakkar","mosh'aru","prophecy","tablets","tanaris","yeh'kinya"},rel={"npc:yeh-kinya","zone:tanaris"},m={id=3527},src={"In-game quest text: The Prophecy of Mosh'aru"},fv=true}
E["quest:3528"] = {t="quest",n="The God Hakkar",z="tanaris",s="Yeh'kinya asks you to bring him Hakkar's filled egg in Tanaris. Its stirring life raises a fear about the god's return.",h="Yeh'kinya asks you to bring him Hakkar's filled egg in Tanaris.",sec={{t="Yeh'kinya's Concern",b="After Hakkar's essence has empowered the egg, Yeh'kinya in Tanaris receives it from you. The egg stirs with life, and he wonders whether the myths of Hakkar are true. He fears what Hakkar might do if born again, so he intends to keep the egg from evil hands.",sp=1}},faq={{q="Who is asking for the egg?",a="Yeh'kinya asks you to bring him the Filled Egg of Hakkar in Tanaris.",al={"who wants the egg","yehkinya egg","egg guy"}},{q="What is the Filled Egg of Hakkar?",a="The egg holds Hakkar's essence, and it stirs with life.",al={"hakkar egg","filled egg","what egg"}},{q="Why does Yeh'kinya want the egg?",a="Yeh'kinya fears what Hakkar may do if born again, so he plans to keep the egg from evil hands.",al={"why egg","yehkinya wants egg","what's he doing with it"}},{q="What happens to Hakkar's essence?",a="Hakkar's essence empowers the egg, which then stirs with life.",al={"hakkar essence","essence egg","did essence empower it"}}},kw={"avatar","filled egg","hakkar","hakkar's essence","tanaris","yeh'kinya"},rel={"zone:tanaris","npc:yeh-kinya"},m={id=3528},src={"In-game quest text: The God Hakkar"},fv=true}
E["quest:379"] = {t="quest",n="Slake That Thirst",z="tanaris",s="In Gadgetzan, Chief Engineer Bilgewhizzle needs five Wastewander Water Pouches before he can supply the 4711-FTZ power source for your kit. The Wastewander nomads east of town carry them.",h="In Gadgetzan, Chief Engineer Bilgewhizzle needs five Wastewander Water Pouches before he can supply the...",sec={{t="A Drink for a Power Source",b="Chief Engineer Bilgewhizzle in Gadgetzan can help with the power source your kit needs after Into the Field. First, he asks you for five Wastewander Water Pouches. The Wastewander nomads live east of Gadgetzan, and Bilgewhizzle suggests you walk up and ask one for water. He wants to hear how it goes.",sp=0},{t="A Limit on the Power",b="The 4711-FTZ power source was not made for a science kit. Once you hand over the pouches, you can use it, but your gathered data lasts two hours at most. Bring the source back to Bilgewhizzle when you have what you need, so he can shut it down properly. If time runs out, you can get another source, but you will have to buy it.",sp=1}},faq={{q="Who asks for the water pouches?",a="Chief Engineer Bilgewhizzle in Gadgetzan asks for five Wastewander Water Pouches in return for the 4711-FTZ power source.",al={"who gives slake that thirst","bilgewhizzle quest","gadgetzan engineer water"}},{q="Where do you find the Wastewander Water Pouches?",a="You can get Wastewander Water Pouches from the Wastewander nomads east of Gadgetzan.",al={"where are wastewander water pouches","nomad water tanaris","wastewander pouches location"}},{q="What power source does Chief Engineer Bilgewhizzle offer?",a="Bilgewhizzle offers the 4711-FTZ power source for your kit.",al={"what item does bilgewhizzle give","4711 ftz power source","power source name"}},{q="What came before this step?",a="Into the Field comes before this step.",al={"slake that thirst prerequisite","previous quest for slake that thirst","into the field connection"}}},kw={"4711-ftz","bilgewhizzle","gadgetzan","power source","tanaris","wastewander","water pouch"},rel={"quest:243","quest:841","subzone:gadgetzan","zone:tanaris"},m={start="Chief Engineer Bilgewhizzle",["end"]="Chief Engineer Bilgewhizzle",level="46",faction="Horde",id=379},src={"Slake That Thirst"}}
E["quest:4496"] = {t="quest",n="Bungle in the Jungle",z="tanaris",s="In Gadgetzan, Alchemist Pestlezugg studies the silithid and likens them to bees. He believes their queen is the weak point, and needs scent and soil from Un'Goro Crater to the west.",h="In Gadgetzan, Alchemist Pestlezugg studies the silithid and likens them to bees.",sec={{t="A Lure for the Queen",b="Alchemist Pestlezugg likens the silithid to bees. He believes that if their queen is destroyed, the rest will fall into disarray. A lure can draw her out. You are to bring her down when she appears.",sp=0},{t="Reagents from Un'Goro",b="To make the lure, Pestlezugg needs reagents from Un'Goro Crater. The silithid hive lies west of Gadgetzan. He asks you to bring an undamaged scent gland from one of the bugs and five samples of the native soil.",sp=0}},faq={{q="Who asks for the scent gland and soil, and where?",a="Alchemist Pestlezugg asks for them in Gadgetzan.",al={"who gives bungle in the jungle","where is pestlezugg","bungle in the jungle questgiver"}},{q="What does Pestlezugg need for the lure?",a="Pestlezugg needs one undamaged Gorishi scent gland from a silithid bug and five samples of native Un'Goro soil.",al={"bungle in the jungle items","what reagents does pestlezugg need","scent gland and soil"}},{q="Where is the silithid hive?",a="The silithid hive is in Un'Goro Crater, west of Gadgetzan.",al={"where to find gorishi scent gland","where is the silithid hive","where is un'goro soil found"}},{q="Why does Pestlezugg want to bring out the hive queen?",a="Pestlezugg likens the silithid to bees and believes that without their queen, the rest will fall into disarray.",al={"why kill the queen","pestlezugg plan","silithid bee theory"}}},kw={"gadgetzan","gorishi","pestlezugg","scent gland","silithid","tanaris","un'goro crater","un'goro soil"},rel={"quest:4507","subzone:gadgetzan","zone:ungoro","zone:tanaris"},m={start="Alchemist Pestlezugg",["end"]="Alchemist Pestlezugg",level="53",id=4496},src={"Bungle in the Jungle"}}
E["quest:4504"] = {t="quest",n="Super Sticky",z="tanaris",s="In Gadgetzan, Tran'rek sees quick gold in super sticky glue. He needs tar from beasts near the pits in northern Un'Goro Crater and offers a little of the profit.",h="In Gadgetzan, Tran'rek sees quick gold in super sticky glue.",sec={{t="A Sticky Idea",b="Tran'rek hopes his newest idea will bring quick gold, and offers you a little of the profit. Ordinary tar is not sticky enough. He wants twelve samples from creatures near the tar pits in northern Un'Goro Crater.",sp=0},{t="Why the Beasts",b="The plant-like creatures around the pits have chlorophyll in their skin. Mixed with tar, it makes a super sticky glue.",sp=0},{t="Once the Tar Arrives",b="When Tran'rek handles the tar, his hands soon stick together. He changes his plan on the spot. A super sticky tar remover, he decides, is where the real money lies.",sp=1}},faq={{q="Who asks for the sticky tar?",a="Tran'rek in Gadgetzan asks for the sticky tar.",al={"who gives super sticky","super sticky quest giver","tran'rek quest"}},{q="Why does the tar have to come from beasts?",a="Ordinary tar is not sticky enough. The plant-like creatures around the tar pits have chlorophyll in their skin, which makes the tar super sticky.",al={"why beast tar","regular tar vs sticky tar","why get tar from beasts"}},{q="Where are the tar beasts?",a="The tar beasts live by the tar pits in northern Un'Goro Crater.",al={"where is super sticky tar","tar beasts location","ungoro tar pits"}},{q="What does Tran'rek plan to do with the tar?",a="Tran'rek plans to make super sticky glue for quick gold and offers a little of the profit to whoever helps.",al={"tranrek goal","super sticky purpose","why does tran'rek want tar"}}},kw={"chlorophyll","gadgetzan","glue","super sticky tar","tanaris","tar pits","tran'rek","un'goro crater"},rel={"subzone:gadgetzan","zone:tanaris","zone:ungoro"},m={start="Tran'rek",["end"]="Tran'rek",level="54",faction="Neutral",id=4504,ri={"Super Sticky Tar"}},src={"Super Sticky (Classic)"}}
E["quest:4507"] = {t="quest",n="Pawn Captures Queen",z="tanaris",s="Alchemist Pestlezugg sends you into Un'Goro Crater with a lure for the Gorishi Hive Queen. After Bungle in the Jungle, he wants her brain brought to Gadgetzan for study.",h="Alchemist Pestlezugg sends you into Un'Goro Crater with a lure for the Gorishi Hive Queen.",sec={{t="The Lure and the Crystal",b="Pestlezugg gives you a lure for the silithid hive. He believes a crystal in the hive network attunes the whole swarm, and the hatcheries are the best place to search. Apply the lure to the crystal, and the queen should emerge with several guards beside her.",sp=0},{t="The Queen's Brain",b="Pestlezugg wants you to carry the queen's brain to Gadgetzan. He knows it sounds icky, but says the brain is badly needed for study.",sp=0},{t="After the Queen Falls",b="Pestlezugg suspects a malign intelligence may control the silithid. The thought of what could command something so insidious makes him shudder. When the brain arrives, he calls it quite a victory, yet doubts this is the full extent of the silithid presence. The resolution seems too clean to him.",sp=1}},faq={{q="Where is the Gorishi Hive Queen?",a="Use Pestlezugg's lure on a crystal in the silithid hive in Un'Goro Crater. He expects to find one in the hatcheries, where it should draw out the queen.",al={"gorishi queen location","where is the silithid queen","where to find gorishi queen"}},{q="What is the crystal in the hive for?",a="Pestlezugg thinks a crystal in the hive network attunes the whole silithid swarm. The lure is meant for that crystal, and the hatcheries are the place to search.",al={"hive crystal","queen lure crystal","using queen lure"}},{q="Why does Pestlezugg want the queen's brain?",a="Pestlezugg says the queen's brain is badly needed for study and wants you to bring it to Gadgetzan.",al={"why gorishi brain","gorishi queen brain purpose","pestlezugg research"}},{q="What comes before this?",a="Before this, Pestlezugg asked you for a scent gland and Un'Goro soil to brew the lure in Bungle in the Jungle.",al={"pawn captures queen prerequisites","what quest comes before pawn captures queen","previous quest"}}},kw={"brain","gadgetzan","gorishi","lure","pestlezugg","queen","silithid","tanaris","un'goro"},rel={"quest:4496","subzone:gadgetzan","zone:ungoro","zone:tanaris"},m={start="Alchemist Pestlezugg",["end"]="Alchemist Pestlezugg",level="54",id=4507,ri={"Gorishi Queen Brain"}},src={"Pawn Captures Queen"}}
E["quest:4508"] = {t="quest",n="Calm Before the Storm",z="tanaris",s="After the queen falls, you carry the latest findings from Un'Goro beyond Gadgetzan. Alchemist Pestlezugg sends the report to Gracina Spiritmight at the Temple of the Moon in Darnassus.",h="After the queen falls, you carry the latest findings from Un'Goro beyond Gadgetzan.",sec={{t="A Report for Darnassus",b="Alchemist Pestlezugg says Gadgetzan cannot face the silithid alone. The latest findings from Un'Goro must reach someone who can act on them, so you carry the report to Gracina Spiritmight in Darnassus. Pestlezugg hopes she is at the Temple of the Moon. She has friends among the Alliance's leading figures, and drawing them in may offer a way through this alive.",sp=0},{t="Gracina's Answer",b="Gracina Spiritmight welcomes the report, yet doubts it will help. She says those who cannot look past their hatred of the Horde are fools. The Alliance ignores every threat but the Horde, and even Darnassus's leaders disagree about the silithid. Gracina says Fandral Staghelm believes they are unlike the ancient peril she sees in them. She cannot prove the danger further without dropping someone into a hive. She urges you to stay committed to defeating the silithid.",sp=1}},faq={{q="Who sends you with the report?",a="Alchemist Pestlezugg sends you from Gadgetzan with the report of the latest findings from Un'Goro.",al={"who starts calm before the storm","quest giver calm before the storm","where does calm before the storm start"}},{q="Where must the report be delivered?",a="Deliver the report to Gracina Spiritmight in Darnassus, at the Temple of the Moon, where Pestlezugg last knew her to be.",al={"where do i take pestlezugg's report","where is gracina spiritmight","turn in calm before the storm"}},{q="Why does Pestlezugg send the report to Gracina Spiritmight?",a="Gadgetzan cannot face the silithid alone. Gracina has friends among the Alliance's leading figures, and drawing them in may offer a way through this alive.",al={"why send to darnassus","why gracina spiritmight"}},{q="What comes directly before this?",a="Pawn Captures Queen comes directly before this. You were sent after the Gorishi Hive Queen.",al={"prerequisite for calm before the storm","previous quest calm before the storm"}}},kw={"darnassus","gadgetzan","gracina spiritmight","pestlezugg","silithid","tanaris","temple of the moon","un'goro report"},rel={"quest:4507","subzone:gadgetzan","zone:tanaris","zone:darnassus","subzone:temple-of-the-moon"},m={start="Alchemist Pestlezugg",["end"]="Gracina Spiritmight",level="54",faction="Alliance",id=4508},src={"Calm Before the Storm (Alliance)"}}
E["quest:4509"] = {t="quest",n="Calm Before the Storm",z="tanaris",s="After the queen's fall, Alchemist Pestlezugg sends his latest findings to those who may act. You carry his report on Un'Goro to Zilzibin Drumlore in Orgrimmar.",h="After the queen's fall, Alchemist Pestlezugg sends his latest findings to those who may act.",sec={{t="A Report for Orgrimmar",b="Gadgetzan cannot manage alone, so Alchemist Pestlezugg sends you with his latest findings on Un'Goro. He wants them in the hands of those who can act. Pestlezugg expects Zilzibin Drumlore to be in the upper part of the Drag in Orgrimmar. Zilzibin has friends high in the Horde, and drawing them in may offer a way through this alive.",sp=0},{t="Zilzibin's Answer",b="Zilzibin Drumlore calls those who see only their hatred of the Alliance fools. He says he cannot prove the silithid threat any further without dropping them into a hive. He welcomes the report, but doubts it will help. The Horde ignores every threat but the Alliance. Thrall himself might act if the facts reached him, though conflicting advice presses on him from every side. Zilzibin urges you to stay committed to defeating the silithid.",sp=1}},faq={{q="Who sends you with the report?",a="Alchemist Pestlezugg sends you from Gadgetzan.",al={"quest giver calm before the storm","who gives calm before the storm","pestlezugg quest"}},{q="Where is Zilzibin Drumlore?",a="Zilzibin Drumlore is in Orgrimmar. Pestlezugg expects him in the upper part of the Drag.",al={"zilzibin drumlore location","where is zilzibin","zilzibin drumlore orgrimmar"}},{q="Why does Pestlezugg send the report to Zilzibin Drumlore?",a="Gadgetzan cannot manage this alone. Zilzibin has friends high in the Horde, and drawing them in may offer a way through this alive.",al={"why send report to orgrimmar","pestlezugg motive"}},{q="What comes directly before this?",a="Pawn Captures Queen comes directly before this. You were sent after the Gorishi Hive Queen.",al={"calm before the storm prerequisites","previous quest calm before the storm"}}},kw={"calm before the storm","drag","gadgetzan","orgrimmar","pestlezugg","silithid","tanaris","zilzibin drumlore"},rel={"quest:4507","subzone:gadgetzan","subzone:drag","zone:orgrimmar","zone:tanaris"},m={start="Alchemist Pestlezugg",["end"]="Zilzibin Drumlore",level="54",faction="Horde",id=4509},src={"Calm Before the Storm (Horde)"}}
E["quest:4787"] = {t="quest",n="The Ancient Egg",z="tanaris",s="In Tanaris, Yeh'kinya seeks the ancient egg named in the Prophecy of Mosh'aru. It comes from the age of troll empires, and he wants you to bring it from Jintha'Alor in the Hinterlands.",h="In Tanaris, Yeh'kinya seeks the ancient egg named in the Prophecy of Mosh'aru.",sec={{t="A Relic of Troll Empires",b="The Prophecy of Mosh'aru tells of an ancient egg from the age when trolls ruled vast empires. Its power can contain Hakkar's essence. Yeh'kinya believes it may be the only way to guard the world from his evil.",sp=0},{t="Behind the Amphitheater",b="Yeh'kinya asks you to bring the egg to Tanaris. Tales place it deep inside Jintha'Alor in the Hinterlands, in a cave behind the amphitheater atop the city. Great forces stir, and Yeh'kinya fears time is running short.",sp=0}},faq={{q="What is the ancient egg?",a="A relic from the age when trolls ruled vast empires, told of in the Prophecy of Mosh'aru. Its power can hold Hakkar's essence.",al={"ancient egg lore","what does the egg do","prophecy of mosharu egg"}},{q="Why does Yeh'kinya want the egg?",a="Yeh'kinya believes the egg may be the only way to guard the world from Hakkar's evil.",al={"why find the egg","yehkinya purpose","stop hakkar egg"}},{q="Where is the egg hidden?",a="Tales place the egg deep inside Jintha'Alor in the Hinterlands, in a cave behind the amphitheater atop the city.",al={"where is the ancient egg","ancient egg location","egg cave jinthaalor"}},{q="Who wants the egg brought to them?",a="Yeh'kinya waits in Tanaris and wants you to bring the ancient egg there.",al={"who starts ancient egg","who gives the quest","yehkinya questgiver"}}},kw={"ancient egg","hakkar","hinterlands","jintha'alor","mosh'aru","prophecy","tanaris","yeh'kinya"},rel={"npc:yeh-kinya","zone:hinterlands","zone:tanaris","topic:troll"},m={start="Yeh'kinya",["end"]="Yeh'kinya",level="50",faction="Neutral",id=4787,ri={"Ancient Egg"}},src={"The Ancient Egg"}}
E["quest:5801"] = {t="quest",n="Fire Plume Forged",z="tanaris",s="At Fire Plume Ridge, you face the heat needed to forge a skeletal key stem. The simmering volcano lies west in Un'Goro Crater, where its lava lake can fuse the stem. Then you carry it to Alchemist Arbington at Chillwind Point in the Western Plaguelands.",h="At Fire Plume Ridge, you face the heat needed to forge a skeletal key stem.",sec={{t="Fire for the Key Stem",b="Krinkle Goodsteel says the key stem needs two bars of thorium and fierce heat. You find the thorium, and your gold buys a mold. Dip it in the lava lake atop Fire Plume Ridge. There, the heat fuses thorium and bone together.",sp=0},{t="Back to Arbington",b="Krinkle Goodsteel has done their part. To finish the key, you return to Alchemist Arbington at Chillwind Point in the Western Plaguelands. The lava-forged stem remains unfinished. This work prepares you for an assault.",sp=0},{t="What Lies Ahead",b="Alchemist Arbington calls the key costly, yet unfinished. In Andorhal, Araj the Summoner waits as the foe behind all this work. The lich ranks among the Scourge's most powerful.",sp=1}},faq={{q="Where is the key stem forged?",a="The key stem is forged in the lava lake atop Fire Plume Ridge, a simmering volcano west in Un'Goro Crater.",al={"where to forge key","fire plume forged location","lava lake location"}},{q="What is needed to forge the key stem?",a="You need the skeleton key mold and two bars of thorium. You find the thorium yourself.",al={"what do i need","key materials","thorium requirement"}},{q="Who receives the unfinished key?",a="Alchemist Arbington receives the unfinished key at Chillwind Point in the Western Plaguelands.",al={"who do i turn this in to","arbington location","where does unfinished key go"}}},kw={"alchemist arbington","chillwind point","fire plume ridge","krinkle goodsteel","skeleton key mold","thorium","un'goro crater","unfinished skeleton key"},rel={"subzone:fire-plume-ridge","zone:ungoro","subzone:chillwind-point","zone:westernplaguelands","zone:tanaris"},m={start="Krinkle Goodsteel",["end"]="Alchemist Arbington",level="57",faction="Alliance",id=5801,ri={"Unfinished Skeleton Key"}},src={"Fire Plume Forged (Alliance)"}}
E["quest:5802"] = {t="quest",n="Fire Plume Forged",z="tanaris",s="At Fire Plume Ridge, fierce heat can forge the stem of a skeletal key. Krinkle Goodsteel sends you to the volcano west in Un'Goro Crater, where a lava lake crowns its summit. You then carry the stem to Apothecary Dithers at the Bulwark in the Western Plaguelands.",h="At Fire Plume Ridge, fierce heat can forge the stem of a skeletal key.",sec={{t="Fire for the Key Stem",b="Two bars of thorium and fierce heat are needed to forge the key stem. You find the thorium, and Krinkle Goodsteel helps provide the heat. Your gold has bought a mold, ready for the lava lake atop Fire Plume Ridge. There, lava fuses thorium and bone together.",sp=0},{t="Back to Dithers",b="Krinkle Goodsteel has done their part. Now you return to Apothecary Dithers at the Bulwark in the Western Plaguelands to finish the key. The stem forged in lava remains unfinished, and this work prepares for an assault.",sp=0},{t="What Lies Ahead",b="Apothecary Dithers calls the key costly, though it remains unfinished. All this work is aimed at a foe in Andorhal: Araj the Summoner, a lich ranked among the most powerful of the Scourge.",sp=1}},faq={{q="Where is the key stem forged?",a="You forge the key stem in the lava lake atop Fire Plume Ridge, a simmering volcano in Un'Goro Crater, west of Krinkle Goodsteel.",al={"where to forge key","lava lake location","fire plume ridge lava"}},{q="What is needed to forge the key stem?",a="You need a skeleton key mold and two bars of thorium. You find the thorium yourself.",al={"what do i need","key materials","thorium needed"}},{q="Who receives the unfinished key?",a="Apothecary Dithers receives the unfinished key at the Bulwark in the Western Plaguelands.",al={"who to turn in to","where does the key go","hand in key"}}},kw={"andorhal","apothecary dithers","bulwark","fire plume ridge","krinkle goodsteel","skeleton key mold","thorium bar","un'goro crater","unfinished skeleton key"},rel={"subzone:fire-plume-ridge","zone:ungoro","subzone:bulwark","zone:westernplaguelands","zone:tanaris"},m={start="Krinkle Goodsteel",["end"]="Apothecary Dithers",level="57",faction="Horde",id=5802,ri={"Unfinished Skeleton Key"}},src={"Fire Plume Forged (Horde)"}}
E["quest:5863"] = {t="quest",n="The Dunemaul Compound",z="tanaris",s="In the desert south of Gadgetzan, a growing ogre force has Andi Lynn afraid. She wants the compound destroyed before the ogres gather more strength.",h="In the desert south of Gadgetzan, a growing ogre force has Andi Lynn afraid.",sec={{t="Ogres in the Desert",b="A large band of nomadic ogres has reached Tanaris. South of Gadgetzan, they have claimed a broad stretch of desert and made their compound. Smaller bands roam the desert, and some have entered the old troll ruins. Andi Lynn fears what may happen if the ogres grow stronger.",sp=0},{t="Cutting Off the Head",b="Andi Lynn wants ten Dunemaul Brutes and ten Dunemaul Enforcers cut down. Gor'marok the Ravager leads the band. Andi Lynn believes the ogres will begin to crumble once he no longer commands them.",sp=0}},faq={{q="Who asks for the Dunemaul Compound to be destroyed?",a="Andi Lynn, in Gadgetzan, calls for the Dunemaul Compound to be destroyed.",al={"andi lynn","who gives the quest","quest giver"}},{q="Where is the Dunemaul Compound?",a="The ogres have claimed a large stretch of desert south of Gadgetzan.",al={"dunemaul compound location","where are the ogres","dunemaul location"}},{q="Who leads the Dunemaul ogres?",a="Gor'marok the Ravager leads the Dunemaul ogres. Andi Lynn believes they will begin to fall once he no longer commands them.",al={"ogre leader","who is gormarok","gor'marok the ravager"}},{q="Why does Andi Lynn see the ogres as a danger?",a="Andi Lynn fears the ogres will gather strength. A large band holds a compound south of Gadgetzan, while smaller bands roam the desert, and some have entered the old troll ruins.",al={"why kill the ogres","ogre danger tanaris"}}},kw={"andi lynn","dunemaul","dunemaul brute","dunemaul compound","dunemaul enforcer","gadgetzan","gor'marok the ravager","ogres","tanaris"},rel={"subzone:dunemaul-compound","subzone:gadgetzan","zone:tanaris"},m={start="Andi Lynn",["end"]="Andi Lynn",level="49",id=5863},src={"The Dunemaul Compound"}}
E["quest:648"] = {t="quest",n="Rescue OOX-17/TN!",z="tanaris",s="At Steamwheedle Port, OOX-17/TN needs time and open ground for take-off. Oglethorpe's voice comes through the damaged robot, asking you to escort it there safely, then find him in Booty Bay.",h="At Steamwheedle Port, OOX-17/TN needs time and open ground for take-off.",sec={{t="An Escort to the Port",b="Oglethorpe's voice crackles through OOX-17/TN again. The robot has built-in cloaking, but Oglethorpe needs time to make it work again. It needs an open, safe place to begin its lengthy take-off. Oglethorpe has chosen Steamwheedle Port, and the journey there will give him time to restore the cloaking. You are asked to escort the robot safely.",sp=0},{t="Report in Booty Bay",b="Once OOX-17/TN reaches Steamwheedle Port, find Oglethorpe Obnoticus in Booty Bay. He is a master inventor.",sp=0},{t="A Grateful Inventor",b="Oglethorpe greets you as the one who saved OOX-17/TN. The homing robot series still needs more work, but returning this robot has spared countless hours of rebuilding and many gold pieces in rebinding costs. Oglethorpe says the robots and their inventor are in your debt.",sp=1}},faq={{q="Where does the robot need to be escorted?",a="Escort OOX-17/TN to Steamwheedle Port, where it can begin its lengthy take-off safely.",al={"where does oox-17 go","oox-17 escort path","robot destination"}},{q="Who is speaking through the robot?",a="Oglethorpe Obnoticus, a gnome and master inventor, speaks through his homing robot. You can find him in Booty Bay.",al={"who made oox-17","oox-17 creator","who is speaking through the robot"}},{q="Why does the robot need to be moved?",a="The robot needs an open, safe place to begin its lengthy take-off. Its built-in cloaking also needs time to work again.",al={"why move oox-17","why steamwheedle port"}},{q="Where do you report after the escort?",a="Report to Oglethorpe Obnoticus in Booty Bay.",al={"where is oglethorpe obnoticus","who do i turn this in to","oox-17 turn in location"}}},kw={"booty bay","homing robot","mechanical chicken","oglethorpe obnoticus","oox-17/tn","steamwheedle port","tanaris"},rel={"quest:351","zone:tanaris","subzone:booty-bay","subzone:steamwheedle-port","topic:gnome"},m={start="Homing Robot OOX-17/TN",["end"]="Oglethorpe Obnoticus",level="48",faction="Neutral",id=648},src={"Rescue OOX-17/TN!"}}
E["quest:654"] = {t="quest",n="Tanaris Field Sampling",z="tanaris",s="In Tanaris, a field test begins as soon as the kit's power source is switched on. Your two hours of sampling start then.",h="In Tanaris, a field test begins as soon as the kit's power source is switched on.",sec={{t="A Ticking Power Source",b="Chief Engineer Bilgewhizzle expected the kit to glow and vibrate once its power source was running. Now you have two hours to gather acceptable samples from eight basilisks, eight hyenas and eight scorpions in the Tanaris desert.\n\nIf the time runs out, all the data is lost. You will need to buy another power source from Bilgewhizzle, then return the kit to him in Gadgetzan before its power gives out.",sp=0},{t="The Company's Profit",b="Bilgewhizzle offers no sympathy when a kit goes dead. The Gadgetzan Water Company’s profit is all that matters to him.\n\nHe will keep selling power sources until the company can afford to import water from the icy springs of Dun Morogh.",sp=0}},faq={{q="What creatures need to be sampled for the testing kit?",a="Gather acceptable samples from eight Tanaris basilisks, eight hyenas and eight scorpions.",al={"what animals to test","sampling targets","what do i kill"}},{q="How much time is available to complete the sampling?",a="You have two hours from the moment the power source is switched on.",al={"time limit","how long do i have","timer"}},{q="What happens if the power source runs out?",a="All the data in the kit is lost. To begin again, buy another power source from Chief Engineer Bilgewhizzle in Gadgetzan.",al={"if timer runs out","failed quest","power ran out"}},{q="Where does the testing kit go once full?",a="Return the full testing kit to Chief Engineer Bilgewhizzle in Gadgetzan before its power gives out.",al={"who do i turn this in to","turn in location","where is bilgewhizzle"}},{q="Why does Bilgewhizzle keep selling power sources?",a="Bilgewhizzle wants the Gadgetzan Water Company to profit. He will keep selling power sources until it can afford to import water from the icy springs of Dun Morogh.",al={"bilgewhizzle goal","gadgetzan water company goal","why sample"}}},kw={"basilisk","bilgewhizzle","field testing kit","gadgetzan","hyena","power source","scorpion","tanaris","water company"},rel={"subzone:gadgetzan","zone:tanaris","quest:379","quest:841","zone:dunmorogh"},m={start="Model 4711-FTZ Power Source",["end"]="Chief Engineer Bilgewhizzle",level="46",faction="Horde",id=654,ri={"Acceptable Basilisk Sample","Acceptable Hyena Sample","Acceptable Scorpid Sample","Field Testing Kit"}},src={"Tanaris Field Sampling"}}
E["quest:6610"] = {t="quest",n="Clamlette Surprise",z="tanaris",s="Dirge Quikcleave wants supplies for his clamlette, a new culinary creation. In return, he offers to teach you exotic cuisine and prepare a couple for you.",h="Dirge Quikcleave wants supplies for his clamlette, a new culinary creation.",sec={{t="A New Recipe",b="Dirge Quikcleave is ready to show you how he makes his clamlette surprise. He needs giant eggs, zesty clam meat, and Alterac Swiss before he can begin. Gather the ingredients he asks for, and Dirge will teach you about exotic cuisine while preparing the dish.",sp=0}},faq={{q="What is a clamlette?",a="A clamlette is Dirge Quikcleave's latest culinary creation, made with giant eggs, zesty clam meat, and Alterac Swiss.",al={"clamlette surprise","what's a clamlette"}},{q="Who is asking for the ingredients?",a="Dirge Quikcleave wants the ingredients for his clamlette surprise.",al={"who wants the supplies","dirge quest"}},{q="What ingredients does Dirge need?",a="Dirge needs giant eggs, zesty clam meat, and Alterac Swiss.",al={"clamlette ingredients","what do i gather"}},{q="Where can I find the giant eggs?",a="The giant eggs can come from rocs wandering Tanaris or other large birds.",al={"giant egg location","where eggs"}},{q="Where does the zesty clam meat come from?",a="Zesty clam meat can be found in clams.",al={"clam meat source","zesty clam meat"}},{q="Where can I get Alterac Swiss?",a="Dirge says to get Alterac Swiss from a cheesery.",al={"alterac swiss source","cheese for dirge"}},{q="What does Dirge offer in return?",a="Dirge offers to teach you the finer points of exotic cuisine and prepare a couple of clamlettes for you.",al={"what do i get","dirge teaches"}}},ang={["profession:Cooking"]="As a cook, you can learn the finer points of exotic cuisine from Dirge Quikcleave."},kw={"alterac swiss","clamlette","clamlette surprise","dirge quikcleave","exotic cuisine","giant eggs","zesty clam meat"},rel={"npc:dirge-quikcleave","zone:tanaris"},m={id=6610},src={"In-game quest text: Clamlette Surprise"},fv=true}
E["quest:82"] = {t="quest",n="Noxious Lair Investigation",z="tanaris",s="In the Noxious Lair, Centipaar bugs drain the pools that once lay there. Senior Surveyor Fizzledowser wants to learn who the enemy is, so you bring five insect parts to Alchemist Pestlezugg in Gadgetzan for examination.",h="In the Noxious Lair, Centipaar bugs drain the pools that once lay there.",sec={{t="Parts From the Lair",b="After the Gadgetzan Water Survey, Senior Surveyor Fizzledowser turns to reports of the bugs. They drain the pools that once lay where the Noxious Lair now stands. He knows little about them and wants to learn who the enemy is, so you gather five parts from the Centipaar in the Noxious Lair. Then you take them to Alchemist Pestlezugg in Gadgetzan for examination.",sp=0},{t="What Pestlezugg Finds",b="Alchemist Pestlezugg examines the parts at once. They match no insect form he has seen before. The bugs seem almost as if an outside force controls them. Pestlezugg sends you back to Senior Surveyor Fizzledowser, whose urgent need for help may involve more of the bugs in Tanaris.",sp=1}},faq={{q="Why does Senior Surveyor Fizzledowser want insect parts?",a="Bugs are draining the pools that once lay where the Noxious Lair is, and little else is known about them. The Centipaar parts may help Alchemist Pestlezugg learn what they are.",al={"why collect bug parts","fizzledowser insect parts","noxious lair purpose"}},{q="Where are the Centipaar found?",a="The Centipaar are found in the Noxious Lair, where water pools once lay.",al={"where is noxious lair","centipaar location","where to find centipaar"}},{q="Who receives the insect parts in Gadgetzan?",a="Alchemist Pestlezugg in Gadgetzan receives the insect parts for examination.",al={"who to turn in to","pestlezugg location","who wants the bug parts"}},{q="What comes before this step?",a="It follows the Gadgetzan Water Survey.",al={"previous quest","prerequisite quest","what leads to this"}}},kw={"centipaar","fizzledowser","gadgetzan","insects","noxious lair","pestlezugg","tanaris"},rel={"subzone:noxious-lair","npc:senior-surveyor-fizzledowser","subzone:gadgetzan","zone:tanaris","quest:992","quest:10"},m={start="Senior Surveyor Fizzledowser",["end"]="Alchemist Pestlezugg",level="47",id=82,ri={"Centipaar Insect Parts"}},src={"Noxious Lair Investigation"}}
E["quest:841"] = {t="quest",n="Another Power Source?",z="tanaris",s="In Gadgetzan, Chief Engineer Bilgewhizzle offers you another power source for ten Wastewander Water Pouches.",h="In Gadgetzan, Chief Engineer Bilgewhizzle offers you another power source for ten Wastewander Water Pouches.",sec={{t="A Costly Replacement",b="Chief Engineer Bilgewhizzle believes the first power source ran out of time or was lost in the sand. Whatever happened, he has another one to sell you. Times are tough all around, so he asks for ten Wastewander Water Pouches.",sp=0}},faq={{q="Why does Chief Engineer Bilgewhizzle want Wastewander water pouches?",a="Chief Engineer Bilgewhizzle asks for ten Wastewander Water Pouches in exchange for another power source. Times are tough all around.",al={"bilgewhizzle water pouches","why water pouches"}},{q="Who offers this exchange?",a="Chief Engineer Bilgewhizzle offers the exchange and has more power sources to sell.",al={"who starts another power source","power source quest giver"}},{q="What happened prior to needing another power source?",a="This follows Slake That Thirst, when you first obtained a power source for your kit.",al={"prereq another power source","previous quest power source"}}},kw={"bilgewhizzle","gadgetzan","power source","tanaris","wastewander","water pouches"},rel={"quest:379","subzone:gadgetzan","zone:tanaris"},m={start="Chief Engineer Bilgewhizzle",["end"]="Chief Engineer Bilgewhizzle",level="46",faction="Horde",id=841},src={"Another Power Source?"}}
E["quest:8555"] = {t="quest",n="The Charge of the Dragonflights",z="tanaris",s="In Tanaris, Anachronos meets you as the first part of the Scepter of the Shifting Sands draws to a close. The chain leads toward the opening of the Gates of Ahn'Qiraj.",h="In Tanaris, Anachronos meets you as the first part of the Scepter of the Shifting Sands draws to a close.",sec={{t="The End of the Beginning",b="Anachronos meets you in Tanaris to close the first part of the Scepter of the Shifting Sands. The chain leads toward the opening of the Gates of Ahn'Qiraj.",sp=0},{t="The Three Watchers",b="Anachronos names Eranikus, Vaelastrasz and Azuregos as three dragons who watched over the world. Each has suffered tragedy at the hands of agents of the Old Gods or through betrayal by those they called friend.\n\nAnachronos admits his own naivety made him partly to blame. These events have fed his distrust of mortals, so he sends you to seek the three dragons and prepare for the worst.",sp=1}},faq={{q="Who is Anachronos?",a="Anachronos is a dragon of the bronze dragonflight whom you meet in Tanaris.",al={"who is anachronos","anachronos tanaris","bronze dragon"}},{q="What is the Scepter of the Shifting Sands?",a="The Scepter of the Shifting Sands is a long chain leading toward the opening of the Gates of Ahn'Qiraj. Your meeting with Anachronos closes its first part.",al={"scepter chain","scepter of the shifting sands","gates of ahn'qiraj chain"}}},kw={"anachronos","azuregos","eranikus","gates of ahn'qiraj","scepter of the shifting sands","tanaris","vaelastrasz"},rel={"npc:azuregos","zone:tanaris"},m={start="Anachronos",["end"]="Anachronos",level="60",id=8555},src={"The Charge of the Dragonflights"}}
E["quest:8576"] = {t="quest",n="Translating the Ledger",z="tanaris",s="You bring Azuregos's ledger to Narain Soothfancy, who must decipher its writing. What he finds may bring you closer to opening the Gates of Ahn'Qiraj.",h="You bring Azuregos's ledger to Narain Soothfancy, who must decipher its writing.",sec={{t="The Ledger Comes to Narain",b="Azuregos's ledger is in your hands, and Narain Soothfancy must decipher it. You bring the ledger to him so he can learn what Azuregos wrote.",sp=0},{t="What Narain Makes of It",b="Narain Soothfancy finds that Azuregos set you to build an arcanite buoy, and its schematic lies in the ledger. The writing is Draconic, which Narain cannot read. To make sense of it, he needs the scrying goggles, a chicken of five hundred pounds, and the second volume of Draconic for Dummies. He can gather them in any order.",sp=1}},faq={{q="Whose ledger is it?",a="Azuregos owns the ledger, and you bring it to Narain Soothfancy.",al={"whose ledger","azuregos ledger","who wrote the ledger"}},{q="Who reads the ledger?",a="Narain Soothfancy must work out what Azuregos wrote in the ledger.",al={"who translates the ledger","narain soothfancy","where to take the ledger"}}},kw={"arcanite buoy","azuregos","draconic","ledger","narain soothfancy","tanaris"},rel={"npc:narain-soothfancy","zone:tanaris"},m={start="Narain Soothfancy",["end"]="Narain Soothfancy",level="60",id=8576},src={"Translating the Ledger"}}
E["quest:8577"] = {t="quest",n="Stewvul, Ex-B.F.F.",z="tanaris",s="Narain cannot translate anything without the scrying goggles. Stewvul, Ex-B.F.F., has them, and you need to bring them back.",h="Narain cannot translate anything without the scrying goggles.",sec={{t="The Stolen Goggles",b="Narain Soothfancy cannot translate anything without the scrying goggles. Stewvul was once Narain's best friend forever, but stole them a while ago. Then Stewvul broke Narain's heart in five places and abandoned Narain here.",sp=0},{t="Where to Look",b="Narain's crystal ball points to two places where Stewvul might be. One is the Greymane Wall in Silverpine. The other lies beyond a portal. You need to find Stewvul and bring back the goggles.",sp=0},{t="What Stewvul Says",b="Stewvul cannot believe Narain has found them. Stewvul refuses to return, weary of being a friend only part of the time and a slave the rest.",sp=1}},faq={{q="Why does Narain need the scrying goggles?",a="Narain says nothing can be translated without the scrying goggles.",al={"why need goggles","narain goggles purpose","scrying goggles use"}},{q="Who is Stewvul?",a="Stewvul is Narain Soothfancy's ex-best friend forever. Stewvul stole the scrying goggles, broke Narain's heart in five places, then abandoned Narain here.",al={"who is stewvul","stewvul lore","narain friend"}},{q="Where does Narain think Stewvul is?",a="Narain's crystal ball points to two possible places: the Greymane Wall in Silverpine or a world beyond a portal.",al={"where is stewvul","stewvul locations","greymane wall"}},{q="What comes before this?",a="Before this, you brought Azuregos's ledger to Narain in Translating the Ledger.",al={"previous quest","prereq","what leads to this"}}},kw={"greymane wall","inconspicuous crate","ledger","narain soothfancy","scrying goggles","silverpine","stewvul","tanaris"},rel={"npc:narain-soothfancy","quest:8576","subzone:greymane-wall","zone:tanaris"},m={start="Narain Soothfancy",["end"]="Inconspicuous Crate",level="60",id=8577},src={"Stewvul, Ex-B.F.F."}}
E["quest:8584"] = {t="quest",n="Never Ask Me About My Business",z="tanaris",s="Narain Soothfancy sends you to Gadgetzan to find a chicken weighing five hundred pounds. At the inn, Dirge Quikcleave can point you toward one.",h="Narain Soothfancy sends you to Gadgetzan to find a chicken weighing five hundred pounds.",sec={{t="Planning and Fetching",b="Narain Soothfancy wants no more questions about his business. It deals in things beyond your understanding, so he keeps the plan to himself and leaves the fetching to you. He needs a chicken weighing five hundred pounds. Dirge Quikcleave at the Gadgetzan inn can point you toward one.",sp=0},{t="Dirge's Answer",b="Dirge Quikcleave says no chicken that heavy can be found now. He once knew of the Black Chicken of Death, but nobody who saw that bird lived to tell of it. Then Dirge offers an idea that could be good for you both.",sp=1}},faq={{q="Why does Narain Soothfancy need a five-hundred-pound chicken?",a="Narain will not say. His business involves things you could not understand, such as a psychotronic muzzledorf. He keeps the planning to himself and leaves the fetching to you.",al={"why 500 pound chicken","narain chicken business","why does narain want a chicken"}},{q="Who do you need to talk to in Gadgetzan?",a="Narain sends you to Dirge Quikcleave at the Gadgetzan inn to begin looking for a suitable chicken.",al={"where to go","who to see in gadgetzan","where is dirge quikcleave"}},{q="What comes before this quest?",a="Translating the Ledger comes first. Narain Soothfancy brings up the chicken afterward.",al={"prerequisite quest","what quest comes first","prior step"}},{q="Where is Narain Soothfancy located?",a="Narain Soothfancy is in Tanaris.",al={"where is narain","narain location","narain soothfancy tanaris location"}}},kw={"500 pound chicken","black chicken of death","dirge quikcleave","gadgetzan","narain soothfancy","tanaris"},rel={"npc:narain-soothfancy","npc:dirge-quikcleave","quest:8576","subzone:gadgetzan","zone:tanaris"},m={start="Narain Soothfancy",["end"]="Dirge Quikcleave",level="60",id=8584},src={"Never Ask Me About My Business"}}
E["quest:8586"] = {t="quest",n="Dirge's Kickin' Chimaerok Chops",z="tanaris",s="In Gadgetzan, Dirge Quikcleave has his recipe ready, but the meat needs attention soon. He asks you for twenty Goblin Rocket Fuel and twenty Deeprock Salt before it spoils.",h="In Gadgetzan, Dirge Quikcleave has his recipe ready, but the meat needs attention soon.",sec={{t="What Dirge Still Needs",b="Dirge Quikcleave handles the spices himself, while the meat you brought him makes up the rest of the dish. He still needs twenty Goblin Rocket Fuel and twenty Deeprock Salt. With both in hand, the chicken can go back to Narain Soothfancy. Dirge urges you to hurry before the meat goes bad.",sp=0}},faq={{q="Who asks for these supplies?",a="Dirge Quikcleave in Gadgetzan asks you for the supplies to finish his recipe.",al={"who starts this quest","who gives dirge's kickin chimaerok chops","dirge quikcleave quest"}},{q="What ingredients does Dirge Quikcleave need?",a="Dirge needs twenty Goblin Rocket Fuel and twenty Deeprock Salt. He handles the spices, and the meat you brought him covers the rest.",al={"what items do i need","ingredients for dirge chops","dirges chops items"}},{q="Who is the finished dish intended for?",a="Dirge says the finished bird is ready to be carried back to Narain Soothfancy.",al={"who eats the chops","who gets the chicken","who is the food for"}},{q="What comes after delivering these ingredients?",a="After you deliver the ingredients, return to Narain Soothfancy.",al={"next quest","what do i do after dirge chops","what follows this quest"}}},kw={"chimaerok","chops","deeprock salt","dirge","gadgetzan","narain","quikcleave","rocket fuel"},rel={"npc:dirge-quikcleave","npc:narain-soothfancy","quest:8587","subzone:gadgetzan","zone:tanaris"},m={start="Dirge Quikcleave",["end"]="Dirge Quikcleave",level="60",id=8586},src={"Dirge's Kickin' Chimaerok Chops (quest)"}}
E["quest:8587"] = {t="quest",n="Return to Narain",z="tanaris",s="Dirge Quikcleave keeps his word, and you carry his five-hundred-pound chicken to Narain Soothfancy in Tanaris. Dirge's Kickin' Chimaerok Chops came before this delivery.",h="Dirge Quikcleave keeps his word, and you carry his five-hundred-pound chicken to Narain Soothfancy in Tanaris.",sec={{t="A Bargain Kept",b="Dirge Quikcleave hands over the chicken he promised. A goblin keeps his word, he says. He cannot guess why a gnome wants a bird that size, and grumbles that it must be for sleeping in. From there, you carry the chicken to Narain Soothfancy in Tanaris.",sp=0},{t="Narain's Welcome",b="Narain Soothfancy catches the scent of Dirge's chicken. He drives both fists into the bird, then stuffs his face with Dirge's cooking. It is the best chicken he has ever tasted, Narain says.",sp=1}},faq={{q="What came before this delivery?",a="Dirge's Kickin' Chimaerok Chops came first. Dirge Quikcleave asked for rocket fuel and salt to finish his recipe.",al={"previous quest","what did i do before this","prerequisite"}},{q="Who receives the massive chicken?",a="Narain Soothfancy receives the massive chicken in Tanaris.",al={"who gets the chicken","who do i take this to","turn in location"}},{q="Why did Dirge prepare a five-hundred-pound chicken?",a="Dirge prepared the five-hundred-pound chicken to keep his word and hand it over. He says he cannot imagine what a gnome wants with a bird that size.",al={"why 500 pound chicken","what is the chicken for","dirge chicken"}},{q="What comes after delivering the chicken?",a="The Good News and The Bad News follows. Narain offers it only after Narain's Scrying Goggles and Draconic For Dummies: Volume II are finished.",al={"next quest","what follows this","where to next"}}},kw={"500 pound chicken","chimaerok","dirge quikcleave","narain soothfancy","tanaris"},rel={"npc:narain-soothfancy","npc:dirge-quikcleave","zone:tanaris","quest:8586","quest:8728","topic:gnome","topic:goblin"},m={start="Dirge Quikcleave",["end"]="Narain Soothfancy",level="60",id=8587},src={"Return to Narain"}}
E["quest:8597"] = {t="quest",n="Draconic for Dummies",z="tanaris",s="Narain Soothfancy wants you to find the book he hid on an island in the South Seas. First, find his crashed gyrocopter on Land's End Beach, then swim south. This follows Translating the Ledger.",h="Narain Soothfancy wants you to find the book he hid on an island in the South Seas.",sec={{t="A Book Stowed Away",b="Narain Soothfancy says the book will come in handy, and he hid it where no one could hope to find it. He took a gyrocopter to reach the hiding place, then crashed on the beach on his way back. Narain says the crash gave him his super-gnomish psychic powers.\n\nThe wreck lies somewhere along Land's End Beach. From there, swim south. Narain is sure you will recognise the place at a glance. The book lies buried on an island in the South Seas.",sp=0},{t="At the Island",b="On the island, you find a mound of dirt, but the book is gone. A note lies on the mound in its place.",sp=1}},faq={{q="Who sends you to find this book?",a="Narain Soothfancy sends you after the book once you finish Translating the Ledger for him.",al={"who gives draconic for dummies","narain quest starter","who gives this quest"}},{q="Where did Narain crash his gyrocopter?",a="Narain says he crashed on a beach while returning from hiding the book. His wreck lies somewhere along Land's End Beach.",al={"where is the gyrocopter","crashed gyrocopter location","lands end beach crash"}},{q="Where is the book supposed to be hidden?",a="Narain Soothfancy says the book lies buried on an island in the South Seas. Swim south from his wreck on Land's End Beach; he says you will recognise the place at a glance.",al={"book location","where is the island","where to swim"}},{q="How did Narain get his psychic powers?",a="Narain says the gyrocopter crash on the beach gave him his psychic powers.",al={"narain psychic powers","how did narain become psychic"}}},kw={"draconic for dummies","freshly dug dirt","gyrocopter","land's end beach","narain soothfancy","south seas","tanaris"},rel={"npc:narain-soothfancy","quest:8576","subzone:land-s-end-beach","subzone:south-seas","zone:tanaris","quest:8598","quest:8599"},m={start="Narain Soothfancy",["end"]="Freshly Dug Dirt",level="60",id=8597},src={"Draconic for Dummies (quest)"}}
E["quest:8598"] = {t="quest",n="rAnS0m",z="tanaris",s="At the freshly dug dirt in Tanaris, Narain Soothfancy’s book is gone, and a ransom note waits in its place. You carry the letter back to Narain after searching for the book in Draconic for Dummies.",h="At the freshly dug dirt in Tanaris, Narain Soothfancy’s book is gone, and a ransom note waits in its place.",sec={{t="A Note Made of Scraps",b="Made from scraps of type, the ransom note tells Narain Soothfancy that its writers have his precious book. They call him a gnome and promise he will see it again only if he follows their orders exactly. Three pages give detailed instructions, ending with a demand that he bring the money and come alone. You carry the letter to Narain in Tanaris.",sp=0},{t="Narain's Answer",b="Narain Soothfancy asks what is wrong, then reads the letter. His face glows bright red. Outraged that someone has taken his book, he vows to show the culprits what it means to cross a psychic gnome.",sp=1}},faq={{q="What is the ransom note demanding?",a="The writers claim to have Narain Soothfancy’s book and promise he will see it again only if he follows their orders. Three pages of instructions end with a demand for money and that he come alone. The note does not name its writers.",al={"what does the note say","ransom letter text","who took the book"}},{q="Where does this step lead next?",a="After you bring the letter to Narain Soothfancy in Tanaris, the chain continues with Decoy!",al={"what comes after ransom","ransom follow up","next quest after ransom"}},{q="What came before finding the ransom note?",a="Draconic for Dummies comes first. You search for Narain’s buried book and reach the freshly dug dirt.",al={"previous quest","prereq for ransom"}}},kw={"draconic for dummies","freshly dug dirt","narain soothfancy","ransom","ransom letter","tanaris"},rel={"npc:narain-soothfancy","quest:8606","zone:tanaris","topic:gnome"},m={start="Freshly Dug Dirt",["end"]="Narain Soothfancy",level="60",id=8598},src={"RAnS0m"}}
E["quest:8599"] = {t="quest",n="Love Song for Narain",z="tanaris",s="Meridith sends her love to Narain Soothfancy, and you carry her letter to him in Tanaris. She rescued the gnome from a crashed flying machine and asks you to seek his book, Draconic for Dummies.",h="Meridith sends her love to Narain Soothfancy, and you carry her letter to him in Tanaris.",sec={{t="A Message for the Shore",b="Meridith the Mermaiden seldom has visitors. Her last was the gnome she rescued from a crashed flying machine. The memory takes her gaze far away for a moment. Then she asks if you know Narain Soothfancy. She needs to tell him how she feels, and she is sure it is love. Meridith begs you to carry her message to him and promises to be forever in your debt.",sp=0},{t="Narain's Answer",b="Narain Soothfancy says you smell of fish. When he learns what Meridith's letter says, he fidgets. She is a fish, he protests, and he is a gnome. He insists their love could never work out.",sp=1}},faq={{q="Who is Meridith?",a="Meridith is a mermaiden who seldom has visitors. Her last visitor was Narain Soothfancy, the gnome she rescued from a crashed flying machine.",al={"who is meridith","meridith the mermaiden","mermaiden lore"}},{q="How does Meridith know Narain Soothfancy?",a="Meridith rescued Narain Soothfancy from his crashed flying machine. She believes she is in love with him.",al={"how did meridith meet narain","narain and meridith relationship","narain plane crash"}},{q="What is the love letter?",a="The love letter is Meridith's message to Narain Soothfancy, telling him how she feels. She wants you to deliver it to him in Tanaris.",al={"meridith's love letter","love letter to narain","what is in the message"}},{q="What came before this request?",a="Draconic for Dummies comes first. Meridith asks you to carry her letter while you seek Narain's buried book.",al={"previous quest","prerequisite for love song for narain"}}},kw={"flying machine","love letter","meridith","mermaiden","narain soothfancy","tanaris","wreckage"},rel={"npc:narain-soothfancy","quest:8597","zone:tanaris","topic:gnome"},m={start="Meridith the Mermaiden",["end"]="Narain Soothfancy",level="60",id=8599},src={"Love Song for Narain"}}
E["quest:8606"] = {t="quest",n="Decoy!",z="tanaris",s="At the Winterspring handover, Narain Soothfancy means to deliver the ransom after a fashion. You carry Narain's disguise to the spot the booknappers named, following the ransom letter.",h="At the Winterspring handover, Narain Soothfancy means to deliver the ransom after a fashion.",sec={{t="Narain's Scheme",b="The ransom note said Narain should make the delivery himself. He plans to do so after a fashion, and chooses you for the part. His special kit holds a turban, a robe, and a sack filled with rocks. You carry the disguise to the handover spot the booknappers named in Winterspring. When they arrive for the goods, Narain wants them snuffed out as a lesson in what comes of crossing him.",sp=0},{t="Narain's Verdict",b="When you return, Narain admits that he and you may have underestimated the booknappers.",sp=1}},faq={{q="Why does Narain want you to wear a disguise?",a="The ransom note said Narain should make the delivery himself. He means to do so after a fashion by sending you in his place, with the turban and robe from his special kit.",al={"why wear the turban","why the disguise","why dress like narain"}},{q="Where does the handover take place?",a="The handover takes place at the spot in Winterspring that the booknappers named. That is where the sack of rocks is to be left.",al={"where is the drop","where do i take the bag","drop off point location"}},{q="What is inside the ransom bag?",a="Narain fills the sack with rocks instead of money.",al={"what is in the bag","is it real gold","what did narain pack"}},{q="What came before this quest?",a="Before this, the ransom letter demanded money for Narain's stolen book, which you carried back to him.",al={"prerequisite quest","previous quest","what led to this"}}},kw={"booknappers","decoy","narain soothfancy","number two","ransom","winterspring"},rel={"npc:narain-soothfancy","zone:winterspring","zone:tanaris"},m={start="Narain Soothfancy",["end"]="Narain Soothfancy",level="60",id=8606},src={"Decoy!"}}
E["quest:8728"] = {t="quest",n="The Good News and The Bad News",z="tanaris",s="Narain Soothfancy has read the ledger and found good news and bad. He is nearly certain he can build the arcanite buoy you specified, but needs arcanite, elementium ore, and fine gems. The chicken, the goggles, and the second Draconic For Dummies book must all be done first.",h="Narain Soothfancy has read the ledger and found good news and bad.",sec={{t="Good News, Bad News",b="Narain Soothfancy studies the ledger and murmurs under his breath. He is ninety-nine percent sure he can build the arcanite buoy to your specifications. The materials are the bad news. He asks for twenty arcanite bars, ten elementium ore, ten Azerothian diamonds, and ten blue sapphires. Bring them, and he will craft the buoy.",sp=0},{t="Narain's Warning",b="When you bring the materials, Narain says a deal is a deal. He hopes you know what you are getting into. To him, gathering so much is a great deal of bother just to go fishing.",sp=1}},faq={{q="Who offers this quest?",a="Narain Soothfancy offers it after the chicken, the Scrying Goggles, and the second Draconic For Dummies book are all done.",al={"quest giver","narain soothfancy location","where is narain"}},{q="What materials does Narain require?",a="Narain requires twenty arcanite bars, ten elementium ore, ten Azerothian diamonds, and ten blue sapphires.",al={"required items","mats needed","what materials do i need"}},{q="What is Narain building with these materials?",a="Narain is building an arcanite buoy. He is ninety-nine percent sure it will work to your specifications.",al={"what is narain making","why arcanite buoy","what is the buoy for"}},{q="What comes before this step?",a="Return to Narain comes before this. The goggles and the second Draconic For Dummies book must also be finished.",al={"previous quest","prerequisites","what leads to this"}}},kw={"arcanite bar","arcanite buoy","azerothian diamond","blue sapphire","elementium","narain soothfancy","tanaris"},rel={"npc:narain-soothfancy","quest:8587","zone:tanaris","quest:8597"},m={start="Narain Soothfancy",["end"]="Narain Soothfancy",level="60",id=8728},src={"The Good News and The Bad News"}}
E["quest:8742"] = {t="quest",n="The Might of Kalimdor",z="tanaris",s="In Tanaris, Anachronos greets you in The Might of Kalimdor as the champion fate has awaited for a thousand years. He sees you leading your people into a new age. The Blue, Green and Red Scepter Shard forks are complete, bringing the Scepter of the Shifting Sands to its end.",h="In Tanaris, Anachronos greets you in The Might of Kalimdor as the champion fate has awaited for a thousand...",sec={{t="The Old God Trembles",b="Anachronos speaks of a fate a thousand years in the making. The Old God trembles at your coming and fears your faith. Anachronos urges you to break C'Thun's prophecy, and you bring Kalimdor's strength with you. When you are ready, tell Anachronos, and he will place the Scepter of the Shifting Sands in your hands.",sp=0},{t="Words of Parting",b="Anachronos declares the Scepter of the Shifting Sands complete again. The scepter is yours alone to wield, and you are to lead your people into the age ahead. The Scarab Gong must wait: both the Horde and Alliance armies must first arrive in Silithus.",sp=1}},faq={{q="Who offers The Might of Kalimdor?",a="Anachronos offers The Might of Kalimdor only after you finish all three Scepter Shard forks: Blue, Green and Red.",al={"who gives the might of kalimdor","anachronos quest","who gives the scepter"}},{q="What does the Old God fear?",a="Anachronos says the Old God C'Thun trembles at your coming and fears your faith. He urges you to shatter C'Thun's prophecy.",al={"what old god","who fears the might of kalimdor","cthun prophecy"}},{q="What must be done before this step?",a="Finish all three Scepter Shard forks first: the Blue, the Green and the Red.",al={"prerequisite","what do i need before might of kalimdor","scepter shard forks"}}},kw={"anachronos","c'thun","might of kalimdor","scepter","shifting sands","silithus","tanaris"},rel={"zone:tanaris","zone:silithus","topic:old-god"},m={start="Anachronos",["end"]="Anachronos",level="60",id=8742},src={"The Might of Kalimdor"}}
E["quest:8921"] = {t="quest",n="The Ectoplasmic Distiller",z="tanaris",s="In Gadgetzan, Mux Manascrambler lacks the funds and help to finish his extra-dimensional ghost revealer. He asks you for costly materials and forty gold to build its first piece, an ectoplasmic distiller.",h="In Gadgetzan, Mux Manascrambler lacks the funds and help to finish his extra-dimensional ghost revealer.",sec={{t="What Mux Needs",b="Mux Manascrambler welcomes your help with his ghost revealer, a machine meant to reach across dimensions. First, he needs a distiller to gather the fabric of death itself. Building it will be difficult. Mux asks for one delicate arcanite converter, four greater eternal essences, ten stonescale oil, twenty-five volcanic ash, and forty gold.\n\nThe volcanic ash must come from the lava pools of the Burning Steppes. It will make the distiller's filter. The materials are costly, but Mux says he needs every one.",sp=0},{t="Mux's Thanks",b="Mux says you brought exactly the materials he needed, just in time. He promises the distiller will be ready in moments, and gives you something for your trouble.",sp=1}},faq={{q="Who asks for these materials?",a="Mux Manascrambler in Gadgetzan, Tanaris, asks for materials while building an extra-dimensional ghost revealer.",al={"quest giver","who gives the quest","who is mux"}},{q="What materials does Mux require?",a="Mux needs one delicate arcanite converter, four greater eternal essences, ten stonescale oil, twenty-five volcanic ash, and forty gold.",al={"required items","what do i need","distiller materials"}},{q="Where is the volcanic ash found?",a="Mux says to gather volcanic ash from the lava pools of the Burning Steppes.",al={"volcanic ash location","where to get ash"}},{q="Why does Mux need these specific components?",a="The materials go into an ectoplasmic distiller, which gathers the stuff death is made of. The volcanic ash makes its filter.",al={"why arcanite","what is the ash for","why the items"}},{q="What comes after delivering the materials?",a="Hunting for Ectoplasm comes next.",al={"next step","what happens next","next quest"}}},kw={"arcanite converter","burning steppes","ectoplasmic distiller","gadgetzan","mux manascrambler","stonescale oil","tanaris","volcanic ash"},rel={"npc:mux-manascrambler","subzone:gadgetzan","quest:8924","zone:tanaris","zone:burningsteppes"},m={start="Mux Manascrambler",["end"]="Mux Manascrambler",level="60",id=8921,ri={"Volcanic Ash"}},src={"The Ectoplasmic Distiller"}}
E["quest:8924"] = {t="quest",n="Hunting for Ectoplasm",z="tanaris",s="Mux Manascrambler in Gadgetzan has his distiller ready, and now needs ectoplasm. You carry it to Silithus, Winterspring and the Eastern Plaguelands, gathering twelve of each kind from the incorporeal dead. This follows The Ectoplasmic Distiller.",h="Mux Manascrambler in Gadgetzan has his distiller ready, and now needs ectoplasm.",sec={{t="Three Climates, Three Kinds",b="Mux Manascrambler is proud of his distiller, but the incorporeal dead are far from Gadgetzan. He believes climate changes the spectral fabric of the dead. In Silithus, tortured night elves yield scorched ectoplasm. In Winterspring, spirits of the highborne yield frozen ectoplasm.\n\nGhosts and banshees in the Eastern Plaguelands yield stable ectoplasm. Gather twelve of each kind. Mux says to set the distiller down nearby before harvesting, then bring it and the ectoplasm back to Gadgetzan.",sp=0},{t="Mux's Verdict",b="Mux Manascrambler is delighted with the ectoplasm. Its otherworldly energies, he explains, will let you reach out to souls that have not fully left this world.",sp=1}},faq={{q="Who sends you to gather ectoplasm?",a="Mux Manascrambler sends you from Gadgetzan in Tanaris once his distiller is built.",al={"who gives hunting for ectoplasm","quest giver hunting for ectoplasm"}},{q="Why does Mux need ectoplasm from three different places?",a="Mux says climate changes the spectral fabric of the dead. He wants twelve scorched ectoplasm from Silithus, twelve frozen from Winterspring and twelve stable from the Eastern Plaguelands.",al={"why three ectoplasms","different ectoplasm types","why silithus winterspring plaguelands"}},{q="Which spirits provide the ectoplasm?",a="Tortured night elves in Silithus, spirits of the highborne in Winterspring, and ghosts and banshees in the Eastern Plaguelands provide the ectoplasm.",al={"what enemies drop ectoplasm","what to kill for ectoplasm","which ghosts drop it"}},{q="How is the ectoplasm gathered?",a="Mux says to set the distiller down near the incorporeal dead before harvesting them.",al={"how does the distiller work","how to collect ectoplasm"}},{q="Where does this fit in Mux's work?",a="It follows The Ectoplasmic Distiller, and A Portable Power Source comes next.",al={"hunting for ectoplasm prerequisite","what comes before hunting for ectoplasm"}}},kw={"eastern plaguelands","ectoplasmic distiller","frozen ectoplasm","gadgetzan","hunting for ectoplasm","mux manascrambler","scorched ectoplasm","silithus","stable ectoplasm","winterspring"},rel={"npc:mux-manascrambler","quest:8921","quest:8925","subzone:gadgetzan","zone:silithus","zone:winterspring","zone:easternplaguelands","zone:tanaris"},m={start="Mux Manascrambler",["end"]="Mux Manascrambler",level="60",id=8924,ri={"Frozen Ectoplasm","Scorched Ectoplasm","Stable Ectoplasm"}},src={"Hunting for Ectoplasm"}}
E["quest:8925"] = {t="quest",n="A Portable Power Source",z="tanaris",s="Mux Manascrambler needs steady power for his ectoplasm. Rumour points to Magma Lord Bokk in the Burning Steppes, whose heart is a Magma Core, and Mux asks you to bring it to Gadgetzan.",h="Mux Manascrambler needs steady power for his ectoplasm.",sec={{t="A Heart of Endless Heat",b="Mux Manascrambler needs power he can carry to keep the ectoplasm active. Rumour says Magma Lord Bokk, a mighty elemental, has a Magma Core for a heart. Its heat never ends. Bokk is said to dwell in the Burning Steppes, south of Blackrock Mountain and west of the Pillar of Ash. Mux wants you to bring the core to Gadgetzan to run his extra-dimensional ghost revealer.",sp=0},{t="Power at Last",b="Mux Manascrambler is thrilled when you arrive with the core. He declares that it will give the ghost revealer all the energy it needs.",sp=1}},faq={{q="Why does Mux Manascrambler need a power source?",a="Mux Manascrambler needs steady, portable energy to keep the ectoplasm active and run his extra-dimensional ghost revealer.",al={"why need power source","what is the power source for","why magma core"}},{q="Who is Magma Lord Bokk?",a="Rumour says Magma Lord Bokk is a mighty elemental with a Magma Core for a heart. Its heat never runs dry.",al={"who is bokk","magma lord bokk lore","where is bokk"}},{q="Where in the Burning Steppes can Magma Lord Bokk be found?",a="Rumour places Magma Lord Bokk in the Burning Steppes, south of Blackrock Mountain and west of the Pillar of Ash.",al={"bokk location","where is magma lord bokk","find magma lord bokk"}},{q="Where does this step fit into Mux's work?",a="This follows Hunting for Ectoplasm, and A Shifty Merchant follows it.",al={"what comes before","quest chain order","what comes next"}}},kw={"blackrock mountain","burning steppes","gadgetzan","ghost revealer","magma core","magma lord bokk","mux manascrambler"},rel={"npc:mux-manascrambler","zone:burningsteppes","subzone:blackrock-mountain","subzone:gadgetzan","quest:8924","quest:8928","zone:tanaris"},m={start="Mux Manascrambler",["end"]="Mux Manascrambler",level="60",id=8925,ri={"Magma Core (Classic)"}},src={"A Portable Power Source"}}
E["quest:8928"] = {t="quest",n="A Shifty Merchant",z="tanaris",s="In Gadgetzan, Mux Manascrambler has a core for his device but still needs a rod to carry its force without melting. He remembers an imp in Winterspring who offered an elemental rod, and regrets not buying it. You find the imp in a cave at Darkwhisper Gorge’s entrance and buy the Fel Elemental Rod.",h="In Gadgetzan, Mux Manascrambler has a core for his device but still needs a rod to carry its force without...",sec={{t="The Imp in the Cave",b="Mux Manascrambler has the core for his device, but still needs a rod that can carry its force without melting. After A Portable Power Source, he recalls an elemental rod an imp was selling in Winterspring. Mux regrets not buying it then.\n\nThe imp is in a cave at the entrance to Darkwhisper Gorge in southern Winterspring. You buy the Fel Elemental Rod and bring it to Mux in Gadgetzan. He says the imp quoted him forty gold and insists you pay no more.",sp=0},{t="The Rod Arrives",b="Mux is delighted with the rod and says it will do perfectly. Then he turns to putting everything together.",sp=1}},faq={{q="Who sends you after the rod?",a="Mux Manascrambler in Gadgetzan, Tanaris, sends you to find the rod.",al={"who gives a shifty merchant","quest giver a shifty merchant"}},{q="What came before this step?",a="This follows A Portable Power Source.",al={"previous quest","prereq a shifty merchant"}},{q="Where can the imp merchant be found?",a="The imp merchant is in a cave at the entrance to Darkwhisper Gorge in southern Winterspring.",al={"where is the imp","darkwhisper gorge imp location","where is the merchant in winterspring"}},{q="What item are you sent to purchase?",a="You are sent to buy a Fel Elemental Rod.",al={"what item do i buy","what does the imp sell"}},{q="How much does the rod cost?",a="The imp quoted Mux forty gold, and Mux wants you charged no more.",al={"rod cost","how much gold for rod","imp price"}},{q="Why does Mux need this rod?",a="The core will power Mux’s device, but he still needs a rod that can carry its force without melting.",al={"why fel elemental rod","what is the rod for"}}},kw={"darkwhisper gorge","fel elemental rod","gadgetzan","imp","merchant","mux manascrambler","winterspring"},rel={"npc:mux-manascrambler","quest:8925","subzone:gadgetzan","subzone:darkwhisper-gorge","zone:winterspring","zone:tanaris"},m={start="Mux Manascrambler",["end"]="Mux Manascrambler",level="60",id=8928},src={"A Shifty Merchant"}}
E["quest:95144"] = {t="quest",n="Overseas Delivery",z="tanaris",s="Fizzgrimble asks you to carry a sealed crate across the sea to Friz Frazzlespark in the Riverglades. Its contents are meant to remain a surprise until it reaches Powderfuse Port.",h="Fizzgrimble asks you to carry a sealed crate across the sea to Friz Frazzlespark in the Riverglades.",sec={{t="A Careful Crossing",b="Fizzgrimble sends you east toward Steamwheedle Port, where a ship usually offers passage across the sea. The crate is bound for Friz Frazzlespark at Powderfuse Port in the Riverglades. Handle it gently on the way; Fizzgrimble warns against opening or jolting it.",sp=0}},faq={{q="Who is the package for?",a="Friz Frazzlespark is waiting for the crate at Powderfuse Port in the Riverglades.",al={"who gets the crate","friz frazzlespark package"}},{q="Where should I take the crate?",a="Take it to Friz Frazzlespark at Powderfuse Port in the Riverglades.",al={"crate destination","where is powderfuse port"}},{q="Where can I find passage across the sea?",a="Fizzgrimble recommends heading east to Steamwheedle Port, where a ship usually provides safe passage.",al={"how do i cross","steamwheedle ship"}},{q="What should I do with the crate on the way?",a="Keep the crate closed and avoid tilting, shaking, or making sudden movements with it.",al={"how to carry crate","can i open the package"}},{q="What is inside the crate?",a="Friz Frazzlespark asks you to turn around while they look inside, keeping the contents a surprise.",al={"crate contents","what's the surprise"}}},kw={"fizzgrimble","friz frazzlespark","mysterious crate","overseas delivery","powderfuse port","riverglades","steamwheedle port"},rel={"subzone:steamwheedle-port","zone:riverglades"},m={id=95144},src={"In-game quest text: Overseas Delivery"},fv=true}
E["quest:95312"] = {t="quest",n="Coming to Collect",z="tanaris",s="Friz’s debtor has gambled her money on Slugjaw in Gadgetzan’s arena and says the winnings are ready to collect. You are sent to speak with Fizbuz Mithril.",h="Friz’s debtor has gambled her money on Slugjaw in Gadgetzan’s arena and says the winnings are ready to...",sec={{t="Friz’s Money",b="The gambler who owes Friz says he wagered her money on Slugjaw at Fizbuz’s arena in Gadgetzan. He claims the bet won, but says he has not collected the winnings. Since you are already running an errand for Friz, he asks you to speak with Fizbuz Mithril in Gadgetzan.",sp=0}},faq={{q="Who owes Friz money?",a="A gambler owes Friz money after betting it on Slugjaw in Fizbuz’s arena.",al={"friz money","friz's debtor","who owes friz"}},{q="Why did he bet Friz’s money?",a="He says he thought betting on Slugjaw was a sound investment.",al={"why bet her money","slugjaw bet","gambler bet"}},{q="Who is Slugjaw?",a="Slugjaw is the arena fighter the gambler bet on in Gadgetzan.",al={"slugjaw","slugjaw arena","who's slugjaw"}},{q="Where are the winnings?",a="The gambler says he has not collected the winnings and sends you to speak with Fizbuz Mithril in Gadgetzan.",al={"friz winnings","collect money","where money"}},{q="Who should I speak to in Gadgetzan?",a="Speak with Fizbuz Mithril in Gadgetzan about the winnings.",al={"fizbuz","gadgetzan arena","friz errand"}}},kw={"arena","coming to collect","fizbuz mithril","friz","gadgetzan","gambling","slugjaw","winnings"},rel={"subzone:gadgetzan"},m={id=95312},src={"In-game quest text: Coming to Collect"},fv=true}
E["quest:95321"] = {t="quest",n="Tazzik's Dues",z="tanaris",s="Tazzik sent you to collect his winnings in Gadgetzan, but his arena champion earned nothing. You need to confront Tazzik about the unpaid debt.",h="Tazzik sent you to collect his winnings in Gadgetzan, but his arena champion earned nothing.",sec={{t="Back to the Port",b="The collector points you back toward Steamwheedle Port in Tanaris. Tazzik's champion lost quickly in the arena, so there are no winnings to collect. Tazzik may be trying to catch a ship out of port while you speak with the collector.",sp=0},{t="Tazzik's Answer",b="Tazzik admits he wagered everything he had on the fights to pay Friz, and lost it all. He says he cannot return her belongings and asks you to help him.",sp=1}},faq={{q="What happened to Tazzik's winnings?",a="Tazzik's champion lost in the arena, and the collector says the fight earned no copper.",al={"tazzik winnings","where's tazzik's money"}},{q="Where does Tazzik want me to go?",a="The collector sends you back to Steamwheedle Port in Tanaris to confront Tazzik.",al={"where to find tazzik","tazzik location"}},{q="Why should I hurry back to the port?",a="The collector thinks Tazzik may be trying to catch the next ship out of Steamwheedle Port.",al={"tazzik escaping","is tazzik leaving"}},{q="Who is Friz?",a="Friz is the one Tazzik owes. He bet her money on a fight in the Gadgetzan arena, and his champion lost.",al={"friz tazzik","tazzik friz"}}},kw={"arena","friz","steamwheedle port","tanaris","tazzik","tazzik's dues","winnings"},rel={"subzone:steamwheedle-port","zone:tanaris"},m={id=95321},src={"In-game quest text: Tazzik's Dues"},fv=true}
E["quest:95383"] = {t="quest",n="Shipping and Handling",z="tanaris",s="Wharfmaster Steamfizzle points you toward Tazzik with Friz’s Secret Stash. The shipment raises questions about its passage through customs.",h="Wharfmaster Steamfizzle points you toward Tazzik with Friz’s Secret Stash.",sec={{t="At the Dock",b="Tazzik is waiting on the dock in Steamwheedle Port for the crate you carry. Wharfmaster Steamfizzle directs you to him, though he claims to know nothing about the delivery. He urges haste and warns you against drawing the wrong attention. The shipment comes from Powderfuse Port, and its passage through customs is in question.",sp=0}},faq={{q="Who is asking me to deliver the crate?",a="Wharfmaster Steamfizzle directs you to Tazzik with Friz’s Secret Stash.",al={"who sent me","who gave me the package"}},{q="Who am I delivering Friz’s Secret Stash to?",a="You are to deliver Friz’s Secret Stash to Tazzik in Steamwheedle Port.",al={"where does the crate go","deliver stash to who"}},{q="What is Friz’s Secret Stash?",a="It is a shipment Friz sent for Tazzik. The completion text praises its quality.",al={"what's in the crate","friz package"}},{q="Where did the shipment come from?",a="Tazzik says he can smell Powderfuse Port on you.",al={"crate origin","powderfuse package"}},{q="Why does Steamfizzle tell me to hurry?",a="Steamfizzle warns you not to draw the wrong attention.",al={"why be quick","wrong idea"}},{q="Was the shipment cleared by customs?",a="Tazzik says the shipment has been cleared by customs, but suggests Friz’s money may be a problem.",al={"customs cleared","is this legal"}}},kw={"customs","friz","friz's secret stash","powderfuse port","shipping and handling","steamwheedle port","tazzik","wharfmaster steamfizzle"},rel={"subzone:steamwheedle-port"},m={id=95383},src={"In-game quest text: Shipping and Handling"},fv=true}
E["quest:95472"] = {t="quest",n="Consolation Prize",z="tanaris",s="Tazzik asks you to bring his sweaty shirt to Friz Frazzlespark in Powderfuse Port. Friz has not been paid back, and the shirt is all Tazzik has left.",h="Tazzik asks you to bring his sweaty shirt to Friz Frazzlespark in Powderfuse Port.",sec={{t="A Shirt for Friz",b="Tazzik's promise has left him with nothing but his shirt. In Powderfuse Port, Friz Frazzlespark is waiting for you to bring it to him. Tazzik cannot pay Friz back, so this is all he can offer.",sp=0},{t="Friz's Share",b="Friz reacts with anger when you give him the shirt. He stamps it into the ground, then offers you a share of the profits and insists you keep it.",sp=1}},faq={{q="Why does Tazzik give up his shirt?",a="Tazzik says he cannot pay Friz back and has nothing left but his shirt.",al={"tazzik shirt","why shirt","sweaty shirt"}},{q="Who is Friz Frazzlespark?",a="Friz Frazzlespark is the one Tazzik owes money to.",al={"who's friz","friz","friz guy"}},{q="Where do I take Tazzik's shirt?",a="Bring Tazzik's Sweaty Shirt to Friz Frazzlespark in Powderfuse Port.",al={"shirt where","take it to friz","powderfuse shirt"}},{q="What does Friz say about the shirt?",a="Friz reacts with disbelief when he learns what happened.",al={"friz reaction","what friz say","shirt response"}},{q="What does Friz offer me?",a="Friz offers you a share of the profits and says it is yours.",al={"friz payment","my share","profits"}}},kw={"consolation prize","friz frazzlespark","payment","powderfuse port","profits","sweaty shirt","tazzik"},m={id=95472},src={"In-game quest text: Consolation Prize"},fv=true}
E["quest:97530"] = {t="quest",n="Dunemaul Dues",z="tanaris",s="Security Chief Bilgewhizzle of Steamwheedle Port wants a shiny bangle recovered near the Dunemaul ogre compound. It was lost when a merchant caravan threw cargo to distract the ogres.",h="Security Chief Bilgewhizzle of Steamwheedle Port wants a shiny bangle recovered near the Dunemaul ogre...",sec={{t="Lost Cargo",b="A caravan lost cargo near the Dunemaul ogre compound after the ogres attacked. Security Chief Bilgewhizzle of Steamwheedle Port asks you to recover a particularly shiny bangle. The merchants are pressing him over their lost profits, and he offers to make it worth your trouble.",sp=0}},faq={{q="Who wants the bangle back?",a="Security Chief Bilgewhizzle of Steamwheedle Port wants you to recover the shiny bangle.",al={"who sent me","Bilgewhizzle bangle","who wants it"}},{q="Where was the bangle lost?",a="The bangle was lost near the Dunemaul ogre compound.",al={"where is the bracelet","bangle location","where lost"}},{q="How did the caravan lose its cargo?",a="The caravan took a wrong turn through the desert and was attacked by Dunemaul ogres. Its people threw cargo overboard to distract them.",al={"what happened to caravan","Dunemaul caravan","why lost cargo"}},{q="Why does Bilgewhizzle want it recovered?",a="The merchants are pressing Bilgewhizzle over the profits lost with their cargo.",al={"why find bangle","lost profits","merchant trouble"}},{q="What kind of bangle is Bilgewhizzle looking for?",a="Bilgewhizzle asks for a particularly shiny bangle bracelet.",al={"shiny bracelet","which bangle","bangle quest"}}},kw={"bangle","bilgewhizzle","bracelet","caravan","dunemaul dues","dunemaul ogres","lost cargo","steamwheedle port"},rel={"zone:tanaris","subzone:steamwheedle-port"},m={id=97530},src={"In-game quest text: Dunemaul Dues"},fv=true}
E["quest:97534"] = {t="quest",n="Gritty Business",z="tanaris",s="Quinn in Gadgetzan offers a share of the coin for salvage from machines in the desert. She plans to sell the parts to junkers.",h="Quinn in Gadgetzan offers a share of the coin for salvage from machines in the desert.",sec={{t="A Share of the Salvage",b="Quinn has silver waiting in Gadgetzan, where she means to sort and sell what you bring back. The desert machines shed parts that tech-heads may value as fuel-cell material. Quinn wants you to bring her seven pieces of Desert Debris, and promises a share of the coin from the sale.",sp=0}},faq={{q="Who is asking for the debris?",a="Quinn in Gadgetzan is asking you to recover Desert Debris from machines in the desert.",al={"who wants debris","Quinn salvage","gritty business giver"}},{q="What does Quinn want me to bring back?",a="Quinn wants seven pieces of Desert Debris.",al={"what parts","debris pieces","gritty business items"}},{q="Why does Quinn want the machine parts?",a="Quinn plans to sell the salvage to junkers who may use the parts as fuel-cell material.",al={"why debris","what's it for","salvage reason"}},{q="What does Quinn offer in return?",a="Quinn promises you a share of the coin from selling the salvage.",al={"what do i get","Quinn's deal","gritty business reward"}},{q="Where do I find Quinn?",a="Quinn is in Gadgetzan.",al={"Quinn location","where's Quinn","Gadgetzan giver"}}},kw={"desert debris","fuel cell","gadgetzan","gritty business","junkers","machines","quinn","salvage"},rel={"subzone:gadgetzan"},m={id=97534},src={"In-game quest text: Gritty Business"},fv=true}
E["quest:97536"] = {t="quest",n="Gnomish Garbage",z="tanaris",s="Jhordy Lapforge asks you to remove dangerously charged refuse from near Gadgetzan. The crate must be emptied in Tanaris, away from town and other trash.",h="Jhordy Lapforge asks you to remove dangerously charged refuse from near Gadgetzan.",sec={{t="Charged Refuse",b="Jhordy Lapforge’s tests with the Matter Transporter have left some materials dangerously charged. The objects give off energy that can burn anyone who stays near too long. He asks you to empty a crate of radioactive refuse in the desert of Tanaris, well away from Gadgetzan and other trash.",sp=0}},faq={{q="What is in the crate?",a="The crate holds refuse from experiments with the Matter Transporter. Some tested materials became dangerously charged.",al={"crate contents","radioactive refuse","gnomish garbage"}},{q="Why does the refuse need to be dumped?",a="The charged objects give off energy that can burn anyone who stays near them too long.",al={"why dump it","dangerous garbage"}},{q="Who is Jhordy Lapforge?",a="Jhordy Lapforge asks you to dispose of the radioactive refuse.",al={"who is Jhordy","Jhordy quest"}},{q="Where should the refuse be emptied?",a="Jhordy asks you to empty it in the desert of Tanaris, a safe distance from Gadgetzan and other trash.",al={"where dump garbage","Tanaris refuse"}}},kw={"charged objects","gadgetzan","gnomish garbage","jhordy lapforge","matter transporter","radioactive refuse","tanaris"},rel={"zone:tanaris","subzone:gadgetzan"},m={id=97536},src={"In-game quest text: Gnomish Garbage"},fv=true}
E["quest:992"] = {t="quest",n="Gadgetzan Water Survey",z="tanaris",s="Gadgetzan needs water, and Senior Surveyor Fizzledowser is searching the desert for a new source. The Gadgetzan Water Company has lost every well to the nomads, so Fizzledowser hires you to sample a pool near Sandsorrow Watch.",h="Gadgetzan needs water, and Senior Surveyor Fizzledowser is searching the desert for a new source.",sec={{t="A Company in Need of Water",b="The Gadgetzan Water Company has lost every well to the nomads. Now Senior Surveyor Fizzledowser hopes to find other free sources in the desert, but the search calls for a survey. The company needs a temporary junior-grade surveyor to help.",sp=0},{t="Sampling at Sandsorrow Watch",b="Fizzledowser gives you an untapped dowsing widget and sends you to the pool near Sandsorrow Watch. It lies due west of Gadgetzan and south of Zul'Farrak, within view of nearby trolls. Use the widget to tap a water sample, then return it to Fizzledowser.",sp=0},{t="Back With Fizzledowser",b="Fizzledowser learns that a bad mojo creepy-crawly ambushed you on the return journey. Reports have also described crazy bug-creatures sucking up the desert's water. Fizzledowser first dismissed the reports as nonsense, likely more trouble from the nomads. Now the truth is known.",sp=1}},faq={{q="Who offers the survey work in Gadgetzan?",a="Senior Surveyor Fizzledowser is hiring a temporary junior-grade surveyor for the Gadgetzan Water Company.",al={"who gives gadgetzan water survey","gadgetzan water survey quest giver","who is fizzledowser"}},{q="Why is the Gadgetzan Water Company searching for new pools?",a="The nomads have seized every well belonging to the company, so it needs other free sources of water.",al={"why survey water","why need water gadgetzan"}},{q="Where is the pool to be sampled located?",a="The pool near Sandsorrow Watch lies due west of Gadgetzan and south of Zul'Farrak, within view of nearby trolls.",al={"where is the pool","sandsorrow watch pool location","where to use dowsing widget"}},{q="What tool is provided for gathering the sample?",a="You use a dowsing widget at the pool to tap a water sample.",al={"dowsing widget","what item is used"}},{q="What follows this step?",a="This begins a chain that continues with the Noxious Lair Investigation.",al={"what quest comes next","gadgetzan water survey chain"}}},kw={"dowsing widget","fizzledowser","gadgetzan","gadgetzan water company","sandsorrow watch","tanaris"},rel={"npc:senior-surveyor-fizzledowser","subzone:gadgetzan","subzone:sandsorrow-watch","quest:82","subzone:zul-farrak","zone:tanaris","topic:troll"},m={start="Senior Surveyor Fizzledowser",["end"]="Senior Surveyor Fizzledowser",level="46",id=992,ri={"Tapped Dowsing Widget"}},src={"Gadgetzan Water Survey"}}
E["subzone:broken-pillar"] = {t="subzone",n="Broken Pillar",z="tanaris",s="South of Gadgetzan, Marvon Rivetseeker studies artifacts buried in Tanaris’s sands. His research camp stands beside the ancient troll ruins of the Broken Pillar.",h="South of Gadgetzan, Marvon Rivetseeker studies artifacts buried in Tanaris’s sands.",sec={{t="Sun-Bleached Stone",b="South of Gadgetzan and east of the Abyssal Sands, the Broken Pillar rises from the desert. Tanaris has swallowed much of its ancient troll stonework. Desert beasts roam nearby, yet the ruins still offer clues to the continent’s earliest civilizations. Marvon Rivetseeker, a goblin researcher from Ratchet, has made his camp beside the shattered stones. There he examines Gahz'ridian relics scattered across the waste.",sp=0}},faq={{q="What is the Broken Pillar?",a="The Broken Pillar is an ancient troll ruin in central Tanaris, south of Gadgetzan and east of the Abyssal Sands. Weathered pillars and debris, half-buried in shifting dunes, are all that remain.",al={"broken pillar tanaris","what is broken pillar","pillar ruins"}},{q="Who is camped at the Broken Pillar?",a="Marvon Rivetseeker, a goblin scientist and prospector from Ratchet, has made a research camp among the ruins. He studies mysterious Gahz'ridian ornaments buried in the surrounding desert.",al={"who is at broken pillar","broken pillar npc","marvon rivetseeker location"}},{q="Who built the original ruins here?",a="Ancient trolls built the ruins. Their stonework dates to the time when troll empires ruled southern Kalimdor, long before desert sands covered the region.",al={"who built broken pillar","broken pillar history","broken pillar origin"}},{q="What are Gahz'ridian relics?",a="Gahz'ridian are ancient stone artifacts and carved faces buried in Tanaris’s sands. From his camp at the Broken Pillar, Marvon Rivetseeker studies them to uncover the craft and power of the vanished empire.",al={"gahzridian","what is gahzridian","marvon quest items"}}},ang={["race:Troll"]="For trolls, the crumbling pillars mark an age of ancestral troll architecture, before time and sand broke the empire’s dominion over southern Kalimdor.",["race:Gnome"]="Marvon Rivetseeker’s study of unknown relics reflects gnomish scholarly curiosity, though his methods are distinctly goblin."},kw={"broken pillar","gadgetzan","gahz'ridian","marvon rivetseeker","ratchet","tanaris","troll ruins"},rel={"zone:tanaris","subzone:gadgetzan","subzone:ratchet","topic:troll","topic:goblin"},src={"Broken Pillar"}}
E["subzone:caverns-of-time"] = {t="subzone",n="Caverns of Time",z="tanaris",s="In the Caverns of Time, Nozdormu and the bronze dragonflight guard Azeroth's fragile timeways. Deep in Tanaris's eastern cliffs, they watch for mortal intrusion and changes to time's flow.",h="In the Caverns of Time, Nozdormu and the bronze dragonflight guard Azeroth's fragile timeways.",sec={{t="The Winding Timeways",b="Deep beneath Tanaris's eastern cliffs, the Caverns of Time gather the currents of history. At the dawn of the world, the titans charged Nozdormu the Timeless One and his bronze dragonflight with guarding these winding corridors.\n\nTime moves strangely within them, and hidden rifts show glimpses of the past and future. Relics from distant eras lie scattered across the sands. Anachronos watches near the entrance while lesser bronze drakes patrol the descent and guard the one true timeline.",sp=0},{t="A Hoard of Eras",b="The Caverns of Time also hold a vault where past and future meet. Over millennia, the bronze flight has gathered fragments of Azeroth's history: ancient dwarven structures, a watchtower from Lordaeron, chieftain quarters from the orcish clans, and armor from the first kings of Stromgarde. Some travelers have slipped past the sentinels to see these wonders. The inner gateways stay shut until the flight decides mortal intervention is needed.",sp=0}},faq={{q="Can I go inside the Caverns of Time right now?",a="No. The way into the Caverns of Time remains sealed, and the bronze dragonflight admits no mortals. Anachronos is indifferent to travelers, but his companions patrol the entrance and attack mortals who stray too close.",al={"can i enter caverns of time","how to enter caverns of time","is caverns of time open"}},{q="Who rules over the Caverns of Time?",a="Nozdormu the Timeless One rules the Caverns of Time. The titans empowered him to oversee time, and he entrusts their daily stewardship and the entrance guard to his prime scion, Anachronos, and the bronze dragonflight's guardians.",al={"who leads caverns of time","caverns of time boss","who lives in caverns of time"}},{q="Why are there random buildings and artifacts inside?",a="Nozdormu spent ages collecting and cataloging physical relics from across Azeroth's history. The caverns hold misplaced treasures, including a Lordaeron guard tower, dwarven architecture, orcish structures, and weapons from long-forgotten mortal kingdoms.",al={"why are there human towers in caverns of time","artifacts in caverns of time"}},{q="What is the purpose of the bronze dragonflight here?",a="The titans charged the bronze dragonflight with guarding time's flow and history's integrity. Its guardians prevent mortal tampering and outside disruptions from unraveling the events that define the world.",al={"what do bronze dragons do here","bronze flight purpose"}}},ang={["class:Mage"]="The temporal magic in the Caverns of Time far exceeds mortal chronomancy. As a Mage, you can glimpse forces beyond arcane manipulation.",["race:NightElf"]="As a Night Elf, you remember the kaldorei's ancient pacts with the Dragon Aspects. Nozdormu's charge is essential to preserving the world's survival."},kw={"anachronos","bronze dragonflight","caverns of time","nozdormu","tanaris","temporal","timeways"},rel={"zone:tanaris","topic:titan","topic:lordaeron"},src={"Caverns of Time"}}
E["subzone:circle-of-aquementas"] = {t="subzone",n="Circle of Aquementas",z="tanaris",s="Travelers come to Tanaris’s eastern shore to summon Aquementas at the Circle of Aquementas.",h="Travelers come to Tanaris’s eastern shore to summon Aquementas at the Circle of Aquementas.",sec={{t="A Ring by the Sea",b="South of Lost Rigger Cove, the Circle of Aquementas stands where Tanaris’s eastern shore meets the desert. Weathered stones rise beside the sea in a ring. Travelers gather here to call Aquementas, an elemental spirit linked to an ancient artifact. Southsea brigands and sea creatures roam the nearby beaches, but the stones mark a place for summoning.",sp=0}},faq={{q="What is the Circle of Aquementas?",a="On Tanaris’s southeastern coast, upright stones form a ring where travelers can summon the elemental spirit Aquementas.",al={"what is this stone ring","circle of aquementas purpose","standing stones tanaris"}},{q="Where is the circle located?",a="The circle lies on Tanaris’s eastern shore, directly south of the cliffs and entrance to Lost Rigger Cove.",al={"where is circle of aquementas","how to find circle of aquementas","circle of aquementas location"}},{q="Who is Aquementas?",a="Aquementas is an elemental spirit linked to an ancient artifact, summoned at the circle of stones.",al={"who is aquementas","aquementas lore"}},{q="Is the circle guarded by pirates?",a="Southsea pirates prowl near Lost Rigger Cove and the surrounding shore. The circle itself is an isolated place for summoning.",al={"are there pirates here","southsea pirates near circle"}}},ang={["class:Shaman"]="As a shaman on the Tanaris coast, you may find the circle’s power to focus primal energies and anchor an elemental spirit intriguing."},kw={"aquementas","circle of aquementas","elemental","lost rigger cove","standing stones","tanaris"},rel={"zone:tanaris","subzone:lost-rigger-cove","topic:pirate"},src={"Circle of Aquementas"},nf=true}
E["subzone:dunemaul-compound"] = {t="subzone",n="Dunemaul Compound",z="tanaris",s="At the western edge of Tanaris, Dunemaul ogres gather around their central settlement. The clan’s mound and cave network lie among rocky ridges.",h="At the western edge of Tanaris, Dunemaul ogres gather around their central settlement.",sec={{t="A Stronghold in the Sands",b="In western Tanaris, Dunemaul ogres guard their stronghold from travelers crossing the dunes. The harsh arid climate has taught the clan to survive through brute force and opportunism. Their settlement gathers around an ogre mound and a network of caves. Warriors and enforcers patrol beside twisted spellcasters who wield dark warlock and mage magic. The ogres violently reject uninvited guests.",sp=0}},faq={{q="Who rules the Dunemaul Compound?",a="Gor'marok the Ravager leads the Dunemaul ogres at the compound. In Gadgetzan, Andi Lynn fears the strength of this newly arrived band.",al={"dunemaul leader","dunemaul boss"}},{q="What kinds of ogres live here?",a="Common brutes and enforcers live here, along with cunning ogre mages and warlocks who wield dark fel and shadow magic.",al={"dunemaul types","dunemaul mobs"}},{q="Why is the Horde interested in this compound?",a="The Horde has no recorded interest in the compound. Gor'marok the Ravager leads the independent Dunemaul band. In Gadgetzan, Andi Lynn calls for the compound's destruction because she fears their growing strength will threaten the region.",al={"horde dunemaul"}},{q="Who is Omgorn the Lost?",a="Omgorn the Lost is an elusive, solitary ogre who sometimes wanders the edges of the Dunemaul Compound. He stays apart from the common sentries patrolling the mound.",al={"omgorn","rare ogre tanaris"}}},ang={["faction:Horde"]="Many ogres once marched with the Old Horde, but the reclusive Dunemaul answer to no outside power. They treat Horde travelers as intruders like any other.",["class:Warlock"]="As a warlock, you may find the Dunemaul warlocks a curious sight among a seemingly primitive desert clan. Their presence shows that shadow and fel traditions have taken root even in isolated ogre mounds."},kw={"dunemaul compound","dunemaul ogres","ogre mound","omgorn","tanaris"},rel={"zone:tanaris","subzone:southmoon-ruins","topic:horde"},src={"Dunemaul Compound"}}
E["subzone:eastmoon-ruins"] = {t="subzone",n="Eastmoon Ruins",z="tanaris",s="Dunemaul ogres occupy Eastmoon Ruins, west of the Gaping Chasm in eastern Tanaris. Their camp stands among the remains of an ancient troll site.",h="Dunemaul ogres occupy Eastmoon Ruins, west of the Gaping Chasm in eastern Tanaris.",sec={{t="Stones in the Sand",b="West of the Gaping Chasm, old troll stones rise from Tanaris’s desert sands. Their pillars and plazas have crumbled with age. Now Dunemaul ogres shelter among the broken walls and watch the nearby trade routes.",sp=0}},faq={{q="Who built the Eastmoon Ruins?",a="Ancient trolls built Eastmoon Ruins. Their stonework and plazas remain in the desert, worn by time.",al={"who made eastmoon ruins","eastmoon origin","trolls built eastmoon"}},{q="Who controls Eastmoon Ruins now?",a="Dunemaul ogres occupy Eastmoon Ruins now. They camp among the old walls and watch over eastern Tanaris.",al={"who lives at eastmoon","eastmoon ruins mobs","wastewanders at eastmoon"}},{q="Where are the Eastmoon Ruins located?",a="Eastmoon Ruins lie in eastern Tanaris, just west of the Gaping Chasm.",al={"eastmoon ruins location","where is eastmoon","find eastmoon ruins"}},{q="Are there any quests in Eastmoon Ruins?",a="Eastmoon Ruins are a Dunemaul ogre camp and an old landmark in the deeper desert. You can explore the surrounding area, though no work is directed specifically to the ruins.",al={"eastmoon quests","quests at eastmoon ruins","is there a quest here"}}},ang={["race:Troll"]="As a troll, you can see a reminder of your ancestors’ reach across Kalimdor before the desert sands claimed the south.",["class:Rogue"]="As a rogue, you can use the broken pillars and walls to slip past or ambush Dunemaul ogres along the perimeter."},kw={"dunemaul","eastmoon","eastmoon ruins","gaping chasm","tanaris","troll ruins"},rel={"zone:tanaris","subzone:gaping-chasm","topic:troll"},src={"Eastmoon Ruins"}}
E["subzone:gadgetzan"] = {t="subzone",n="Gadgetzan",z="tanaris",s="Trade brings both factions to Gadgetzan, where the Steamwheedle Cartel keeps the peace. Anyone may enter, provided they bring coin or work to offer.",h="Trade brings both factions to Gadgetzan, where the Steamwheedle Cartel keeps the peace.",sec={{t="A Bastion of Profit in the Dunes",b="Amid Tanaris's scorching sands, Gadgetzan is the Steamwheedle Cartel's base for trade in southern Kalimdor. Goblin ingenuity gives its buildings a haphazard shape. Within them are an auction house, a bank, an inn, and workshops for engineers, blacksmiths, and alchemists.\n\nFlight masters carry travelers of both factions toward Tanaris, Feralas, and the basin of Un'Goro. Commerce rules here. Keep your weapons sheathed and your purse open, and the goblins will let you pass in peace.",sp=0},{t="Desert Troubles and Enforced Order",b="Goblin bruisers keep order in Gadgetzan. They pummel anyone who threatens trade or starts a faction brawl. Beyond the gates, the Gadgetzan Water Company struggles against Wastewander bandits at Waterspring Field. Water is precious in Tanaris, so the cartel hires mercenaries to defeat the bandit leaders and recover water pouches. The town's reservoirs depend on that supply.",sp=0}},faq={{q="Can Alliance and Horde attack each other in Gadgetzan?",a="No. The Steamwheedle Cartel keeps Gadgetzan strictly neutral. Goblin bruisers patrol the town and attack anyone who breaks the peace or harms other travelers.",al={"is gadgetzan safe","pvp in gadgetzan","can horde and alliance fight here"}},{q="Why is water such a big deal around here?",a="Gadgetzan depends on water from the extraction towers of the Gadgetzan Water Company at Waterspring Field. Wastewander bandits have overrun the wells and cut off the town's main supply. So the goblins offer bounties for stolen water pouches.",al={"gadgetzan water company","why water pouches","waterspring field conflict"}},{q="Who controls Gadgetzan?",a="The Steamwheedle Cartel owns and governs Gadgetzan. It is Azeroth's largest and most prominent mercantile goblin organization.",al={"who runs gadgetzan","gadgetzan faction","what cartel owns gadgetzan"}},{q="What makes the auction house here special?",a="Gadgetzan's neutral auction house lets Alliance and Horde buy and sell goods to each other. The goblins charge a much higher transaction fee for this privilege.",al={"gadgetzan auction house","neutral auction house","cross faction ah"}}},ang={["profession:Engineering"]="As an engineer, you can find advanced trainers and specialized schematics in Gadgetzan. The town also has an arrival teleportation pad calibrated for gnomish engineers.",["profession:Blacksmithing"]="As a blacksmith, you can use Gadgetzan's heavy-duty forges and anvils, favored by advanced metalworkers. The town is a key staging ground for members of the Mithril Order."},kw={"auction house","gadgetzan","goblin","neutral","steamwheedle cartel","tanaris","wastewander","waterspring field"},rel={"topic:steamwheedle-cartel","zone:tanaris","subzone:waterspring-field","zone:ungoro","topic:goblin","subzone:ratchet"},src={"Gadgetzan"}}
E["subzone:gaping-chasm"] = {t="subzone",n="Gaping Chasm",z="tanaris",s="In southeastern Tanaris, the Gaping Chasm opens into a Hazzali silithid hive. Its tunnels spread beneath the desert and reveal how far the brood has reached beyond the western sands.",h="In southeastern Tanaris, the Gaping Chasm opens into a Hazzali silithid hive.",sec={{t="The Hive in the Dunes",b="The Gaping Chasm cuts through Tanaris, where tunnels wind among mounds of resin. Beneath the desert, the Hazzali silithid burrow in an aggressive brood. Stingers, swarmers, and hulking sandreavers hunt anyone who descends, traveler or treasure-hunter. The tunnels may trap them in sticky cocoons.",sp=0},{t="A Surveyor's Grave",b="As the hive grew, Gadgetzan grew concerned. Senior Surveyor Fizzledowser sent junior surveyor Scrimshank into the pit to map and measure the geological shifts caused by the insect tunnels. The expedition ended in disaster. Scrimshank died among the chittering broods, leaving scattered gear and measuring instruments as a warning against underestimating the silithid.",sp=0}},faq={{q="What creatures dwell inside the Gaping Chasm?",a="The Hazzali silithid dwell inside the chasm. Their hive holds many castes, including worker drones, winged stingers, swarms, and massive, chitin-plated sandreavers.",al={"what lives in gaping chasm","bugs in tanaris chasm","gaping chasm mobs"}},{q="Where is the Gaping Chasm located?",a="The Gaping Chasm lies in southeastern Tanaris, south of Gadgetzan and east of the mountain ridge that divides Tanaris from the western wilderness.",al={"where is gaping chasm","gaping chasm location","how to find gaping chasm"}},{q="Why was a gnome surveyor sent into the chasm?",a="Senior Surveyor Fizzledowser sent Junior Surveyor Scrimshank from Gadgetzan to survey the cavern and assess its geological activity. The Hazzali silithid overwhelmed and killed Scrimshank before he could finish.",al={"who was scrimshank","fizzledowser surveyor quest","why did scrimshank go there"},sp=1},{q="Are the silithid here related to the ones in other parts of Kalimdor?",a="Yes. The Hazzali silithid in Tanaris share the insectoid nature and hive-mind structure of broods in the southern barrens and Silithus to the west. Their presence signals a dangerous, coordinated expansion across southern Kalimdor.",al={"are these silithid connected to silithus","why are bugs in tanaris"}}},ang={["race:Gnome"]="As a gnome, remember Junior Surveyor Scrimshank's death in the chasm. Field research in Kalimdor calls for serious firepower as well as scientific curiosity.",["profession:Mining"]="As a miner, you may find rich mineral deposits in the hive's exposed clefts and sunken earth. Reaching them means fending off dozens of vicious burrowing insects."},kw={"fizzledowser","gaping chasm","hazzali","hive","sandreaver","scrimshank","silithid","tanaris"},rel={"zone:tanaris","subzone:gadgetzan","npc:senior-surveyor-fizzledowser"},src={"Gaping Chasm"}}
E["subzone:land-s-end-beach"] = {t="subzone",n="Land's End Beach",z="tanaris",s="At Kalimdor’s southern edge, Land's End Beach lies quiet beneath the sun. Tanaris’s southern mountains and the vast South Seas cut this coast off from the desert.",h="At Kalimdor’s southern edge, Land's End Beach lies quiet beneath the sun.",sec={{t="The Edge of the World",b="Beyond Tanaris’s southern mountains, Land's End Beach meets the far southern edge of Kalimdor’s mainland. The sealed titan gateway to Uldum stands beyond the ranges. No desert route reaches this coast, so travelers must swim through the dangerous open waters of the South Seas.\n\nSurf breaks on shifting sand along the barren shore. The cartels and desert explorers who live farther north around Gadgetzan rarely come here.",sp=0},{t="Offshore Mysteries",b="Unnamed islets lie beyond the beach’s breakers, with broad stretches of deep water between them and the mainland. Reaching these rocks can exhaust even seasoned swimmers. Few mortals have reason to seek out the lonely waters at Kalimdor’s end, so the beach and nearby shoals remain undisturbed beneath the southern sun.",sp=0}},faq={{q="Where is Land's End Beach located?",a="Land's End Beach follows Tanaris’s southernmost coast, south of the mountains that seal off the ancient titan gates of Uldum, at Kalimdor’s far southern tip.",al={"where is lands end beach","lands end beach location","how to find lands end beach"}},{q="How do you reach Land's End Beach?",a="The southern mountain ranges block overland travel from the desert interior. Travelers must swim along the southern coast from eastern Tanaris or cross the perilous open waters, where deep-sea fatigue threatens them.",al={"how do i get to lands end beach","get to lands end tanaris","reach lands end"}},{q="What is on the islands off the coast of the beach?",a="Unnamed, remote islands lie far off the shore across a broad channel of deep ocean. These desolate rocky spits have seen few travelers, and few have explored them.",al={"unnamed islands lands end","offshore islands tanaris","islands near lands end"}},{q="Does anyone live on Land's End Beach?",a="No major settlements line the shore. Cut off from trade and civilization, Land's End Beach remains a barren natural shore exposed to ocean winds.",al={"who lives at lands end","lands end beach inhabitants","is anyone at lands end"}}},kw={"beach","coast","kalimdor","land's end beach","shore","south seas","tanaris","uldum"},rel={"zone:tanaris","subzone:uldum","subzone:gadgetzan"},src={"Land's End Beach"}}
E["subzone:lost-rigger-cove"] = {t="subzone",n="Lost Rigger Cove",z="tanaris",s="At Lost Rigger Cove, pirate ships take shape along Tanaris's eastern cliffs. Desert mountains shield the hidden port on three sides, where the Southsea Pirates keep docks and fortified camps beside their shipyard.",h="At Lost Rigger Cove, pirate ships take shape along Tanaris's eastern cliffs.",sec={{t="Pirates and Mountain Walls",b="Rock walls guard almost every side of Lost Rigger Cove. Here on Kalimdor's southeastern edge, the Southsea Freebooters haul salvage and build fresh hulls under Gadgetzan's nose. Cutthroats, dockworkers, and brigands work from this stronghold. From here, Southsea power reaches across the Great Sea, and its pirates raid trade routes between Ratchet, Booty Bay, and coastal settlements.",sp=0},{t="Rivals on the Doorstep",b="Gadgetzan and nearby Steamwheedle Port oppose the Southsea Pirates at their doorstep. The goblins resent the raiders, so they pay mercenaries to slaughter them, thin their ranks, and disrupt their operations.",sp=0}},faq={{q="Who controls Lost Rigger Cove?",a="The Southsea Pirates hold Lost Rigger Cove. This infamous maritime syndicate ranges across Kalimdor and the South Seas. It uses the natural harbor to repair its fleet and build new warships.",al={"who owns lost rigger cove","who lives in lost rigger cove","lost rigger cove factions"}},{q="Who is fighting the pirates here?",a="The goblins of Gadgetzan and Steamwheedle Port fight the pirates. Resenting raiders on their doorstep, they hire passing adventurers to strike at the stronghold and thin the Southsea ranks.",al={"gnome goblin camp tanaris","why are gnomes here","why fight the pirates"}},{q="Where is Lost Rigger Cove located?",a="Lost Rigger Cove lies along Tanaris's eastern coast, southeast of Gadgetzan. A winding canyon path crosses the coastal mountain barrier and leads there.",al={"where is lost rigger cove","how to get to lost rigger cove","lost rigger cove map"}},{q="What are the pirates building in the cove?",a="The Southsea Pirates are building a large ocean-going war vessel. Carpenters and brigands assemble its hull in an active drydock and shipyard at the cove's center.",al={"shipyard lost rigger cove","pirate boat construction"}}},ang={["class:Rogue"]="As a rogue, you find a sprawling pirate camp with pockets to pick, private lockboxes, and cutthroats skilled in every dirty trick of maritime swashbuckling.",["race:Gnome"]="As a gnome, you can read the pirates' drydock as a crude display of salvaged machinery and stolen parts. It threatens every merchant vessel on the southern seas."},kw={"freebooter","gadgetzan","lost rigger cove","shipyard","southsea pirates","tanaris"},rel={"zone:tanaris","subzone:gadgetzan","topic:gnome","topic:goblin","topic:pirate"},src={"Lost Rigger Cove"}}
E["subzone:noxious-lair"] = {t="subzone",n="Noxious Lair",z="tanaris",s="In Tanaris, Centipaar silithid have made the Noxious Lair their home. They drained the water from a sunken basin near Un'Goro Crater and raised an acidic hive above rich mineral veins.",h="In Tanaris, Centipaar silithid have made the Noxious Lair their home.",sec={{t="A Drained Basin",b="Beside the western ridges above Un'Goro Crater, the Noxious Lair fills a sandy hollow. A lake or shallow river once lay here, but the Centipaar silithid consumed the remaining underground moisture and claimed the basin. Now pincers and twitching limbs rise from the dunes above tunnels in the sand. Corrosive secretions coat the passages, and clusters of eggs fill the chambers.",sp=0},{t="The Centipaar Swarm",b="Entrances descend into humid breeding chambers slick with acid. Centipaar workers, tunnelers, wasps, and colossal sandreavers patrol the perimeter and guard their brood from outside threats. Their digging has exposed deep mineral deposits too. Ore lies bare among the hives, drawing hunters and prospectors to the basin.",sp=0}},faq={{q="What kind of creatures live in the Noxious Lair?",a="Centipaar silithid fill the hive. Workers, burrowing tunnelers, flying wasps, and predatory sandreavers defend it. Rare hive terrors such as Soriid the Devourer rule within.",al={"what mobs are in noxious lair","noxious lair insects","centipaar silithid"}},{q="What was here before the silithid took over?",a="A riverbed or shallow desert lake once filled the sunken basin. The silithid burrowed underground and drained western Tanaris of vital water and natural resources, leaving an acid-soaked hollow.",al={"noxious lair history","was noxious lair a lake","water in noxious lair"}},{q="Why are goblins interested in this hive?",a="Gadgetzan goblins see the hive as a danger to desert commerce. They have sent adventurers to investigate the lair and the silithid expansion.",al={"goblin quests noxious lair","steamwheedle noxious lair","thunderdrome silithid"}},{q="Is the Noxious Lair connected to other insect hives in the desert?",a="The Noxious Lair is the Centipaar hive, one of several insect colonies spreading from the southern wastes. Its tunnels are separate from hives farther south, yet share their eerie underground design and threaten life across Tanaris.",al={"other hives tanaris","centipaar hive connection","silithid expansion"}}},ang={["profession:Mining"]="Silithid burrowing has exposed many kinds of ore in the basin. You can find Iron, Mithril, Truesilver, and Thorium veins in the same territory.",["class:Druid"]="As a druid, you see how invasive silithid drained a once-watered basin and turned it into an arid, acidic wasteland."},kw={"centipaar","hive","noxious lair","sandreaver","silithid","soriid","tanaris"},rel={"zone:tanaris","zone:ungoro","topic:goblin"},src={"Noxious Lair"}}
E["subzone:ruins-of-uldum"] = {t="subzone",n="Ruins of Uldum",z="tanaris",s="In southern Tanaris, the Ruins of Uldum guard a sealed Titan facility beneath the cliffs of the Valley of the Watchers. Stone doors keep grave robbers and curious explorers from its secrets.",h="In southern Tanaris, the Ruins of Uldum guard a sealed Titan facility beneath the cliffs of the Valley of the...",sec={{t="The Antechamber of the Titans",b="Deep in southern Tanaris, a grand stone threshold leads into the bedrock toward a sealed underground complex. Colossal gates block the way, and no mechanism or key known to modern scholars has opened them.",sp=0},{t="Secrets of the Biosphere",b="The Titans built Uldum to study Azeroth’s biosphere, alongside facilities such as Uldaman and Ulduar. When the Great Sundering tore the world apart ten thousand years ago, the earthen felt its agony and retreated into the vaults to hibernate. The lost Plates of Uldum are needed to pass the inner threshold, so the full facility remains closed to those on the surface.",sp=1}},faq={{q="What is inside the Ruins of Uldum?",a="No one knows for certain what lies beyond the gates. The ruins are an ancient Titan hall, and the complex behind them remains sealed to modern explorers.",al={"what's in uldum","what is uldum tanaris","ruins of uldum interior"}},{q="Can players enter the main facility behind the door?",a="No. The gates remain sealed. The Stone Watcher of Norgannon says only those carrying the lost Plates of Uldum may enter the compound, and no one has found them.",al={"can you open the door to uldum","how to get into uldum","open uldum door"}},{q="What was Uldum built for?",a="Uldum was built as a Titan research complex to study, sustain, and enhance Azeroth’s biosphere. The Stone Watcher of Norgannon describes it as similar in origin to Uldaman and Ulduar.",al={"why did titans build uldum","uldum purpose","lore of uldum"}}},ang={["race:Dwarf"]="As a dwarf descended from the earthen, you can trace your ancestors to one of the original Titan crèches. They first rested there after the Sundering.",["profession:Mining"]="As a miner, you can see Titan craftsmanship in Uldum’s stonework and machinery. Both have endured thousands of years of tectonic pressure and desert decay without faltering."},kw={"earthen","tanaris","titans","uldum","valley of the watchers"},rel={"subzone:valley-of-the-watchers","zone:tanaris","topic:titan","subzone:uldaman"},src={"Ruins of Uldum"}}
E["subzone:sandsorrow-watch"] = {t="subzone",n="Sandsorrow Watch",z="tanaris",s="At Sandsorrow Watch, Sandfury trolls hold the desert ruins and dunes just west of Gadgetzan.",h="At Sandsorrow Watch, Sandfury trolls hold the desert ruins and dunes just west of Gadgetzan.",sec={{t="A Precarious Perch",b="Leave Gadgetzan through its western gate and you enter Sandfury territory almost at once. Trolls and shambling dead command the open desert, while an old watch tower rises at the eastern edge.",sp=0},{t="Frontier Outpost",b="Sandfury trolls hold even the eastern tower, within sight of Gadgetzan's walls. From its heights, they watch the goblin town. Travelers leaving through the western gate step onto a tense frontier, where settlers and sand trolls face one another.",sp=0}},faq={{q="Where is Sandsorrow Watch located?",a="Sandsorrow Watch lies directly west of Gadgetzan, in Tanaris's northern desert plains. You reach it almost at once through the town's western gate.",al={"sandsorrow watch location","where is sandsorrow","how to get to sandsorrow watch"}},{q="Who controls Sandsorrow Watch?",a="Hostile Sandfury trolls and their undead minions occupy the ruins, dunes, and eastern watch tower.",al={"who lives at sandsorrow","sandsorrow watch faction","who holds sandsorrow watch"}},{q="Why are there undead trolls at Sandsorrow Watch?",a="The Sandfury practice necromantic arts and voodoo. They raise fallen warriors as Sandfury Zombies to guard their territory and outposts across Tanaris.",al={"sandfury zombies","why troll zombies tanaris","sandsorrow zombies"}},{q="What threats can adventurers expect in the surrounding dunes?",a="Sandfury Axe Throwers, Firecallers, and Hideskinners patrol the dunes with reanimated troll zombies. Leave the main path west of Gadgetzan and roving Sandfury warbands may overwhelm you.",al={"sandsorrow mobs","sandsorrow watch enemies","hostile trolls sandsorrow"}}},ang={["profession:Blacksmithing"]="No smith works at the Sandfury-held watch tower. Desert smiths gather behind Gadgetzan's walls, just to the east.",["race:Troll"]="As a troll, you will find no kinship with the Sandfury. They see outsiders as invaders to crush and raise as shambling corpses."},kw={"gadgetzan","sand troll","sandfury","sandsorrow","sandsorrow watch","tanaris"},rel={"zone:tanaris","subzone:gadgetzan","topic:troll"},src={"Sandsorrow Watch"}}
E["subzone:south-seas"] = {t="subzone",n="South Seas",z="tanaris",s="Merchant ships and pirate crews contend across the South Seas, between southern Kalimdor and the Eastern Kingdoms. Tanaris and Stranglethorn Vale border these tropical waters, where reefs and other dangers threaten every voyage.",h="Merchant ships and pirate crews contend across the South Seas, between southern Kalimdor and the Eastern...",sec={{t="A Swashbuckler's Frontier",b="The South Seas stretch south from the Great Sea and the Maelstrom, washing against Tanaris and Stranglethorn Vale. The Great Sundering shattered the primeval continent ten thousand years ago, leaving remote tropical islands and waters rich with ocean life.\n\nIndependent merchant networks cross these seas. Goblin shipping cartels work from havens such as Steamwheedle Port and Booty Bay to keep the lanes open. Corsairs and Bloodsail buccaneers prey on passing ships, while dangerous sea life threatens vessels far from shore.",sp=0},{t="Hidden Depths and Distant Isles",b="Beyond the coastal trade lanes lie legendary islands and dangers beneath the waves. Zandalar, the ancient troll island, and the produce-rich shores of Tel'Abim are scattered across the South Seas. Cutthroats are not the only danger: giant squids, primeval sea turtles, and naga haunt the deeper waters. The naga guard ancient ruins swallowed by the waves. Captains need experience, reliable charts, and substantial firepower to cross these seas.",sp=0}},faq={{q="What zones border the South Seas?",a="In southern Kalimdor, the South Seas meet Tanaris near Uldum's sealed gates. To the east, they wash against Stranglethorn Vale and nearby islands such as Jaguero Isle and Yojamba Isle.",al={"where are south seas","south seas borders","what coast is south seas"},it="place"},{q="Who controls shipping in the South Seas?",a="No single faction rules the South Seas. The Steamwheedle Cartel controls the main merchant traffic between Steamwheedle Port and Booty Bay, while rival pirate outfits such as the Bloodsail Buccaneers and the Southsea Freebooters contest the waters.",al={"who runs south seas","south sea trade","ports in south seas"},it="in_charge"},{q="What dangerous creatures live in these waters?",a="Giant squids, coastal reef sharks, and armored giant turtles threaten ships on the open waves. During the Second War, the Horde's Stormreaver clan captured giant turtles from these waters and refitted them as naval submersibles. The islands also shelter flesh-eating bloodwing bats and naga patrols.",al={"south seas monsters","sea monsters tanaris","south sea creatures"},it="threat"},{q="What notable islands lie out in the South Seas?",a="Tel'Abim, rich in fruit, and Zandalar, historic realm of the troll empire, lie in the deep waters. Yojamba Isle and Jaguero Isle sit closer to the coasts.",al={"islands in south seas","kezan zandalar south seas","south seas island list"}},{q="What is the South Seas?",a="The South Seas is the sprawling southern expanse of the Great Sea, separating the lower reaches of Kalimdor and the Eastern Kingdoms. Lying south of the raging Maelstrom, these warm, tropical waters wash against the coasts of Tanaris and Stranglethorn Vale, dotted with remote archipelagos, pirate havens, and uncharted islands.",al={"what is south seas","south seas overview","where is south seas"},it="place",add="b58adc59"},{q="What happened in the history of the South Seas?",a="Ten thousand years ago, all of Azeroth was a single continent before the Great Sundering shattered the landmass. When the Well of Eternity imploded during the War of the Ancients, the ocean rushed in to fill the rift, tearing continents apart and creating the Maelstrom and the surrounding seas. The islands scattered across the South Seas are remnants of that ancient world.",al={"south seas history","how was south seas formed","origin of south seas"},it="history",add="89d72661"},{q="Is traveling the South Seas dangerous?",a="These waters are notoriously treacherous. Beyond erratic weather and treacherous reefs, the South Seas teem with aggressive predators, including giant squids and monstrous, flesh-eating bloodwing bats nesting on tropical isles. Worse still, cutthroat pirate cartels such as the Bloodsail Buccaneers roam the shipping channels, preying upon merchant vessels and daring travelers.",al={"is south seas dangerous","south seas hazards","south seas threats"},it="danger",add="68566e28"},{q="Why is it called the South Seas?",a="The region simply takes its name from its geography as the southern portion of the Great Sea, covering the waters south of the central Maelstrom and bordering the southern coasts of both main continents.",al={"why south seas name","how did south seas get its name"},it="name",add="7fe84177"}},ang={["class:Rogue"]="The lawless South Seas sustain pirate cartels and privateers. They offer opportunities for scoundrels skilled in boarding ships, smuggling contraband, and navigating the politics of cutthroat harbors.",["profession:Cooking"]="The South Seas and their shores yield ocean fish, giant squids, and sweet bananas shipped from isolated isles such as Tel'Abim."},kw={"bloodsail","pirates","south seas","steamwheedle","stranglethorn","tanaris","tel'abim","zandalar"},rel={"zone:tanaris","subzone:steamwheedle-port","zone:stranglethorn","subzone:booty-bay","topic:pirate","topic:goblin","subzone:uldum","topic:war-of-the-ancients"},src={"South Seas"}}
E["subzone:southmoon-ruins"] = {t="subzone",n="Southmoon Ruins",z="tanaris",s="Dunemaul ogres camp among the Southmoon Ruins in southern Tanaris, north of the Valley of the Watchers. Their stones preserve the remains of an ancient troll civilization that once ruled the desert.",h="Dunemaul ogres camp among the Southmoon Ruins in southern Tanaris, north of the Valley of the Watchers.",sec={{t="Stones in the Shifting Sands",b="Weathered pillars and altars rise from the sands at Southmoon in southern Tanaris. Nearby Eastmoon and Noonshade share their age, their stones worn by thousands of years of wind and grit. Dunemaul ogres have often camped among these old structures. They claim the stones for shelter and territory, with little regard for the craft that shaped them.",sp=0},{t="Secrets Beneath the Rubble",b="Southmoon’s stones are unmistakably trollish, though little is recorded of who raised them or why they left. Whatever remains lies beneath the drifting sand. The Dunemaul ogres camp among the pillars without concern for it.",sp=0}},faq={{q="Who originally built the Southmoon Ruins?",a="The Southmoon Ruins preserve remnants of the ancient troll civilization that once held the southern reaches of what is now the Tanaris desert.",al={"who built southmoon","southmoon history","are these troll ruins"}},{q="Who inhabits the ruins currently?",a="Dunemaul ogres traditionally inhabit the ruins. They wandered into Tanaris, claimed crumbling ancient outposts as camps, and drove off other scavengers.",al={"who lives here","southmoon mobs","dunemaul at southmoon"}},{q="Where are the Southmoon Ruins located?",a="The Southmoon Ruins lie in southern Tanaris, northwest of the Valley of the Watchers and south of the central desert wastes.",al={"southmoon location","where is southmoon ruins","how to find southmoon"}}},ang={["race:Dwarf"]="As a dwarf crossing southern Tanaris, you find weathered troll stonework at Southmoon, with Dunemaul ogres camped among it.",["race:Troll"]="As a Darkspear troll, you see the fallen grandeur of distant troll cousins in these broken columns, now reduced to squalor beneath the desert sun."},kw={"dunemaul","ruins","southmoon","southmoon ruins","tanaris","valley of the watchers"},rel={"zone:tanaris","subzone:valley-of-the-watchers","topic:troll"},src={"Southmoon Ruins"}}
E["subzone:steamwheedle-port"] = {t="subzone",n="Steamwheedle Port",z="tanaris",s="Steamwheedle Port keeps Gadgetzan linked to the eastern shore of Tanaris. The neutral Steamwheedle Cartel runs its docks and holds open a sea route across the South Seas, though Southsea Pirates press nearby.",h="Steamwheedle Port keeps Gadgetzan linked to the eastern shore of Tanaris.",sec={{t="A Gateway on the Shifting Sands",b="On Tanaris's eastern shore, the docks give Gadgetzan a direct route to maritime trade. The Steamwheedle Cartel runs the settlement, where dockhands, traders, and sea captains face treacherous waters. Supply vessels sail between the port and distant goblin trading posts, bringing mechanical components, luxuries, and raw materials into southern Kalimdor.",sp=0},{t="Pirates and Strange Scholars",b="Southsea Freebooters raid goblin shipping from Lost Rigger Cove, just south along the coast. They steal cargo and contest control of the shoreline, while dockworkers haggle and merchants seek to recover stolen shipments. The port also shelters unusual travelers. Among them is Yeh'kinya, a troll scholar studying the world's ancient and ominous spirits away from prying eyes.",sp=0}},faq={{q="Who controls Steamwheedle Port?",a="The Steamwheedle Cartel built and runs the settlement. It is the primary trade conglomerate of neutral goblins, and welcomes Alliance and Horde travelers who maintain standing with Gadgetzan and the Cartel.",al={"who runs steamwheedle port","steamwheedle port faction","is steamwheedle port friendly"}},{q="Where do the ships from this port travel?",a="Ships from the port connect the Cartel to distant goblin trading hubs across the South Seas. A passenger ship also sails across the sea from the docks to Powderfuse Port in the Riverglades.",al={"where do ships go from steamwheedle","steamwheedle port ferry"}},{q="Why are there so many pirates nearby?",a="Southsea Freebooters have made their base at Lost Rigger Cove, just south of the port. They hijack incoming cargo, raid dock supplies, and pick off stragglers along the shoreline, making them the chief local threat to goblin trade.",al={"lost rigger cove pirates","southsea pirates tanaris"}},{q="Who is Yeh'kinya?",a="Yeh'kinya is an eccentric troll scholar resting at the port. He enlists daring travelers to go abroad and capture spiritual essences, including screechers from Feralas, for his research into forgotten, primordial rituals.",al={"yehkinya purpose","troll in steamwheedle port"}}},ang={["profession:Engineering"]="For an engineer, the port is a valuable depot for parts and supplies imported from across the South Seas. It is also a natural source of supplies and gossip for tinkerers seeking schematics.",["class:Rogue"]="As a rogue, the friction between goblin merchants and nearby Southsea Pirates creates opportunities for pickpockets, scouts, and recovery contracts."},kw={"gadgetzan harbor","lost rigger cove","southsea pirates","steamwheedle port","tanaris docks","yeh'kinya"},rel={"zone:tanaris","subzone:gadgetzan","topic:steamwheedle-cartel","subzone:lost-rigger-cove","npc:yeh-kinya","topic:pirate","subzone:south-seas","topic:goblin"},src={"Steamwheedle Port"}}
E["subzone:thistleshrub-valley"] = {t="subzone",n="Thistleshrub Valley",z="tanaris",s="In southwestern Tanaris, giant cacti and living thistleshrubs crowd a canyon. The hostile plants lash out at travelers who cross their thorn-choked ground.",h="In southwestern Tanaris, giant cacti and living thistleshrubs crowd a canyon.",sec={{t="A Grove of Thorns",b="Giant blooming cacti rise above the sand, crowding a canyon where much of Tanaris lies bare. Living thistleshrubs give the valley its name. They strike travelers who come near with sharp spines, making the crossing perilous. Their thorny brush blocks the way past the cliffs toward the mysterious southern gates.",sp=0},{t="Sentinels of the Desert",b="Travelers have long wondered how animated plants survive in such a dry land. The thistleshrubs fiercely guard their ground. Forgotten elemental energies may have awakened them, or they may have adapted to Tanaris's harsh climate. Towering cacti offer little cover from desert predators and venomous serpents in the canyon.",sp=0}},faq={{q="Where is Thistleshrub Valley located?",a="Thistleshrub Valley lies in southwestern Tanaris, along the southern mountain ridge near the mysterious sealed gates of Uldum.",al={"thistleshrub valley location","where is thistleshrub","find thistleshrub valley"}},{q="Why is there so much plant life in this part of Tanaris?",a="Unlike the barren desert around it, the valley shelters towering cacti and animated plants. How the thistleshrubs thrive so fiercely in dry sand remains a mystery of the southern dunes.",al={"why giant cactus here","why are plants growing here"}},{q="What creatures live in Thistleshrub Valley?",a="Hostile walking thistleshrubs, aggressive desert blooms and venomous reptiles live in the valley, hidden among thorny plants.",al={"thistleshrub valley mobs","monsters in thistleshrub valley"}},{q="What is the massive stone structure near the valley?",a="A massive sealed Titan structure stands just beyond the valley. Desert wanderers call it the gateway to Uldum, though it remains locked and enigmatic.",al={"doors near thistleshrub","titan gate tanaris"}}},ang={["profession:Herbalism"]="For herbalists crossing Tanaris, the valley holds unusual, resilient plants among thick groves of thorny brush.",["class:Druid"]="As a druid, you may find the viciously animated thistleshrubs fascinating. You may wonder what primeval or elemental forces keep them thriving in this desolate desert."},kw={"cacti","cactus","desert","tanaris","thistleshrub","thorns","uldum","valley"},rel={"zone:tanaris","subzone:uldum"},src={"Thistleshrub Valley"}}
E["subzone:uldum"] = {t="subzone",n="Uldum",z="tanaris",s="In Tanaris’s southern mountains, Uldum’s colossal gates remain sealed. Ancient wards and machinery hide the Titan research compound from explorers.",h="In Tanaris’s southern mountains, Uldum’s colossal gates remain sealed.",sec={{t="The Gates of the Makers",b="Uldum’s great stone gateway still bars the way in the southern mountains of Tanaris. The Titans built the compound while ordering ancient Kalimdor. It was a vast facility for shaping and overseeing the planet’s biosphere. Titan wardens and defensive constructs once guarded its bounds. Today, only the massive arches can be seen; what lies beyond remains out of mortal reach.",sp=0},{t="The Sealed Secrets",b="Dwarven scholars study the clear signs of Titan craft at Uldum, but they have found no key or mechanism to open the complex. Legend points to the lost Plates of Uldum as the means to reach its secrets. For now, the scholars can only look toward an empire they cannot enter.",sp=0}},faq={{q="Can you open the gates to Uldum?",a="No. Massive stone gates bar the mountain pass, and no mechanism or key in the surrounding desert opens them.",al={"how to get into uldum","open uldum door","enter uldum"}},{q="What is inside Uldum?",a="Ancient records and Titan lore describe Uldum as a vast research facility built by the Titans to study and enhance Azeroth’s biosphere. Titan safeguards keep the exact details hidden.",al={"what is uldum","purpose of uldum","inside uldum"}},{q="What are the Plates of Uldum?",a="The Plates of Uldum are ancient data discs made by the Titans. Lore preserved by ancient stone keepers says the plates hold the knowledge needed to reach Uldum’s work and facilities.",al={"plates of uldum","discs of uldum","uldum tablets"}}},ang={["race:Dwarf"]="As a dwarf pursuing your Titan heritage through the Explorers’ League, you can see Uldum’s colossal gates as one of Kalimdor’s greatest unsolved mysteries.",["faction:Alliance"]="Alliance scholars hope to reach the Titan secrets hidden in the southern mountains before a rival power does."},kw={"explorers' league","gates of uldum","plates of uldum","tanaris","titans","uldum"},rel={"zone:tanaris","topic:titan","topic:explorers-league","zone:ungoro","zone:silithus","topic:alliance"},src={"Uldum"}}
E["subzone:valley-of-the-watchers"] = {t="subzone",n="Valley of the Watchers",z="tanaris",s="At Tanaris’s southern edge, the sealed gate at the Valley of the Watchers keeps Uldum beyond reach. Stone sentinels and lumbering giants guard the ancient complex.",h="At Tanaris’s southern edge, the sealed gate at the Valley of the Watchers keeps Uldum beyond reach.",sec={{t="The Sealed Threshold",b="At the valley’s southern end, a massive stone gate bars the way. It is believed to guard Uldum, a subterranean facility of the enigmatic Titans. Dune Smasher mountain giants roam the dusty approach, keeping travelers, tomb robbers, and scholars from disturbing what lies beneath the sands. The valley marks Tanaris’s southern boundary, where shifting desert sands meet the continent’s mountainous edge.",sp=0}},faq={{q="What is behind the huge stone gate here?",a="The monumental doors lead into Uldum, an ancient subterranean facility built by the Titans before mortal history was recorded. The mechanisms remain sealed, and the complex’s contents and purpose are a mystery.",al={"gate of uldum","what is uldum","what is behind the door"}},{q="Can the gate to Uldum be opened?",a="No. The massive stone gates remain impassable. No mortal key, spell, or force known in Kalimdor can bypass the Titan safeguards that lock the complex shut.",al={"can you open the uldum gate","open uldum door","how to get into uldum"}},{q="Why are there giants wandering the valley?",a="Dune Smashers, colossal mountain giants, prowl the canyon floor. Drawn by the area’s potent earthen energy, they fiercely guard the approach and crush adventurers who stray too close to the southern cliffs.",al={"why are there dune smashers","valley giants","mountain giants tanaris"}},{q="Where in Tanaris is this valley located?",a="The valley lies at Tanaris’s far southern edge, south of Thistleshrub Valley and the gaping chasms of Southbreak Shores. It is carved into the towering southern mountain wall.",al={"valley of the watchers location","how to find valley of the watchers","where is the gate"}}},ang={["race:Dwarf"]="As a dwarf, you may see the massive stone gateway as another tantalizing clue in the search for your Titan creators."},kw={"dune smasher","kalimdor","tanaris","titan gate","titans","uldum","valley of the watchers"},rel={"zone:tanaris","subzone:uldum","topic:titan"},src={"Valley of the Watchers"}}
E["subzone:waterspring-field"] = {t="subzone",n="Waterspring Field",z="tanaris",s="At Waterspring Field in northern Tanaris, stolen pumps leave Gadgetzan without water.",h="At Waterspring Field in northern Tanaris, stolen pumps leave Gadgetzan without water.",sec={{t="A Stolen Oasis",b="Beneath the Tanaris sands, pumps draw water for Gadgetzan. The Steamwheedle Cartel goblins built them to supply their growing trade hub. Now the Wastewanders hold the field. These human outlaws and desert marauders guard the pumps, while Gadgetzan seeks hired blades to reclaim its water.",sp=0}},faq={{q="Who built the water towers here?",a="Gadgetzan's goblins built the towers to pump fresh water from deep underground reserves for their desert settlement and industry.",al={"who built this","goblin pumps","waterspring field towers"}},{q="Why are there bandits squatting at Waterspring Field?",a="The Wastewanders seized the pumps for themselves. Control of northern Tanaris's fresh water gives them power over nearby travelers and merchants.",al={"who are the bandits","wastewanders waterspring","why are wastewanders here"}},{q="Why doesn't Gadgetzan take the field back directly?",a="Gadgetzan hires adventurers to drive off the Wastewanders and recover its water pouches. Why its Bruisers do not enter the field is unknown.",al={"why gadgetzan no fight","goblin guards waterspring"}}},ang={["profession:Engineering"]="The goblins' pumping towers show how they draw water beneath the desert sands.",["race:Human"]="As a human, you share your race with many Wastewander bandits who occupy the towers. They left the northern kingdoms to make a harsh life in the desert."},kw={"gadgetzan","pumps","tanaris","wastewander","water pouches","water towers","waterspring field"},rel={"zone:tanaris","subzone:gadgetzan","topic:goblin"},src={"Waterspring Field"}}
E["subzone:wavestrider-beach"] = {t="subzone",n="Wavestrider Beach",z="tanaris",s="Burning ships still clash offshore from Wavestrider Beach on Tanaris's eastern coast. The shore stretches between Steamwheedle Port and Lost Rigger Cove, where crustaceans roam the sand and pirates command the nearby waters.",h="Burning ships still clash offshore from Wavestrider Beach on Tanaris's eastern coast.",sec={{t="A Treacherous Coastline",b="Steeljaw Snappers and Desert Crawlers scuttle over the baking sand. Wavestrider Beach follows eastern Tanaris from Steamwheedle Port in the north to the cliffs above Lost Rigger Cove. Offshore, burning vessels remain locked in combat. Their flames mark the violence that grips these pirate waters.",sp=0}},faq={{q="Where is Wavestrider Beach located?",a="Wavestrider Beach follows Tanaris's eastern coast, from Steamwheedle Port in the north to Lost Rigger Cove in the south.",al={"wavestrider beach location","where is wavestrider beach","wavestrider beach tanaris"}},{q="What creatures wander the sands here?",a="Desert Crawlers and Steeljaw Snappers roam the sand and surf.",al={"wavestrider beach mobs","crabs on wavestrider beach"}},{q="What are the burning ships visible offshore?",a="Two blazing vessels remain locked in combat offshore, reflecting the pirate activity around the Southsea Freebooters' hideouts.",al={"burning ships tanaris","ships on fire wavestrider beach"}},{q="Is Wavestrider Beach safe to travel through?",a="The shore is hazardous, with aggressive crabs and snapjaws by the water and Southsea pirates nearby. Unwary travelers can quickly be overwhelmed.",al={"is wavestrider beach dangerous","wavestrider beach safety"}}},kw={"coast","desert crawler","lost rigger cove","southsea","steamwheedle port","steeljaw snapper","tanaris","wavestrider beach"},rel={"zone:tanaris","subzone:steamwheedle-port","subzone:lost-rigger-cove"},src={"Wavestrider Beach"}}
E["subzone:zalashji-s-den"] = {t="subzone",n="Zalashji's Den",z="tanaris",s="Along Tanaris's eastern shore, Zalashji keeps to a lonely cave in the bluffs.",h="Along Tanaris's eastern shore, Zalashji keeps to a lonely cave in the bluffs.",sec={{t="A Solitary Lair",b="Zalashji lives alone in a cave on Tanaris's eastern shore. While naga across Kalimdor gather in war parties or coastal outposts, he has made his home in this isolated cavern, far from the region's settlements and desert ruins. Travelers following the surf should approach the cave mouth with caution. Why Zalashji chose this place is unknown.",sp=0}},faq={{q="Where is Zalashji's Den located?",a="Zalashji's Den lies in the rocky bluffs beside the ocean on Tanaris's eastern coast.",al={"zalashji location","where is zalashji den","zalashji cave"}},{q="Who is Zalashji?",a="Zalashji is a naga who lives alone in a coastal cave, apart from larger naga forces.",al={"who is zalashji","zalashji lore","what is zalashji"}},{q="Are there any quests associated with this cave?",a="No known tasks lead adventurers to Zalashji's Den. The cave remains a landmark for travelers along Tanaris's eastern shore.",al={"zalashjis den quests","is there a quest here","zalashji quest"}},{q="Why is a naga living alone in Tanaris?",a="Zalashji's motives are unknown. Naga usually gather near sunken ruins or in organized encampments, while he lives alone in a seaside cave.",al={"why is zalashji alone","naga in tanaris","why is zalashji here"}}},ang={["race:NightElf"]="As a night elf, the cursed and mutated naga along Kalimdor's shores recall the ancient Highborne and the Sundering."},kw={"cave","coast","naga","tanaris","zalashji","zalashji's den"},rel={"zone:tanaris","topic:naga"},src={"Zalashji's Den"}}
E["subzone:zul-farrak"] = {t="subzone",n="Zul'Farrak",z="tanaris",s="In northwestern Tanaris, Sandfury trolls hold Zul'Farrak behind guarded gates. Long cut off from their kin, they rely on dark voodoo and an army of the dead.",h="In northwestern Tanaris, Sandfury trolls hold Zul'Farrak behind guarded gates.",sec={{t="The Withered Remnant",b="Inside Zul'Farrak, Sandfury trolls endure the harsh wastes of Tanaris. Little survives of the city's distant past beyond troll legend. Across the desert, its people are known for their ruthlessness. Their priests dig up their own dead and raise them as a shambling army within the sun-bleached stronghold.",sp=0},{t="Legends of the Sand",b="In Gadgetzan, whispers tell of treasures and terrors behind Zul'Farrak's guarded gates. Troll lore speaks of Sul'thraze the Lasher, a legendary broadsword broken into two blades and hidden somewhere in the city. More troubling are the tales of Sergeant Bly and his band of mercenaries, captured after entering the city. Other rumors tell of Gahz'rilla, an ancient hydra demigod said to sleep in a sacred pool at the city's heart.",sp=0}},faq={{q="What tribe of trolls lives here?",a="The Sandfury tribe holds Zul'Farrak. Across Tanaris, these sand trolls are known for ruthlessness and dark mysticism.",al={"who lives in zulfarrak","sand troll tribe","what trolls are these"}},{q="Why are there so many zombies and graves inside?",a="Isolation and desperation have driven Sandfury witch doctors and shadow hunters to necromancy. They raise their fallen kin as undead thralls to strengthen their ranks and wage war across Tanaris.",al={"why undead in zulfarrak","sandfury zombies","troll graves"}},{q="What is the ancient monster sleeping in the city?",a="Gahz'rilla is the sleeping creature, a colossal hydra demigod. The Sandfury revere it in a deep, sacred pool, and rumors say a ritual instrument can call it forth.",al={"hydra boss","ancient creature in pool","gahzrilla"}},{q="What is Sul'thraze the Lasher?",a="Sul'thraze the Lasher is a legendary blade from ancient troll folklore. It saps the strength and will of those it strikes. Long ago, it was broken into Jang'thraze and Sang'thraze, both rumored to be inside the city.",al={"sandfury sword","sulthraze","zul farrak sword legend"}}},ang={["race:Troll"]="The Sandfury see the Darkspear as weak traitors allied with foreign conquerors. Darkspear elders such as Master Gadrin watch their corrupted desert cousins with grim concern.",["faction:Alliance"]="Human and dwarven explorers come from Gadgetzan to recover ancient relics or rescue missing mercenaries who vanished into the ruins."},kw={"gadgetzan","gahz'rilla","sand trolls","sandfury","sul'thraze","tanaris","zul'farrak"},rel={"zone:tanaris","subzone:gadgetzan","topic:troll","npc:master-gadrin","subzone:sen-jin-village","quest:1179","subzone:mirage-raceway","subzone:tabetha-s-farm"},src={"Zul'Farrak"}}
E["topic:arthas-menethil"] = {t="topic",n="Arthas Menethil",z="tanaris",s="As plague spreads through Lordaeron, Arthas Menethil leaves his place as its golden prince to hunt those behind it. A paladin of the Silver Hand, he claims Frostmourne in the frozen north, loses his soul, kills King Terenas, and turns against his homeland as the Scourge's champion.",h="As plague spreads through Lordaeron, Arthas Menethil leaves his place as its golden prince to hunt those...",sec={{t="The Golden Prince",b="Arthas grew up heir to King Terenas Menethil II, expected to uphold the ideals of the Alliance of Lordaeron. Muradin Bronzebeard trained him in combat, while Uther the Lightbringer guided him into the Order of the Silver Hand. High and low alike looked to him as humanity's future. Bold, skilled, and fiercely protective of his people, he fought Blackrock clan orc incursions and forest troll warbands. Beneath that bright name lived pride and a deep fear of failure.",sp=0},{t="The Scourge and the Culling",b="When the Plague of Undeath took hold in northern Lordaeron, Arthas rode with the sorceress Jaina Proudmoore to stop it spreading. They followed tainted grain from Brill to Andorhal, where Arthas killed the necromancer Kel'Thuzad and learned of the wider plot led by the dreadlord Mal'Ganis. At Stratholme, he found its people infected and chose to kill them before they could turn. He ordered the city's inhabitants slain. Horrified, Uther and Jaina left as Stratholme burned.",sp=1},{t="The Fall and Ascendance",b="Vengeance drove Arthas into Northrend's frozen wastes, where he met Muradin again and found Frostmourne. He took the runeblade despite its curse and defeated Mal'Ganis. But Frostmourne severed his soul and made him the Lich King's puppet.\n\nAs a Death Knight, Arthas returned to Capital City and killed King Terenas with the blade. Lordaeron was left to ash and undeath. He crushed the Silver Hand, besieged Dalaran, and cut through Quel'Thalas. Then he returned to the frozen throne and joined his dark master.",sp=2}},faq={{q="Who was Arthas Menethil before his fall?",a="Before his fall, Arthas was Crown Prince of Lordaeron and heir to King Terenas Menethil II. At nineteen, he joined the Knights of the Silver Hand and was counted among the realm's finest young paladins and swordsmen.",al={"arthas backstory","who was prince arthas","arthas prince of lordaeron"},it="identity"},{q="Why did Arthas purge Stratholme?",a="Stratholme's citizens had eaten grain tainted by the Plague of Undeath, and Arthas believed they would rise as mindless undead under Mal'Ganis's control. Convinced no mercy remained, he ordered the whole city slaughtered to prevent a Scourge army from rising.",al={"why did arthas cull stratholme","culling of stratholme","stratholme purge"},it="motive"},{q="How did Arthas become corrupted?",a="Arthas pursued Mal'Ganis to Northrend and claimed Frostmourne, a cursed runeblade forged by the Lich King. It drained his soul and bound his mind to Ner'zhul, making him the Scourge's vanguard death knight.",al={"how did arthas turn evil","arthas corruption","why did arthas become death knight"},it="history"},{q="What happened to King Terenas?",a="After Frostmourne claimed Arthas, he returned to Capital City as a conqueror come home. In the throne room, bells rang and rose petals fell as he drew the runeblade and drove it through his father, King Terenas.",al={"arthas kills father","death of king terenas","what happened to terenas"}},{q="What was Arthas's relationship with Jaina Proudmoore?",a="In their youth, Arthas and Jaina Proudmoore shared a romance, and she rode beside him as he fought the plague. His cruelty at Stratholme drove her away.",al={"arthas and jaina","did jaina love arthas","arthas romance"},it="ties"},{q="Where is Arthas right now?",a="Arthas now rules the Scourge from Northrend. After the defense of the frozen throne against the demon hunter Illidan, he ascended Icecrown, broke the Lich King's icy prison, and joined his essence with Ner'zhul.",al={"where is arthas","current status of arthas","is arthas alive"},it="today"},{q="Who leads Arthas Menethil?",a="Arthas serves the Lich King, the supreme master of the undead Scourge. Originally drawn to Northrend by vengeance, Arthas took up the cursed runeblade Frostmourne and sacrificed his own soul to its dark whispers. He surrendered his will entirely to become Ner'zhul's greatest death knight and champion, commanding armies in his master's name before traveling back to the Frozen Throne to merge directly with the Lich King himself.",al={"who does arthas serve","arthas leader","who controls arthas"},it="leader",add="b80d5fb0"},{q="Who is Arthas Menethil allied with?",a="Arthas commands the Scourge, a monstrous legion of mindless undead, necromancers, and horrors created by the Plague of Undeath. Among his chief lieutenants is the revived archlich Kel'Thuzad, whom Arthas once slew in life but later resurrected to oversee the ruins of Lordaeron. Arthas works solely on behalf of the Scourge and the Lich King, standing in bitter hostility against all living mortal nations across Azeroth.",al={"arthas allies","who does arthas work with","arthas faction"},it="allies",add="8c3ad81e"}},ang={["class:Paladin"]="For the Silver Hand, Arthas is its greatest tragedy and shame. His fall corrupted the ideals of justice and protection Uther tried to teach him.",["race:Human"]="Lordaeron's destruction split the human race in two. Refugees scattered across the globe, leaving Stormwind as humanity's last great seat of power.",["race:Undead"]="The Forsaken hate Arthas above all. Under Queen Sylvanas, they broke free of the dark prince's mental thrall and seek vengeance for their damnation.",["faction:Alliance"]="Arthas's treason cost the Alliance of Lordaeron its greatest kingdom, its capital, and the legendary paladin order that had anchored human faith."},kw={"arthas","frostmourne","lich king","lordaeron","menethil","scourge","stratholme","terenas"},rel={"topic:scourge","topic:lich-king","subzone:stratholme-classic","topic:terenas-menethil-ii","npc:jaina-proudmoore","topic:muradin-bronzebeard","topic:plague-of-undeath","topic:lordaeron"},src={"Arthas Menethil"}}
E["zone:tanaris"] = {t="zone",n="Tanaris",z="tanaris",s="In Tanaris, goblins trade beneath a fierce sun as dangers stir in the sands. Gadgetzan welcomes both the Alliance and the Horde, while Sandfury trolls, silithid, and ancient powers hold the dunes beyond.",h="In Tanaris, goblins trade beneath a fierce sun as dangers stir in the sands.",sec={{t="A Sea of Dunes",b="Tanaris lies beneath a fierce sun, and sand covers much of the land. Within Zul'Farrak's walls, the Sandfury trolls guard their isolated home. Hyenas, basilisks, and scorpids roam the desert floor. Tunnels wind beneath the hot earth.",sp=0},{t="Goblin Enterprise",b="Close to the goblins' island homeland of Kezan, Tanaris has become a trading ground for the Steamwheedle Cartel. From walled Gadgetzan to the docks of steamwheedle port, the goblins welcome coin from the Alliance and the Horde alike. Bruisers keep the peace, yet Southsea Freebooters still harass ships and dig sites along the coast.",sp=0},{t="Ancient Mysteries and Rising Perils",b="Tanaris holds powers older than mortal empires. In the east, the Caverns of Time belong to Nozdormu and the bronze dragonflight. Their drakes sometimes ride the desert thermals.\n\nFarther south, massive stone gates mark the titan complex of Uldum. Silithid swarms burrow outward from nests such as the Gaping Chasm and the Noxious Lair.",sp=0}},faq={{q="How do I travel to Tanaris?",a="Travel through Thousand Needles on foot to reach the Shimmering Flats. At the salt flats' southern end, a mountain pass leads down into Tanaris, with Gadgetzan's walls immediately in sight. Ships also sail from Powderfuse Port in the Riverglades to Steamwheedle Port on the eastern coast.",al={"how to get to tanaris","getting to tanaris","tanaris entrance"}},{q="Why is Gadgetzan neutral to both factions?",a="The Steamwheedle Cartel governs Gadgetzan and gives its allegiance to profit. To protect trade and draw commerce, the goblins enforce neutrality. Their bruisers attack anyone who starts a faction fight inside the city walls.",al={"why is gadgetzan neutral","can horde and alliance go to gadgetzan","goblin neutrality gadgetzan"}},{q="What is Zul'Farrak?",a="Zul'Farrak is the walled desert capital of the Sandfury trolls. Isolated in the desert, the tribe grew hostile to outsiders and guards its sacred pools and mysterious shrines.",al={"what is zulfarrak","who lives in zulfarrak","sand troll city"}},{q="What are the insect creatures nesting across the desert?",a="The insectlike beasts are silithid, monstrous burrowers that build vast hives such as the Gaping Chasm and the Noxious Lair. Their emergence in Tanaris unsettles Senior Surveyor Fizzledowser, recalling the ancient horrors of the War of the Shifting Sands.",al={"what are the bugs in tanaris","tanaris insect hives","silithid in tanaris"}},{q="What is behind the massive stone doors in the south?",a="The massive gates in the Valley of the Watchers mark the entrance to Uldum, a research facility held by the ancient titans. Colossal stone sentinels guard its sealed entrance, while scholars and goblins watch from afar.",al={"giant doors in south tanaris","ruins of uldum gates","titan gate tanaris"}},{q="Who dwells inside the Caverns of Time?",a="The Caverns of Time are the ancestral home of the bronze dragonflight and their aspect, Nozdormu. From hidden, winding depths, the timeless dragons watch the flow of history. They sometimes patrol the skies above the southern dunes.",al={"caverns of time lore","what is in caverns of time","dragons in tanaris"}}},ang={["profession:Mining"]="Tanaris's arid cliffs and rocky outcrops hold veins of Mithril, Truesilver, Iron, and Gold. Scattered deposits of Small Thorium lie deeper in the desert.",["profession:Herbalism"]="The dry heat of Tanaris nurtures Firebloom across the shifting dunes. Shaded ruins and damp oases shelter valuable Purple Lotus.",["race:Troll"]="As a troll, Zul'Farrak's Sandfury trolls show you ancient cousins who forged a brutal culture in the desert's isolation.",["faction:Alliance"]="As an Alliance traveler, you find no major Alliance strongholds between Dustwallow Marsh and Feralas. Neutral Gadgetzan gives you a vital staging post for travel across southern Kalimdor.",["faction:Horde"]="As a member of the Horde, you can use Gadgetzan as a trade hub linking routes from Freewind Post and Camp Mojache to the silithid-infested wastes of the far south."},kw={"caverns of time","desert","freebooters","gadgetzan","nozdormu","sandfury","silithid","steamwheedle","tanaris","uldum","zul'farrak"},rel={"subzone:gadgetzan","subzone:zul-farrak","subzone:caverns-of-time","subzone:steamwheedle-port","subzone:ruins-of-uldum","subzone:shimmering-flats","subzone:gaping-chasm","quest:887"},src={"Tanaris (Classic)","Tanaris"}}
